let currentLang = localStorage.getItem('app_lang') || 'ku_badini';
if (currentLang === 'ku') currentLang = 'ku_badini';

const TRANSLATIONS = {
    ku_badini: LANG_KU,
    ku_sorani: LANG_KU_SORANI,
    ar: LANG_AR,
    en: LANG_EN
};

function t(key, fallback = '') {
    if (!TRANSLATIONS[currentLang]) currentLang = 'ku_badini';
    let val = TRANSLATIONS[currentLang][key] || TRANSLATIONS['ku_badini'][key] || fallback || key;

    // Dynamically provide stage-specific specializations / subjects
    if (key === 'specializations') {
        const schedule = allSchedules[activeScheduleName];
        const schoolType = schedule?.settings?.milakData?.schoolType || 'سه‌ره‌تایی 1-6';
        if (typeof getStageSpecializations === 'function') {
            return getStageSpecializations(schoolType, currentLang);
        }
    }
    return val;
}

function translateStoredData(newLang) {
    if (!allSchedules) return;
    const targetLangObj = TRANSLATIONS[newLang];
    if (!targetLangObj) return;

    const translateValue = (val, arrayKey) => {
        if (!val) return val;
        for (const langKey in TRANSLATIONS) {
            const arr = TRANSLATIONS[langKey][arrayKey];
            if (arr) {
                const idx = arr.indexOf(val);
                if (idx !== -1) {
                    return targetLangObj[arrayKey][idx] || val;
                }
            }
        }
        return val;
    };

    for (const scheduleName in allSchedules) {
        const schedule = allSchedules[scheduleName];
        if (schedule.teachers) {
            schedule.teachers.forEach(teacher => {
                if (teacher.certificate) teacher.certificate = translateValue(teacher.certificate, 'certificates');
                if (teacher.jobTitle) teacher.jobTitle = translateValue(teacher.jobTitle, 'job_titles');
                if (teacher.specialization) teacher.specialization = translateValue(teacher.specialization, 'specializations');

                if (teacher.subjects) {
                    teacher.subjects.forEach(subj => {
                        if (subj.name) subj.name = translateValue(subj.name, 'specializations');
                    });
                }

                if (teacher.classes) {
                    for (const col in teacher.classes) {
                        const classObj = teacher.classes[col];
                        const newClassObj = {};
                        for (const subjName in classObj) {
                            const newSubjName = translateValue(subjName, 'specializations');
                            newClassObj[newSubjName] = classObj[subjName];
                        }
                        teacher.classes[col] = newClassObj;
                    }
                }
            });
        }

        if (schedule.settings && schedule.settings.workDays) {
            schedule.settings.workDays = schedule.settings.workDays.map(day => translateValue(day, 'work_days'));
        }

        if (schedule.timetables) {
            const newTimetables = {};
            for (const day in schedule.timetables) {
                const newDay = translateValue(day, 'work_days');
                newTimetables[newDay] = schedule.timetables[day];

                for (const col in newTimetables[newDay]) {
                    for (const period in newTimetables[newDay][col]) {
                        const cell = newTimetables[newDay][col][period];
                        if (cell && cell.subject) {
                            cell.subject = translateValue(cell.subject, 'specializations');
                        }
                    }
                }
            }
            schedule.timetables = newTimetables;
        }
    }
}

function changeLanguage(newLang) {
    if (!TRANSLATIONS[newLang]) return;

    translateStoredData(newLang);

    currentLang = newLang;
    localStorage.setItem('app_lang', currentLang);

    if (typeof saveData === 'function') {
        saveData(true);
    }

    document.documentElement.lang = currentLang;
    document.documentElement.dir = (currentLang === 'en') ? 'ltr' : 'rtl';

    applyTranslations();

    if (typeof renderApp === 'function') {
        const searchInput = document.getElementById('searchInput');
        renderApp(searchInput ? searchInput.value : '');
    }
}

function applyTranslations() {
    const langObj = TRANSLATIONS[currentLang] || TRANSLATIONS['ku_badini'];

    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (langObj[key]) {
            const icon = el.querySelector('i');
            if (icon) {
                const iconClone = icon.cloneNode(true);
                el.replaceChildren(iconClone, document.createTextNode(' ' + langObj[key]));
            } else {
                el.textContent = langObj[key];
            }
        }
    });

    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (langObj[key]) el.placeholder = langObj[key];
    });

    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        const key = el.getAttribute('data-i18n-title');
        if (langObj[key]) el.title = langObj[key];
    });

    const langSelect = document.getElementById('languageSelector');
    if (langSelect) langSelect.value = currentLang;
}

// --- Global Scope & Constants ---
let allSchedules = {};
let activeScheduleName = '';
let nextTeacherId = 1;
let teacherModalInstance = null;
let settingsModalInstance = null;
let tableViewMode = 'detailed'; // 'simple' or 'detailed'
let modalLayoutMode = 'vertical'; // 'vertical' or 'horizontal'
let currentEditingTeacher = null;

const PREDEFINED_SUBJECTS = ['ئاین', 'كوردی', 'عربی', 'ئینگلیزی', 'بیركاری', 'زانست', 'كومه‌لایه‌تی', 'كارامه‌ی', 'ده‌روونزانی', 'كومپیوته‌ر', 'هونه‌ر', 'وه‌رزش'];
const ALL_DAYS_KURDISH = ['شەمب', 'ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب', 'ئەینی'];

function getTeacherTotal(teacher) {
    return (teacher.classes ? Object.values(teacher.classes).reduce((sum, classObj) => {
        return sum + Object.values(classObj).reduce((value, periods) => value + (parseInt(periods, 10) || 0), 0);
    }, 0) : 0);
}

function sortDistributionTable(mode) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !Array.isArray(schedule.teachers)) return;
    const sortedTeachers = [...schedule.teachers];

    const compareText = (a, b, prop) => (a[prop] || '').localeCompare(b[prop] || '', 'ar', { sensitivity: 'base' });

    if (mode === 'name') {
        sortedTeachers.sort((a, b) => compareText(a, b, 'name'));
    } else if (mode === 'total') {
        sortedTeachers.sort((a, b) => getTeacherTotal(b) - getTeacherTotal(a));
    } else if (mode === 'certificate') {
        sortedTeachers.sort((a, b) => compareText(a, b, 'certificate'));
    } else if (mode === 'specialization') {
        sortedTeachers.sort((a, b) => compareText(a, b, 'specialization'));
    } else if (mode === 'jobTitle') {
        sortedTeachers.sort((a, b) => compareText(a, b, 'jobTitle'));
    }

    schedule.teachers = sortedTeachers;
    saveData();
    renderDistributionTable(searchInput?.value || '');

    const modeLabels = {
        name: 'ناڤ',
        total: 'کۆی',
        certificate: 'بروانامه',
        specialization: 'بسپور',
        jobTitle: 'نیشانا کاری'
    };
    showToast(`خشتە هاتە رێکخستن بە ${modeLabels[mode] || 'فرز'}.`);
}

function moveTeacherRow(teacherId, direction) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !Array.isArray(schedule.teachers)) return;

    const filter = searchInput ? searchInput.value.trim().toLowerCase() : '';
    const visibleTeachers = filter
        ? schedule.teachers.filter(t => (t.name || '').toLowerCase().includes(filter))
        : schedule.teachers;

    const visIndex = visibleTeachers.findIndex(t => String(t.id) === String(teacherId));
    if (visIndex === -1) return;

    const targetVisIndex = direction === 'up' ? visIndex - 1 : visIndex + 1;
    if (targetVisIndex < 0 || targetVisIndex >= visibleTeachers.length) return;

    const teacherA = visibleTeachers[visIndex];
    const teacherB = visibleTeachers[targetVisIndex];

    const mainIdxA = schedule.teachers.findIndex(t => t.id === teacherA.id);
    const mainIdxB = schedule.teachers.findIndex(t => t.id === teacherB.id);

    if (mainIdxA !== -1 && mainIdxB !== -1) {
        schedule.teachers[mainIdxA] = teacherB;
        schedule.teachers[mainIdxB] = teacherA;
        saveData(true);
        renderDistributionTable(searchInput ? searchInput.value : '');
        showToast('جهێ ماموستایی هاتە گوهورین', 'success');
    }
}

function changeTeacherPosition(teacherId, newPositionStr) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !Array.isArray(schedule.teachers)) return;

    let targetPos = parseInt(newPositionStr, 10);
    if (isNaN(targetPos)) return;

    const mainIndex = schedule.teachers.findIndex(t => String(t.id) === String(teacherId));
    if (mainIndex === -1) return;

    targetPos = Math.max(1, Math.min(schedule.teachers.length, targetPos));
    const newIndex = targetPos - 1;

    if (mainIndex === newIndex) return;

    const [movedTeacher] = schedule.teachers.splice(mainIndex, 1);
    schedule.teachers.splice(newIndex, 0, movedTeacher);

    saveData(true);
    renderDistributionTable(searchInput ? searchInput.value : '');
    showToast('جهێ ماموستایی هاتە گوهورین', 'success');
}

async function openReorderTeachersModal() {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !schedule.teachers || schedule.teachers.length === 0) {
        showToast('هیچ ماموستایەك نینە د ڤی خشتەیی دا.', 'warning');
        return;
    }

    const buildListHtml = () => {
        return schedule.teachers.map((t, idx) => `
            <div class="d-flex align-items-center justify-content-between p-2 mb-2 bg-body-tertiary border rounded-3 shadow-xs" data-teacher-id="${t.id}">
                <div class="d-flex align-items-center gap-2">
                    <span class="badge bg-primary rounded-circle p-2" style="width:28px; height:28px; display:inline-flex; align-items:center; justify-content:center;">${idx + 1}</span>
                    <i class="fas fa-grip-vertical text-muted drag-handle-modal me-1" style="cursor:grab;"></i>
                    <div class="text-start">
                        <strong class="text-dark-emphasis d-block">${t.name || ''}</strong>
                        <span class="small text-muted">${t.specialization || ''} ${t.certificate ? '(' + t.certificate + ')' : ''}</span>
                    </div>
                </div>
                <div class="d-flex align-items-center gap-2">
                    <label class="small text-muted mb-0">جهـ:</label>
                    <input type="number" class="form-control form-control-sm text-center fw-bold pos-input" style="width:65px;" min="1" max="${schedule.teachers.length}" value="${idx + 1}" data-teacher-id="${t.id}">
                    <div class="btn-group btn-group-sm">
                        <button type="button" class="btn btn-outline-secondary btn-sm" onclick="moveTeacherRow(${t.id}, 'up'); openReorderTeachersModal();" ${idx === 0 ? 'disabled' : ''}><i class="fas fa-chevron-up"></i></button>
                        <button type="button" class="btn btn-outline-secondary btn-sm" onclick="moveTeacherRow(${t.id}, 'down'); openReorderTeachersModal();" ${idx === schedule.teachers.length - 1 ? 'disabled' : ''}><i class="fas fa-chevron-down"></i></button>
                    </div>
                </div>
            </div>
        `).join('');
    };

    await Swal.fire({
        title: '<i class="fas fa-arrows-alt-v me-2 text-primary"></i>تعديل مكان المعلمين د جدول دا',
        html: `<div id="modal-teachers-reorder-container" style="max-height:60vh; overflow-y:auto;" class="pe-1">${buildListHtml()}</div>`,
        showCancelButton: false,
        confirmButtonText: t('btn_close') || 'داخستن',
        customClass: { popup: 'rounded-4' },
        didOpen: (modalEl) => {
            const container = modalEl.querySelector('#modal-teachers-reorder-container');
            if (container) {
                container.querySelectorAll('.pos-input').forEach(input => {
                    input.addEventListener('change', (e) => {
                        const tId = parseInt(e.target.dataset.teacherId, 10);
                        changeTeacherPosition(tId, e.target.value);
                        openReorderTeachersModal();
                    });
                });

                if (typeof Sortable !== 'undefined') {
                    new Sortable(container, {
                        animation: 150,
                        handle: '.drag-handle-modal',
                        onEnd: () => {
                            const newIds = Array.from(container.children)
                                .map(child => parseInt(child.dataset.teacherId, 10))
                                .filter(id => !isNaN(id));

                            const reordered = newIds
                                .map(id => schedule.teachers.find(t => t.id === id))
                                .filter(Boolean);

                            if (reordered.length === schedule.teachers.length) {
                                schedule.teachers = reordered;
                                saveData(true);
                                renderDistributionTable(searchInput ? searchInput.value : '');
                            }
                        }
                    });
                }
            }
        }
    });
}



// --- DOM Element Caching (will be initialized in DOMContentLoaded) ---
let searchInput, themeSwitcher, teacherModalEl, settingsModalEl;

// --- Advanced Security & Anti-Hacking Protection Utilities ---
function escapeHTML(str) {
    if (str === null || str === undefined) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

function sanitizeInputString(str) {
    if (typeof str !== 'string') return str;
    return str
        .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
        .replace(/javascript\s*:/gi, '')
        .replace(/data\s*:\s*text\/html/gi, '')
        .replace(/on\w+\s*=/gi, '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

function sanitizeObject(obj) {
    if (!obj || typeof obj !== 'object') return obj;
    if (Array.isArray(obj)) {
        return obj.map(sanitizeObject);
    }
    const cleanObj = {};
    for (const key of Object.keys(obj)) {
        // Anti-Prototype Pollution Protection
        if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue;
        const val = obj[key];
        if (typeof val === 'string') {
            cleanObj[key] = sanitizeInputString(val);
        } else if (typeof val === 'object' && val !== null) {
            cleanObj[key] = sanitizeObject(val);
        } else {
            cleanObj[key] = val;
        }
    }
    return cleanObj;
}

function validateAndSanitizeSchedules(rawData) {
    if (!rawData || typeof rawData !== 'object') return null;
    const cleanData = sanitizeObject(rawData);
    for (const sName in cleanData) {
        const sch = cleanData[sName];
        if (sch && typeof sch === 'object') {
            if (!Array.isArray(sch.teachers)) sch.teachers = [];
            if (!Array.isArray(sch.columns)) sch.columns = [];
            if (!sch.timetables || typeof sch.timetables !== 'object') sch.timetables = {};
            if (!sch.settings || typeof sch.settings !== 'object') {
                sch.settings = {
                    principalName: 'طاهر محمود محمد',
                    studentTableRows: 6,
                    leaveTableRows: 4,
                    studentTableData: [],
                    leaveTableData: [],
                    periodsPerDay: 7,
                    workDays: ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب']
                };
            }
            if (!sch.nisab || typeof sch.nisab !== 'object') sch.nisab = {};
            if (sch.settings && !sch.settings.milakData) sch.settings.milakData = {};
        }
    }
    return cleanData;
}

const showToast = (message, icon = 'success') => {
    Swal.mixin({
        toast: true, position: 'top-start', showConfirmButton: false, timer: 3000, timerProgressBar: true,
        didOpen: (toast) => { toast.onmouseenter = Swal.stopTimer; toast.onmouseleave = Swal.resumeTimer; }
    }).fire({ icon, title: escapeHTML(message) });
};

// --- Core Data Management & Device-Isolated Silent Auto-Backup ---
const IDB_NAME = 'MamostaTimetableDeviceDB';
const IDB_STORE = 'schedulesStore';

function getIDB() {
    return new Promise((resolve) => {
        if (!window.indexedDB) return resolve(null);
        const req = indexedDB.open(IDB_NAME, 1);
        req.onupgradeneeded = (e) => {
            const db = e.target.result;
            if (!db.objectStoreNames.contains(IDB_STORE)) {
                db.createObjectStore(IDB_STORE);
            }
        };
        req.onsuccess = (e) => resolve(e.target.result);
        req.onerror = () => resolve(null);
    });
}

async function saveToIDB(dataPayload) {
    try {
        const db = await getIDB();
        if (!db) return;
        const tx = db.transaction(IDB_STORE, 'readwrite');
        tx.objectStore(IDB_STORE).put(dataPayload, 'auto_backup');
    } catch (e) {
        console.warn('Auto IDB backup warning:', e);
    }
}

async function loadFromIDB() {
    try {
        const db = await getIDB();
        if (!db) return null;
        return new Promise((resolve) => {
            const tx = db.transaction(IDB_STORE, 'readonly');
            const req = tx.objectStore(IDB_STORE).get('auto_backup');
            req.onsuccess = () => resolve(req.result || null);
            req.onerror = () => resolve(null);
        });
    } catch (e) {
        return null;
    }
}

async function loadData() {
    let rawData = localStorage.getItem('allSchedules');
    activeScheduleName = localStorage.getItem('activeScheduleName') || '';

    if (rawData) {
        try {
            allSchedules = JSON.parse(rawData) || {};
        } catch (e) {
            allSchedules = {};
        }
    } else {
        allSchedules = {};
    }

    // Sanitize any empty or invalid keys from allSchedules
    if (typeof allSchedules === 'object' && allSchedules !== null) {
        for (const k of Object.keys(allSchedules)) {
            if (!k || k.trim() === '' || k === 'undefined' || k === 'null') {
                const oldObj = allSchedules[k];
                delete allSchedules[k];
                if (oldObj && ((oldObj.teachers && oldObj.teachers.length > 0) || (oldObj.columns && oldObj.columns.length > 0))) {
                    const fallbackKey = 'خشتێ سه‌ره‌كی';
                    if (!allSchedules[fallbackKey]) {
                        allSchedules[fallbackKey] = oldObj;
                    } else {
                        allSchedules[`خشتێ ${Object.keys(allSchedules).length + 1}`] = oldObj;
                    }
                }
            }
        }
    }

    // If localStorage was empty, attempt recovery from device IndexedDB backup
    if (!allSchedules || Object.keys(allSchedules).length === 0) {
        try {
            const idbData = await loadFromIDB();
            if (idbData && idbData.allSchedules && typeof idbData.allSchedules === 'object') {
                allSchedules = idbData.allSchedules;
                if (idbData.activeScheduleName && allSchedules[idbData.activeScheduleName]) {
                    activeScheduleName = idbData.activeScheduleName;
                }
            }
        } catch (e) {
            console.warn('IDB fallback error:', e);
        }
    }

    // Clean up again after IDB load
    if (typeof allSchedules === 'object' && allSchedules !== null) {
        for (const k of Object.keys(allSchedules)) {
            if (!k || k.trim() === '' || k === 'undefined' || k === 'null') {
                delete allSchedules[k];
            }
        }
    }

    if (!allSchedules || Object.keys(allSchedules).length === 0) {
        allSchedules = {};
        const defaultName = 'خشتێ سه‌ره‌كی';
        allSchedules[defaultName] = {
            columns: [],
            teachers: [],
            nisab: {},
            settings: { principalName: 'طاهر محمود محمد', studentTableRows: 6, leaveTableRows: 4, studentTableData: [], leaveTableData: [], periodsPerDay: 7, workDays: ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'] }
        };
        activeScheduleName = defaultName;
    }

    if (!activeScheduleName || !allSchedules[activeScheduleName]) {
        activeScheduleName = Object.keys(allSchedules)[0];
    }

    for (const scheduleName in allSchedules) {
        const schedule = allSchedules[scheduleName];
        schedule.nisab = schedule.nisab || {};
        if (!schedule.settings) {
            schedule.settings = { principalName: 'طاهر محمود محمد', studentTableRows: 6, leaveTableRows: 4, studentTableData: [], leaveTableData: [], periodsPerDay: 7, workDays: ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'] };
        } else {
            schedule.settings.studentTableData = schedule.settings.studentTableData || [];
            schedule.settings.leaveTableData = schedule.settings.leaveTableData || [];
            schedule.settings.periodsPerDay = schedule.settings.periodsPerDay || 7;
            schedule.settings.workDays = schedule.settings.workDays || ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
            schedule.settings.milakData = schedule.settings.milakData || {};
        }
        if (schedule.settings.principalName === 'مسعود لاوند تحلو') {
            schedule.settings.principalName = 'طاهر محمود محمد';
        }
    }
    saveData();
}

let _saveDataTimeout = null;
function saveData(immediate = false) {
    const doSave = () => {
        try {
            localStorage.setItem('allSchedules', JSON.stringify(allSchedules));
            localStorage.setItem('activeScheduleName', activeScheduleName);
            saveToIDB({ allSchedules, activeScheduleName });
        } catch (e) {
            console.error('saveData error', e);
        }
    };
    if (immediate) {
        if (_saveDataTimeout) clearTimeout(_saveDataTimeout);
        doSave();
        return;
    }
    if (_saveDataTimeout) clearTimeout(_saveDataTimeout);
    _saveDataTimeout = setTimeout(doSave, 150);
}

async function handleSaveLoad(action) {
    if (action === 'save') {
        const dataStr = JSON.stringify({ allSchedules, activeScheduleName }, null, 2);
        const blob = new Blob([dataStr], { type: 'application/json;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `schedules_backup_${new Date().toISOString().slice(0, 10)}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        showToast('زانیاری هاتنه‌ هیلان.');
    } else if (action === 'load') {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = '.json, application/json, text/plain';
        input.style.display = 'none';
        document.body.appendChild(input);

        input.onchange = e => {
            const file = e.target.files && e.target.files[0];
            if (!file) {
                if (document.body.contains(input)) document.body.removeChild(input);
                return;
            }

            const reader = new FileReader();
            reader.onload = event => {
                try {
                    let content = event.target.result;
                    if (typeof content === 'string') {
                        // Strip UTF-8 BOM if present
                        content = content.replace(/^\uFEFF/, '').trim();
                    }

                    let data;
                    try {
                        data = JSON.parse(content);
                    } catch (parseError) {
                        if (typeof LZString !== 'undefined') {
                            const decompressed = LZString.decompressFromBase64(content);
                            if (decompressed) {
                                data = JSON.parse(decompressed);
                            } else {
                                throw parseError;
                            }
                        } else {
                            throw parseError;
                        }
                    }

                    // Decompress if LZString stringified payload or cloud sync string format
                    if (typeof data === 'string') {
                        try {
                            data = JSON.parse(data);
                        } catch (_) {
                            if (typeof LZString !== 'undefined') {
                                const decompressed = LZString.decompressFromBase64(data);
                                if (decompressed) data = JSON.parse(decompressed);
                            }
                        }
                    }
                    if (data && data.data && typeof data.data === 'string' && typeof LZString !== 'undefined') {
                        const decompressed = LZString.decompressFromBase64(data.data);
                        if (decompressed) data = JSON.parse(decompressed);
                    }

                    let parsedSchedules = null;
                    let parsedActiveName = null;

                    if (data && typeof data === 'object') {
                        if (data.allSchedules && typeof data.allSchedules === 'object') {
                            parsedSchedules = data.allSchedules;
                            parsedActiveName = data.activeScheduleName || Object.keys(data.allSchedules)[0] || '';
                        } else if (Array.isArray(data)) {
                            parsedSchedules = {};
                            data.forEach((sch, idx) => {
                                const sName = sch.name || `خشتێ ${idx + 1}`;
                                parsedSchedules[sName] = sch;
                            });
                            parsedActiveName = Object.keys(parsedSchedules)[0] || '';
                        } else {
                            if (data.teachers || data.columns || data.timetables || data.settings) {
                                const sName = data.name || activeScheduleName || 'خشتێ هاوردەکری';
                                parsedSchedules = { ...allSchedules, [sName]: data };
                                parsedActiveName = sName;
                            } else {
                                const keys = Object.keys(data);
                                if (keys.length > 0 && typeof data[keys[0]] === 'object') {
                                    parsedSchedules = data;
                                    parsedActiveName = keys[0];
                                }
                            }
                        }
                    }

                    parsedSchedules = validateAndSanitizeSchedules(parsedSchedules);

                    if (parsedSchedules && parsedActiveName && parsedSchedules[parsedActiveName]) {
                        allSchedules = parsedSchedules;
                        activeScheduleName = parsedActiveName;
                        saveData();
                        renderApp();
                        showToast('زانیاری ب سەرکەفتن هاتنه‌ ڤه‌گه‌راندن.');
                    } else if (parsedSchedules && Object.keys(parsedSchedules).length > 0) {
                        allSchedules = parsedSchedules;
                        activeScheduleName = Object.keys(parsedSchedules)[0];
                        saveData();
                        renderApp();
                        showToast('زانیاری ب سەرکەفتن هاتنه‌ ڤه‌گه‌راندن.');
                    } else {
                        throw new Error('Data format did not match expected schedule structure.');
                    }
                } catch (err) {
                    console.error('Error importing JSON:', err);
                    let errStr = (err && err.message) ? err.message : String(err);
                    showToast('هەڵە: ' + errStr, 'error');
                } finally {
                    if (document.body.contains(input)) document.body.removeChild(input);
                }
            };

            reader.onerror = () => {
                showToast('خەلەتی د خویندنا فایلی دا پەیدا بوو.', 'error');
                if (document.body.contains(input)) document.body.removeChild(input);
            };

            reader.readAsText(file);
        };

        input.click();
    }
}

// --- App Rendering ---
function renderApp(filter = '') {
    if (!activeScheduleName || !allSchedules[activeScheduleName]) return;

    // Update the school stage selection dropdown label in the first tab if exists
    const stageBtn = document.getElementById('stageSelectorBtn');
    if (stageBtn) {
        const schedule = allSchedules[activeScheduleName];
        const md = schedule?.settings?.milakData || {};
        const schoolType = md.schoolType || 'سه‌ره‌تایی 1-6';
        let label = schoolType;
        if (schoolType === 'سه‌ره‌تایی 1-6' || schoolType === 'سه‌ره‌تایی') label = 'سه‌ره‌تایی (ابتدائي) ١-٦';
        else if (schoolType === 'ناڤه‌ندی 7-9' || schoolType === 'ناڤه‌ندی') label = 'ناڤه‌ندی (متوسط) ٧-٩';
        else if (schoolType === 'بنەڕەتی 1-9') label = 'بنەڕەتی (أساسي) ١-٩';
        else if (schoolType === 'ئامادەیی زانستی 10-12' || schoolType === 'ئامادەیی زانستی') label = 'ئامادەیی زانستی (إعدادي علمي) ١٠-١٢';
        else if (schoolType === 'ئامادەیی وێژەیی 10-12' || schoolType === 'ئامادەیی وێژەیی') label = 'ئامادەیی وێژەیی (إعدادي أدبي) ١٠-١٢';
        else if (schoolType === 'ئامادەیی زانستی و وێژەیی 10-12' || schoolType.includes('زانستی و وێژەیی') || schoolType.includes('علمي و أدبي')) label = 'ئامادەیی گشتی (علمي و أدبي) ١٠-١٢';
        else if (schoolType.includes('ئامادەیی') || schoolType.includes('ئامادهیی') || schoolType.includes('إعدادي')) label = 'ئامادەیی (إعدادي) ١٠-١٢';
        stageBtn.innerHTML = `<i class="fas fa-graduation-cap me-1"></i> ${label}`;
    }

    renderDistributionTable(filter || '');
    renderAdditionalTables();
    renderStatisticsTab();
    renderNisabTab();
    if (typeof initTimetableTab === 'function') initTimetableTab();

    // Also re-render Milak Tab if the container is currently visible
    const milakPane = document.getElementById('milak-tab-pane');
    if (milakPane && milakPane.classList.contains('show')) {
        renderMilakTab();
    }
}

// --- Distribution Tab Functions ---
function toggleTableView() {
    if (tableViewMode === 'simple') {
        tableViewMode = 'detailed';
        showToast(t('toast_view_detailed', 'دیمەنێ خشتەی هاتە گوهورین بۆ: ورده‌كاری'), 'info');
    } else if (tableViewMode === 'detailed') {
        tableViewMode = 'ledger';
        showToast(t('toast_view_ledger', 'دیمەنێ خشتەی هاتە گوهورین بۆ: میلاکی گشتی'), 'info');
    } else {
        tableViewMode = 'simple';
        showToast(t('toast_view_simple', 'دیمەنێ خشتەی هاتە گوهورین بۆ: سادە'), 'info');
    }
    renderDistributionTable(searchInput.value);
}

function renderDistributionTable(filter = '') {
    const schedule = allSchedules[activeScheduleName];
    const container = document.getElementById('tableContainer');
    nextTeacherId = schedule.teachers.length > 0 ? Math.max(...schedule.teachers.map(t => t.id || 0)) + 1 : 1;

    if (schedule.teachers.length === 0) {
        container.innerHTML = `<div class="empty-state"><i class="fas fa-user-plus fa-3x mb-3"></i><h5>${t('empty_table_title')}</h5><p>${t('empty_table_desc')}</p><button class="btn btn-primary" onclick="openTeacherModal()">${t('btn_teacher')}</button></div>`;
        return;
    }
    const filteredTeachers = schedule.teachers.filter(t => t.name.toLowerCase().includes(filter.toLowerCase()));

    if (tableViewMode === 'ledger') {
        const schoolType = schedule?.settings?.milakData?.schoolType || 'سه‌ره‌تایی 1-6';
        const stagePredefined = typeof getStageSpecializations === 'function' 
            ? getStageSpecializations(schoolType).filter(s => s !== 'یێن دی' && s !== 'شتی تر' && s !== 'أخرى' && s !== 'Other')
            : PREDEFINED_SUBJECTS;
        let rawSubjects = [...stagePredefined, ...schedule.teachers.flatMap(t => (t.subjects || []).map(s => s.name))];
        let allSubjects = [...new Set(rawSubjects.map(s => translateSubjectName(s)))];

        const subjectTotals = {};
        allSubjects.forEach(s => subjectTotals[s] = 0);
        let overallGrandTotal = 0;

        let tableHTML = `
            <h4 class="text-center d-none print-only mb-3">${t('tab_teacher_ledger')} - ${activeScheduleName}</h4>
            <table class="table table-bordered align-middle small text-center table-ledger" id="teachers-main-table" style="min-width: 1200px;">
                <thead>
                    <tr id="table-head-row">
                        <th rowspan="2" style="vertical-align: middle;">ژ</th>
                        <th rowspan="2" style="vertical-align: middle;">${t('col_teacher')}</th>
                        <th rowspan="2" style="vertical-align: middle;">${t('job_title_label')}</th>
                        <th rowspan="2" style="vertical-align: middle;">${t('gender_label')}</th>
                        <th rowspan="2" style="vertical-align: middle;">${t('certificate_label')}</th>
                        <th rowspan="2" style="vertical-align: middle;">${t('specialization_label')}</th>
                        <th rowspan="2" style="vertical-align: middle;">${t('status_label')}</th>
                        <th rowspan="2" style="vertical-align: middle;">${t('phone_label')}</th>
                        <th colspan="${allSubjects.length}" class="text-center" style="vertical-align: middle;">${t('nisab_quota')}</th>
                        <th rowspan="2" style="vertical-align: middle;">${t('grand_total')}</th>
                        <th rowspan="2" class="no-print" style="vertical-align: middle;">${t('col_actions')}</th>
                        <th rowspan="2" style="vertical-align: middle;">${t('notes_label')}</th>
                    </tr>
                    <tr>
                        ${allSubjects.map(sub => `<th>${sub}</th>`).join('')}
                    </tr>
                </thead>
                <tbody>
                    ${filteredTeachers.map((tItem, idx) => {
            let totalAssigned = 0;
            const subjectCells = allSubjects.map(sub => {
                let count = 0;
                schedule.columns.forEach(col => {
                    if (tItem.classes?.[col]) {
                        for (const [sName, sVal] of Object.entries(tItem.classes[col])) {
                            if (translateSubjectName(sName) === sub) {
                                count += Number(sVal || 0);
                            }
                        }
                    }
                });
                totalAssigned += count;
                subjectTotals[sub] += count;
                return `<td>${count > 0 ? count : ''}</td>`;
            }).join('');
            overallGrandTotal += totalAssigned;

            const isFirst = idx === 0;
            const isLast = idx === filteredTeachers.length - 1;
            const miniMoveControls = `<div class="d-inline-flex align-items-center justify-content-center gap-1"><i class="fas fa-grip-vertical drag-handle text-secondary me-1 no-print" style="cursor:grab;" title="راکێشە بۆ گوهورینا جهی"></i><span class="fw-bold px-1">${idx + 1}</span><div class="btn-group-vertical btn-group-sm no-print ms-1" style="scale: 0.8;"><button type="button" class="btn btn-xs btn-outline-secondary p-0 px-1" onclick="moveTeacherRow(${tItem.id}, 'up')" title="ببلندکرن" ${isFirst ? 'disabled' : ''}><i class="fas fa-chevron-up"></i></button><button type="button" class="btn btn-xs btn-outline-secondary p-0 px-1" onclick="moveTeacherRow(${tItem.id}, 'down')" title="ئینانە خوارێ" ${isLast ? 'disabled' : ''}><i class="fas fa-chevron-down"></i></button></div></div>`;

            return `
                            <tr data-teacher-id="${tItem.id}">
                                <td>${miniMoveControls}</td>
                                <td class="fw-bold text-start px-3 bg-white text-nowrap">${tItem.name}</td>
                                <td class="text-nowrap">${tItem.jobTitle || ''}</td>
                                <td class="text-nowrap">${tItem.gender || ''}</td>
                                <td class="text-nowrap">${tItem.certificate || ''}</td>
                                <td class="text-nowrap">${tItem.specialization || ''}</td>
                                <td class="text-nowrap">${tItem.status || ''}</td>
                                <td dir="ltr" class="text-nowrap">${tItem.phone || ''}</td>
                                ${subjectCells}
                                <td class="fw-bold bg-white text-primary">${totalAssigned}</td>
                                <td class="no-print text-nowrap">
                                    <div class="btn-group btn-group-sm" role="group">
                                        <button type="button" class="btn btn-sm btn-outline-primary" onclick="openTeacherModal(${tItem.id})"><i class="fas fa-edit"></i></button>
                                        <button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteTeacher(${tItem.id})"><i class="fas fa-trash"></i></button>
                                    </div>
                                </td>
                                <td></td>
                            </tr>
                        `;
        }).join('')}
                </tbody>
                <tfoot>
                    <tr class="fw-bold text-center table-light" style="font-size: 0.95rem;">
                        <td colspan="8" class="text-end pe-4 text-dark">سەرجەم</td>
                        ${allSubjects.map(sub => `<td class="text-primary">${subjectTotals[sub] > 0 ? subjectTotals[sub] : ''}</td>`).join('')}
                        <td class="text-primary">${overallGrandTotal > 0 ? overallGrandTotal : ''}</td>
                        <td class="no-print"></td>
                        <td></td>
                    </tr>
                </tfoot>
            </table>
        `;
        container.innerHTML = tableHTML;
    } else {
        const teacherRowsHtml = filteredTeachers.map((teacher, index) => {
            if (tableViewMode === 'detailed') {
                return renderTeacherTbodyDetailed(teacher, schedule.columns, index, filteredTeachers.length);
            } else {
                return renderTeacherRowSimple(teacher, schedule.columns, index, filteredTeachers.length);
            }
        }).join('');

        let tableHTML = `<h4 class="text-center d-none print-only mb-3">${t('tab_distribution')} - ${activeScheduleName}</h4><table class="table table-bordered table-hover" id="teachers-main-table">
                <thead class="table-light">
                    <tr id="table-head-row">
                        <th>${t('col_num')}</th><th>${t('col_teacher')}</th><th>${t('col_certificate')}</th><th>${t('col_job')}</th><th>${t('col_specialization')}</th><th>${t('col_subject')}</th>
                        ${schedule.columns.map(col => `<th class="column-header" data-col-name="${col}"><span style="cursor: pointer; text-decoration: underline; color: var(--bs-primary);" onclick="showClassSummary('${col}')" title="${t('class_summary_title')}">${col}</span><button class="btn-delete-col no-print" onclick="deleteColumn('${col}')" title="${t('btn_clear_data')}"><i class="fas fa-trash-alt"></i></button></th>`).join('')}
                        <th>${t('col_assigned_total')}</th><th class="no-print">${t('col_actions')}</th>
                    </tr>
                </thead>
                ${teacherRowsHtml}
                <tfoot>${renderFooter(schedule)}</tfoot>
            </table>`;
        container.innerHTML = tableHTML;
    }

    // Render Schedule Dropdown Menu & Label
    const dropdownMenu = document.getElementById('scheduleDropdownMenu');
    const dropdownLabel = document.getElementById('activeScheduleLabel');
    const scheduleKeys = Object.keys(allSchedules).filter(k => k && k.trim() !== '' && k !== 'undefined' && k !== 'null');
    
    if (scheduleKeys.length === 0) {
        const defName = 'خشتێ سه‌ره‌كی';
        allSchedules[defName] = { columns: [], teachers: [], nisab: {}, settings: {} };
        activeScheduleName = defName;
        scheduleKeys.push(defName);
    }
    if (!activeScheduleName || !allSchedules[activeScheduleName]) {
        activeScheduleName = scheduleKeys[0];
    }

    const isSystemDefault = (activeScheduleName === 'خشتێ سه‌ره‌كی' || activeScheduleName === 'الجدول الرئيسي' || activeScheduleName === 'Default Schedule' || activeScheduleName === 'خشتەی سەرەکی');
    const activeDisplayName = isSystemDefault ? (t('default_schedule_name') || activeScheduleName) : activeScheduleName;
    if (dropdownLabel) {
        dropdownLabel.textContent = activeDisplayName || 'خشتێ سه‌ره‌كی';
    }

    if (dropdownMenu) {
        let menuHTML = `<li class="px-3 py-1.5 text-muted small fw-bold border-bottom mb-1 d-flex align-items-center justify-content-between">
            <span><i class="fas fa-list-ul me-1"></i> هەمی خشتە (${scheduleKeys.length})</span>
        </li>`;
        
        scheduleKeys.forEach(name => {
            const sch = allSchedules[name] || {};
            const isDef = (name === 'خشتێ سه‌ره‌كی' || name === 'الجدول الرئيسي' || name === 'Default Schedule' || name === 'خشتەی سەرەکی');
            const dName = isDef ? (t('default_schedule_name') || name) : name;
            const isActive = (name === activeScheduleName);
            const teacherCount = (sch.teachers && sch.teachers.length) ? `${sch.teachers.length} ماموستا` : 'ڤالا';
            const colCount = (sch.columns && sch.columns.length) ? `${sch.columns.length} پۆل` : '';
            const countInfo = colCount ? `${teacherCount}، ${colCount}` : teacherCount;

            menuHTML += `
                <li>
                    <a class="dropdown-item d-flex align-items-center justify-content-between py-2 px-3 rounded-3 my-1 ${isActive ? 'active fw-bold' : ''}" 
                       href="javascript:void(0)" onclick="switchSchedule('${name.replace(/'/g, "\\'")}')" style="cursor: pointer;">
                        <span class="d-flex align-items-center gap-2">
                            <i class="${isActive ? 'fas fa-check-circle text-success' : 'far fa-calendar text-muted'}"></i>
                            <span class="fw-bold">${escapeHTML(dName || name)}</span>
                        </span>
                        <span class="badge ${isActive ? 'bg-light text-dark' : 'bg-secondary bg-opacity-10 text-secondary'} ms-2" style="font-size: 0.75rem;">${countInfo}</span>
                    </a>
                </li>
            `;
        });

        menuHTML += `
            <li><hr class="dropdown-divider my-1"></li>
            <li>
                <a class="dropdown-item text-primary fw-bold py-2 px-3 rounded-3" href="javascript:void(0)" onclick="createSchedule()" style="cursor: pointer;">
                    <i class="fas fa-plus-circle me-1"></i> دروستکرنا خشتەکێ نوی...
                </a>
            </li>
        `;
        dropdownMenu.innerHTML = menuHTML;
    }
    initSortable();
}

function switchSchedule(name) {
    if (!name || !allSchedules[name]) return;
    activeScheduleName = name;
    saveData(true);
    renderApp(searchInput ? searchInput.value : '');
    const activeTab = document.querySelector('#mainTabs .nav-link.active');
    if (activeTab) {
        if (activeTab.id === 'timetable-tab' && typeof initTimetableTab === 'function') initTimetableTab();
        else if (activeTab.id === 'substitute-tab' && typeof initSubstituteTab === 'function') initSubstituteTab();
        else if (activeTab.id === 'nisab-tab' && typeof initNisabTab === 'function') initNisabTab();
        else if (activeTab.id === 'statistics-tab' && typeof initStatisticsTab === 'function') initStatisticsTab();
        else if (activeTab.id === 'milak-tab' && typeof initMilakTab === 'function') initMilakTab();
        else if (activeTab.id === 'supervision-tab' && typeof initSupervisionTab === 'function') initSupervisionTab();
        else if (activeTab.id === 'class-mentors-tab' && typeof initClassMentorsTab === 'function') initClassMentorsTab();
    }
    showToast(`خشتێ چالاك: "${name}"`);
}
window.switchSchedule = switchSchedule;

function renderTeacherTbodyDetailed(teacher, columns, teacherIndex, totalCount = 1) {
    const numSubjects = teacher.subjects.length || 1;
    const rowspanAttr = `rowspan="${numSubjects}"`;
    const totalDistributed = columns.reduce((s, c) => s + (teacher.classes?.[c] ? Object.values(teacher.classes[c]).reduce((a, b) => a + parseInt(b, 10), 0) : 0), 0);

    const isFirst = teacherIndex === 0;
    const isLast = teacherIndex === totalCount - 1;
    const miniMoveControls = `<div class="d-inline-flex align-items-center justify-content-center gap-1"><i class="fas fa-grip-vertical drag-handle text-secondary me-1 no-print" style="cursor:grab;" title="راکێشە بۆ گوهورینا جهی"></i><span class="fw-bold px-1">${teacherIndex + 1}</span><div class="btn-group-vertical btn-group-sm no-print ms-1" style="scale: 0.8;"><button type="button" class="btn btn-xs btn-outline-secondary p-0 px-1" onclick="moveTeacherRow(${teacher.id}, 'up')" title="ببلندکرن" ${isFirst ? 'disabled' : ''}><i class="fas fa-chevron-up"></i></button><button type="button" class="btn btn-xs btn-outline-secondary p-0 px-1" onclick="moveTeacherRow(${teacher.id}, 'down')" title="ئینانە خوارێ" ${isLast ? 'disabled' : ''}><i class="fas fa-chevron-down"></i></button></div></div>`;

    if (teacher.subjects.length === 0) {
        return `<tbody data-teacher-id="${teacher.id}"><tr><td class="align-middle text-center user-select-none" style="white-space:nowrap;">${miniMoveControls}</td><td class="text-nowrap fw-bold">${teacher.name || ''}</td><td class="text-nowrap">${teacher.certificate || ''}</td><td class="text-nowrap">${teacher.jobTitle || ''}</td><td class="text-nowrap">${translateSubjectName(teacher.specialization) || ''}</td><td></td>${columns.map(() => `<td></td>`).join('')}<td><span class="badge bg-primary fs-6">0</span></td><td class="no-print text-nowrap"><div class="btn-group btn-group-sm" role="group"><button type="button" class="btn btn-sm btn-outline-primary" onclick="openTeacherModal(${teacher.id})"><i class="fas fa-edit"></i></button><button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteTeacher(${teacher.id})"><i class="fas fa-trash"></i></button></div></td></tr></tbody>`;
    }

    const subjectsHtml = teacher.subjects.map((subject, subjectIndex) => {
        let rowHtml = '<tr>';
        if (subjectIndex === 0) {
            rowHtml += `<td ${rowspanAttr} class="align-middle text-center user-select-none" style="white-space:nowrap;">${miniMoveControls}</td><td ${rowspanAttr} class="text-nowrap fw-bold">${teacher.name || ''}</td><td ${rowspanAttr} class="text-nowrap">${teacher.certificate || ''}</td><td ${rowspanAttr} class="text-nowrap">${teacher.jobTitle || ''}</td><td ${rowspanAttr} class="text-nowrap">${translateSubjectName(teacher.specialization) || ''}</td>`;
        }
        rowHtml += `<td>${translateSubjectName(subject.name)}: ${subject.periods}</td>`;
        columns.forEach(col => {
            const periodsInClass = teacher.classes?.[col]?.[subject.name] || '';
            rowHtml += `<td>${periodsInClass}</td>`;
        });
        if (subjectIndex === 0) {
            rowHtml += `<td ${rowspanAttr}><span class="badge bg-primary fs-6">${totalDistributed}</span></td><td ${rowspanAttr} class="no-print text-nowrap"><div class="btn-group btn-group-sm" role="group"><button type="button" class="btn btn-sm btn-outline-primary" onclick="openTeacherModal(${teacher.id})"><i class="fas fa-edit"></i></button><button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteTeacher(${teacher.id})"><i class="fas fa-trash"></i></button></div></td>`;
        }
        rowHtml += '</tr>';
        return rowHtml;
    }).join('');

    return `<tbody data-teacher-id="${teacher.id}">${subjectsHtml}</tbody>`;
}

function renderTeacherRowSimple(teacher, columns, index, totalCount = 1) {
    const distributed = columns.reduce((s, c) => s + (teacher.classes?.[c] ? Object.values(teacher.classes[c]).reduce((a, b) => a + parseInt(b, 10), 0) : 0), 0);
    const teacherSubjects = teacher.subjects.length > 0 ? teacher.subjects : [{ name: '', periods: '' }];

    const isFirst = index === 0;
    const isLast = index === totalCount - 1;
    const miniMoveControls = `<div class="d-inline-flex align-items-center justify-content-center gap-1"><i class="fas fa-grip-vertical drag-handle text-secondary me-1 no-print" style="cursor:grab;" title="راکێشە بۆ گوهورینا جهی"></i><span class="fw-bold px-1">${index + 1}</span><div class="btn-group-vertical btn-group-sm no-print ms-1" style="scale: 0.8;"><button type="button" class="btn btn-xs btn-outline-secondary p-0 px-1" onclick="moveTeacherRow(${teacher.id}, 'up')" title="ببلندکرن" ${isFirst ? 'disabled' : ''}><i class="fas fa-chevron-up"></i></button><button type="button" class="btn btn-xs btn-outline-secondary p-0 px-1" onclick="moveTeacherRow(${teacher.id}, 'down')" title="ئینانە خوارێ" ${isLast ? 'disabled' : ''}><i class="fas fa-chevron-down"></i></button></div></div>`;

    const subjectsCellHtml = teacherSubjects.map(s => `<div class="subject-entry">${s.name ? `${translateSubjectName(s.name)} (${s.periods})` : '&nbsp;'}</div>`).join('');

    const classDistributionCellsHtml = columns.map(col => {
        const cellContent = teacherSubjects.map(subject => {
            const periods = subject.name ? teacher.classes?.[col]?.[subject.name] : undefined;
            return `<div class="subject-entry">${periods ? `${translateSubjectName(subject.name)}: ${periods}` : '&nbsp;'}</div>`;
        }).join('');
        return `<td class="class-distribution-cell-padded">${cellContent}</td>`;
    }).join('');

    return `<tbody data-teacher-id="${teacher.id}"><tr>
            <td class="align-middle text-center user-select-none" style="white-space:nowrap;">${miniMoveControls}</td><td class="text-nowrap fw-bold">${teacher.name || ''}</td><td class="text-nowrap">${teacher.certificate || ''}</td><td class="text-nowrap">${teacher.jobTitle || ''}</td><td class="text-nowrap">${translateSubjectName(teacher.specialization) || ''}</td>
            <td class="subjects-cell-padded">${subjectsCellHtml}</td>
            ${classDistributionCellsHtml}
            <td><span class="badge bg-primary fs-6">${distributed}</span></td>
            <td class="no-print text-nowrap">
                <div class="btn-group btn-group-sm" role="group">
                    <button type="button" class="btn btn-sm btn-outline-primary" onclick="openTeacherModal(${teacher.id})"><i class="fas fa-edit"></i></button>
                    <button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteTeacher(${teacher.id})"><i class="fas fa-trash"></i></button>
                </div>
            </td>
        </tr></tbody>`;
}

function renderFooter(schedule) {
    if (schedule.columns.length === 0) return '';
    const totals = schedule.columns.map(c => schedule.teachers.reduce((s, t) => s + (t.classes?.[c] ? Object.values(t.classes[c]).reduce((a, b) => a + parseInt(b, 10), 0) : 0), 0));
    const grandTotal = totals.reduce((a, b) => a + b, 0);
    return `<tr class="table-light fw-bold"><td colspan="6" class="text-end">${t('grand_total')}</td>${totals.map(tVal => `<td>${tVal}</td>`).join('')}<td>${grandTotal}</td><td class="no-print"></td></tr>`;
}

function handleStudentCellInput(cell) {
    const row = cell.parentNode;
    const rowIndex = Array.from(row.parentNode.children).indexOf(row);
    const colIndex = Array.from(row.children).indexOf(cell);

    const boysCell = row.cells[3];
    const girlsCell = row.cells[4];
    const totalCell = row.cells[5];
    const boys = parseInt(boysCell.innerText, 10) || 0;
    const girls = parseInt(girlsCell.innerText, 10) || 0;
    totalCell.innerText = boys + girls;

    saveAdditionalTableData(cell, 'student', rowIndex, colIndex);
    saveAdditionalTableData(totalCell, 'student', rowIndex, 5);

    updateStudentTableFooter();
}

function updateStudentTableFooter() {
    const schedule = allSchedules[activeScheduleName];
    const data = schedule.settings.studentTableData || [];
    let totalBoys = 0, totalGirls = 0, grandTotal = 0;

    data.forEach(row => {
        totalBoys += parseInt(row[3], 10) || 0;
        totalGirls += parseInt(row[4], 10) || 0;
        // Recalculate grand total to ensure consistency
        grandTotal += (parseInt(row[3], 10) || 0) + (parseInt(row[4], 10) || 0);
    });

    document.getElementById('student-total-boys').innerText = totalBoys;
    document.getElementById('student-total-girls').innerText = totalGirls;
    document.getElementById('student-grand-total').innerText = grandTotal;
}

function renderAdditionalTables() {
    const container = document.getElementById('additionalTablesContainer');
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !schedule.settings) {
        container.innerHTML = ''; return;
    }
    const { principalName, studentTableRows, leaveTableRows, studentTableData = [], leaveTableData = [] } = schedule.settings;

    const studentHeaders = [t('col_num'), t('col_class'), t('col_section'), t('col_boys'), t('col_girls'), t('col_total_students')];
    let studentTableBody = '';
    for (let r = 0; r < studentTableRows; r++) {
        let rowHTML = '<tr>';
        for (let c = 0; c < studentHeaders.length; c++) {
            const content = (studentTableData[r] && studentTableData[r][c]) ? studentTableData[r][c] : '';
            if (c === 3 || c === 4) {
                rowHTML += `<td contenteditable="true" oninput="handleStudentCellInput(this)" onblur="saveAdditionalTableData(this, 'student', ${r}, ${c})">${content}</td>`;
            } else if (c === 5) {
                const boys = (studentTableData[r] && parseInt(studentTableData[r][3])) || 0;
                const girls = (studentTableData[r] && parseInt(studentTableData[r][4])) || 0;
                rowHTML += `<td>${boys + girls}</td>`;
            } else {
                rowHTML += `<td contenteditable="true" onblur="saveAdditionalTableData(this, 'student', ${r}, ${c})">${content}</td>`;
            }
        }
        rowHTML += `</tr>`;
        studentTableBody += rowHTML;
    }

    let totalBoys = 0, totalGirls = 0, grandTotal = 0;
    studentTableData.forEach(row => {
        totalBoys += parseInt(row[3], 10) || 0;
        totalGirls += parseInt(row[4], 10) || 0;
        grandTotal += (parseInt(row[3], 10) || 0) + (parseInt(row[4], 10) || 0);
    });

    const studentTable = `<table class="table table-bordered">
            <thead><tr>${studentHeaders.map(h => `<th>${h}</th>`).join('')}</tr></thead>
            <tbody>${studentTableBody}</tbody>
            <tfoot class="table-light fw-bold"><tr>
                <td colspan="3">${t('grand_total')}</td>
                <td id="student-total-boys">${totalBoys}</td>
                <td id="student-total-girls">${totalGirls}</td>
                <td id="student-grand-total">${grandTotal}</td>
            </tr></tfoot>
        </table>`;

    const leaveHeaders = [t('col_num'), t('col_teacher'), t('col_specialization'), t('col_leave_from'), t('col_leave_to'), t('col_leave_reason')];
    let leaveTable = `<table class="table table-bordered"><thead><tr>${leaveHeaders.map(h => `<th>${h}</th>`).join('')}</tr></thead><tbody>`;
    for (let r = 0; r < leaveTableRows; r++) {
        leaveTable += `<tr>`;
        for (let c = 0; c < leaveHeaders.length; c++) {
            const content = (leaveTableData[r] && leaveTableData[r][c]) ? leaveTableData[r][c] : '';
            leaveTable += `<td contenteditable="true" onblur="saveAdditionalTableData(this, 'leave', ${r}, ${c})">${content}</td>`;
        }
        leaveTable += `</tr>`;
    }
    leaveTable += `</tbody></table>`;

    const managerSignature = `<div class="text-center" id="managerSignature"><p class="mb-1"><strong>${t('signature_approved_by')}</strong></p><p class="fw-bold mb-0">${t('signature_principal')}</p><p>${principalName || '.......'}</p></div>`;

    container.innerHTML = `<div class="row mt-5">
            <div class="col-lg-7 mb-4 mb-lg-0">${studentTable}</div>
            <div class="col-lg-5 d-flex flex-column justify-content-between">${leaveTable}${managerSignature}</div>
        </div>`;
}

function saveAdditionalTableData(cell, tableType, rowIndex, colIndex) {
    const schedule = allSchedules[activeScheduleName];
    const dataKey = tableType === 'student' ? 'studentTableData' : 'leaveTableData';
    if (!schedule.settings[dataKey]) schedule.settings[dataKey] = [];
    while (schedule.settings[dataKey].length <= rowIndex) {
        schedule.settings[dataKey].push([]);
    }
    schedule.settings[dataKey][rowIndex][colIndex] = cell.innerText;
    saveData();
}

// --- Printing Functions ---
function getPrintStyleTemplate() {
    return `<style>
        body { font-family:"Noto Kufi Arabic",sans-serif; -webkit-print-color-adjust:exact!important; color-adjust:exact!important; print-color-adjust:exact!important; background-color:#fff; }
        .card { border: 1px solid #fce4d6 !important; border-radius: 8px !important; margin-bottom: 12px !important; background-color: #fff !important; box-shadow: none !important; page-break-inside: avoid; }
        .card-header { background-color: #fce4d6 !important; color: #000 !important; font-weight: bold !important; text-align: center !important; font-size: 0.8rem !important; padding: 4px 8px !important; border-bottom: 1px solid #fce4d6 !important; }
        .card-body { padding: 8px !important; }
        
        .page-break { page-break-before: always !important; break-before: page !important; }
        
        h3 { font-size: 11pt !important; font-weight: bold; margin-bottom: 8px !important; text-align: center; }
        .table { width:100%; border-collapse:collapse; font-size:7pt; table-layout:auto !important; margin-bottom: 0 !important; }
        .table:not(.preserve-table-styles) th, .table:not(.preserve-table-styles) td { border:1px solid #adb5bd!important; padding:3px 4px !important; text-align:center; white-space:nowrap !important; vertical-align:middle; font-size:7pt !important; background-color: transparent !important; }
        .table:not(.preserve-table-styles) thead th { background-color:#fce4d6!important; font-weight:bold; color:#000!important; border: 1px solid #adb5bd !important; }
        .table:not(.preserve-table-styles) .badge { background-color: transparent !important; color: #000 !important; border: none !important; padding: 0 !important; font-size: inherit !important; font-weight: bold !important; }
        .preserve-table-styles th, .preserve-table-styles td { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
        thead { display:table-header-group }
        tfoot { display:table-footer-group }
        hr { margin:2px 0!important; border-top:1px solid #ccc!important; }
        #additionalTablesContainer .table { margin-top:25px!important; font-size:8pt; table-layout:auto !important; zoom: 1; }
        #additionalTablesContainer .table td { height:24px; }
        #managerSignature { margin-top:30px; text-align:center; page-break-inside: avoid; }
        .print-footer { position:fixed; right:0; bottom:0; padding:3px 8px; font-size:7pt; color:#333; opacity:0.8; }
        @page { margin: 0.25cm !important; size: landscape; }
        
        /* Flex Grid Support for side-by-side columns in print */
        .row { display: flex !important; flex-wrap: wrap !important; margin-right: -6px !important; margin-left: -6px !important; page-break-inside: avoid !important; break-inside: avoid !important; }
        .col-lg-8, .col-md-7 { flex: 0 0 66.666667% !important; max-width: 66.666667% !important; padding: 0 6px !important; }
        .col-lg-4, .col-md-5 { flex: 0 0 33.333333% !important; max-width: 33.333333% !important; padding: 0 6px !important; }
        .col-md-6 { flex: 0 0 50% !important; max-width: 50% !important; padding: 0 6px !important; }
        .mb-3 { margin-bottom: 1rem !important; }
        
        /* Column Width Scaling for Print to fit A4 Portrait & Landscape */
        .col-seq { width: 22px !important; min-width: 22px !important; }
        .col-name { width: 110px !important; min-width: 110px !important; text-align: right !important; padding-right: 3px !important; }
        .col-job { width: 60px !important; min-width: 60px !important; }
        .col-gender { width: 25px !important; min-width: 25px !important; }
        .col-cert { width: 60px !important; min-width: 60px !important; }
        .col-spec { width: 65px !important; min-width: 65px !important; }
        .col-birth { width: 45px !important; min-width: 45px !important; }
        .col-phone { width: 75px !important; min-width: 75px !important; }
        .col-subject { width: 22px !important; min-width: 22px !important; }
        .col-total { width: 35px !important; min-width: 35px !important; }
        .col-notes { width: 70px !important; min-width: 70px !important; }
        .col-leave-type { width: 90px !important; min-width: 90px !important; }
        .col-leave-from { width: 35px !important; min-width: 35px !important; }
        .col-leave-to { width: 35px !important; min-width: 35px !important; }
        .col-admin-order { width: 110px !important; min-width: 110px !important; }
        
        /* Table Responsive and Preserve Styles */
        .table-responsive { overflow: visible !important; width: 100% !important; max-width: 100% !important; }
        .table.preserve-table-styles { border-collapse: collapse !important; border: 2px solid #000 !important; width: 100% !important; max-width: 100% !important; min-width: 0 !important; table-layout: fixed !important; margin: 0 auto !important; }
        .preserve-table-styles th, .preserve-table-styles td { border: 1px solid #000 !important; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; word-break: break-word !important; }
        .preserve-table-styles th:first-child, .preserve-table-styles td:first-child { border-right: 2.5px solid #000 !important; }
        .preserve-table-styles th:last-child, .preserve-table-styles td:last-child { border-left: 2.5px solid #000 !important; }

        .print-signature-left {
            float: left !important;
            width: 230px !important;
            max-width: 230px !important;
            text-align: center !important;
            direction: rtl !important;
            margin-left: 20px !important;
            margin-right: auto !important;
            margin-top: 15px !important;
            display: block !important;
            page-break-inside: avoid !important;
        }
        .print-signature-wrapper {
            width: 100% !important;
            display: block !important;
            clear: both !important;
            margin-top: 15px !important;
        }

        @media print {
            html, body {
                width: 100% !important;
                max-width: 100% !important;
                margin: 0 !important;
                padding: 0 !important;
                overflow: visible !important;
            }
            .table-responsive, .container, .container-fluid {
                width: 100% !important;
                max-width: 100% !important;
                overflow: visible !important;
                margin: 0 !important;
                padding: 0 !important;
            }
            .print-signature-left {
                float: left !important;
                width: 230px !important;
                max-width: 230px !important;
                margin-left: 20px !important;
                margin-right: auto !important;
                text-align: center !important;
                direction: rtl !important;
                display: block !important;
            }
            .table.preserve-table-styles {
                width: 100% !important;
                max-width: 100% !important;
                min-width: 0 !important;
                table-layout: fixed !important;
            }
        }

        /* Rotated Header Div Size inside Subject Columns */
        .col-subject div {
            width: 22px !important;
            font-size: 6.5pt !important;
            margin: 0 auto !important;
        }
    </style>`;
}

function buildStyledHtmlDocument(title, contentHTML, options = {}) {
    const orientation = options.orientation || 'landscape';
    const isWebExport = options.isWebExport || false;
    const orientationStyle = `<style>@page { size: ${orientation}; margin: 0.3cm; } @media print { body { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; } }</style>`;
    const fontAwesomeLink = `<link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" rel="stylesheet">`;
    const googleFontLink = `<link href="https://fonts.googleapis.com/css2?family=Noto+Kufi+Arabic:wght@400;600;700;800;900&display=swap" rel="stylesheet">`;
    const footerHTML = `<div class="print-footer">م: طاهر محمود محمد (07503727069)</div>`;
    const webClayStyle = `
    <style>
        :root {
            --clay-bg: #eef2f7;
            --clay-card-bg: #ffffff;
            --clay-shadow: 8px 8px 22px #d1d9e6, -8px -8px 22px #ffffff;
            --clay-pill-shadow: 4px 4px 10px #d1d9e6, -4px -4px 10px #ffffff;
            --clay-inset: inset 2px 2px 4px rgba(255,255,255,0.9), inset -2px -2px 4px rgba(0,0,0,0.03);
            --clay-pill-radius: 50rem;
            --clay-card-radius: 20px;
        }
        body {
            font-family: 'Noto Kufi Arabic', 'Segoe UI', Tahoma, sans-serif;
            background-color: #eef2f7;
            color: #334155;
            padding: 24px 16px;
            min-height: 100vh;
            -webkit-font-smoothing: antialiased;
        }
        .clay-card {
            background: #ffffff;
            border-radius: 20px;
            box-shadow: 8px 8px 22px #d1d9e6, -8px -8px 22px #ffffff;
            border: 1px solid rgba(255, 255, 255, 0.8) !important;
        }
        .clay-pill {
            border-radius: 50rem;
            box-shadow: 3px 3px 8px #d1d9e6, -3px -3px 8px #ffffff;
        }
        .table th, .table td { vertical-align: middle; }
        .print-footer {
            position: fixed;
            right: 14px;
            bottom: 12px;
            padding: 5px 14px;
            font-size: 8pt;
            font-weight: 700;
            color: #64748b;
            background: rgba(255, 255, 255, 0.92);
            backdrop-filter: blur(8px);
            border-radius: 30px;
            box-shadow: 3px 3px 10px rgba(0, 0, 0, 0.08);
            border: 1px solid rgba(255, 255, 255, 0.8);
            z-index: 999;
        }
        /* Smooth scrollbars */
        ::-webkit-scrollbar {
            width: 8px;
            height: 8px;
        }
        ::-webkit-scrollbar-track {
            background: #e2e8f0;
            border-radius: 8px;
        }
        ::-webkit-scrollbar-thumb {
            background: #94a3b8;
            border-radius: 8px;
        }
        ::-webkit-scrollbar-thumb:hover {
            background: #64748b;
        }
    </style>`;
    const baseStyle = isWebExport
        ? webClayStyle
        : getPrintStyleTemplate();
    return `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${title}</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet">${fontAwesomeLink}${googleFontLink}${baseStyle}${orientationStyle}</head><body dir="rtl">${contentHTML}${footerHTML}</body></html>`;
}

function sanitizeDownloadFileName(fileName) {
    if (!fileName) return 'general';
    return String(fileName).replace(/[<>:"/\\|?*]+/g, '_').replace(/\s+/g, '_');
}

function downloadHTMLFile(title, contentHTML, options = {}) {
    try {
        const filename = options.filename || `${sanitizeDownloadFileName(title)}.html`;
        const finalHTML = buildStyledHtmlDocument(title, contentHTML, options);
        const blob = new Blob([finalHTML], { type: 'text/html;charset=utf-8' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        setTimeout(() => URL.revokeObjectURL(link.href), 1000);
    } catch (err) {
        console.error('downloadHTMLFile error:', err);
    }
}

function printWithContent(title, contentHTML, options = {}) {
    const docHTML = buildStyledHtmlDocument(title, contentHTML, options);

    // 1. Close any active SweetAlert or modal to prevent stuck backdrops/focus traps
    try {
        if (typeof Swal !== 'undefined' && Swal.isVisible()) {
            Swal.close();
        }
    } catch (e) { }

    // 2. Comprehensive page restoration function to prevent any freezing after print dialog closes
    const restorePageInteraction = () => {
        try {
            // Restore pointer events across the whole document
            document.body.style.removeProperty('pointer-events');
            document.documentElement.style.removeProperty('pointer-events');

            // Remove any stuck modal backdrops or SweetAlert containers
            document.querySelectorAll('.modal-backdrop').forEach(bd => {
                try { bd.remove(); } catch (e) { }
            });
            document.querySelectorAll('.swal2-container').forEach(sc => {
                try {
                    if (!sc.classList.contains('swal2-top-end')) {
                        sc.remove();
                    }
                } catch (e) { }
            });

            // Clean modal and swal body classes
            document.body.classList.remove('modal-open', 'swal2-shown', 'swal2-height-auto');
            document.documentElement.classList.remove('swal2-shown', 'swal2-height-auto');

            // Clear any lingering aria-hidden attributes
            document.querySelectorAll('[aria-hidden="true"]').forEach(el => {
                if (el.id !== 'print_frame_fallback') {
                    el.removeAttribute('aria-hidden');
                }
            });

            // Force focus back to main window and blur any stuck active elements
            window.focus();
            if (document.activeElement && typeof document.activeElement.blur === 'function') {
                document.activeElement.blur();
            }
            if (document.body && typeof document.body.focus === 'function') {
                document.body.focus();
            }
        } catch (e) {
            console.error('Print interaction restore error:', e);
        }
    };

    // 3. Create or reuse persistent hidden iframe to avoid Chromium's DOM-destruction print bug
    let iframe = document.getElementById('print_frame_fallback');
    if (!iframe) {
        iframe = document.createElement('iframe');
        iframe.id = 'print_frame_fallback';
        iframe.style.position = 'fixed';
        iframe.style.right = '0';
        iframe.style.bottom = '0';
        iframe.style.width = '1px';
        iframe.style.height = '1px';
        iframe.style.opacity = '0.01';
        iframe.style.border = '0';
        iframe.style.pointerEvents = 'none';
        iframe.style.zIndex = '-9999';
        document.body.appendChild(iframe);
    }

    try {
        const pri = iframe.contentWindow;
        const doc = iframe.contentDocument || iframe.contentWindow.document;
        doc.open();
        doc.write(docHTML);
        doc.close();

        // Listen for afterprint on both iframe and top window
        if (pri) {
            pri.addEventListener('afterprint', restorePageInteraction, { once: true });
        }
        window.addEventListener('afterprint', restorePageInteraction, { once: true });

        // Fallback: whenever user returns to window (focus or mousemove), restore page
        const onReturnToWindow = () => {
            window.removeEventListener('focus', onReturnToWindow);
            window.removeEventListener('mousemove', onReturnToWindow);
            setTimeout(restorePageInteraction, 100);
        };
        window.addEventListener('focus', onReturnToWindow, { once: true });
        window.addEventListener('mousemove', onReturnToWindow, { once: true });

        // Trigger print after allowing styles and layout to settle
        setTimeout(() => {
            try {
                if (pri) {
                    pri.focus();
                    pri.print();
                }
            } catch (e) {
                console.error('Print trigger error:', e);
                restorePageInteraction();
            }
        }, 350);
    } catch (err) {
        console.error('Error during in-page printing execution:', err);
        try {
            const printWindow = window.open('', '_blank');
            if (printWindow) {
                printWindow.document.open();
                printWindow.document.write(docHTML);
                printWindow.document.close();
                printWindow.focus();
                printWindow.addEventListener('afterprint', () => {
                    try { printWindow.close(); } catch (e) { }
                    restorePageInteraction();
                }, { once: true });
                setTimeout(() => {
                    printWindow.print();
                }, 350);
            }
        } catch (popupErr) {
            console.error('Window open fallback failed:', popupErr);
        }
        restorePageInteraction();
    }
}

function getCurrentDistributionHTML() {
    const tableNode = document.querySelector('#tableContainer table');
    if (!tableNode) return null;
    const tableClone = tableNode.cloneNode(true);
    tableClone.querySelectorAll('.no-print').forEach(el => el.remove());
    return `<h3>${t('tab_distribution')} - ${activeScheduleName}</h3>${tableClone.outerHTML}`;
}

function getComprehensiveDistributionHTML() {
    const schedule = allSchedules[activeScheduleName];
    if (schedule.teachers.length === 0) return null;

    const columnTotals = schedule.columns.reduce((acc, col) => ({ ...acc, [col]: 0 }), {});
    let totalDistributedOfAll = 0, tbodyHTML = '';

    schedule.teachers.forEach((teacher, index) => {
        const numSubjects = teacher.subjects.length || 1;
        const rowspanAttr = `rowspan="${numSubjects}"`;
        const distributed = schedule.columns.reduce((s, c) => s + (teacher.classes?.[c] ? Object.values(teacher.classes[c]).reduce((a, b) => a + Number(b), 0) : 0), 0);
        totalDistributedOfAll += distributed;
        schedule.columns.forEach(col => { if (teacher.classes?.[col]) { columnTotals[col] += Object.values(teacher.classes[col]).reduce((a, b) => a + Number(b), 0); } });

        if (teacher.subjects.length > 0) {
            teacher.subjects.forEach((subject, subjectIndex) => {
                tbodyHTML += `<tr>`;
                if (subjectIndex === 0) {
                    tbodyHTML += `<td ${rowspanAttr}>${index + 1}</td><td ${rowspanAttr} style="white-space:normal; min-width:220px; width:220px;">${teacher.name || ''}</td><td ${rowspanAttr}>${teacher.certificate || ''}</td><td ${rowspanAttr}>${teacher.specialization || ''}</td>`;
                }
                tbodyHTML += `<td style="white-space:normal;">${subject.name}: ${subject.periods}</td>`;
                schedule.columns.forEach(c => { tbodyHTML += `<td style="white-space:normal;">${teacher.classes?.[c]?.[subject.name] || ''}</td>` });
                if (subjectIndex === 0) {
                    tbodyHTML += `<td ${rowspanAttr}>${distributed}</td>`;
                }
                tbodyHTML += `</tr>`;
            });
        } else {
            tbodyHTML += `<tr><td>${index + 1}</td><td style="white-space:normal; min-width:220px; width:220px;">${teacher.name || ''}</td><td>${teacher.certificate || ''}</td><td>${teacher.specialization || ''}</td><td></td>${schedule.columns.map(() => `<td></td>`).join('')}<td>${distributed}</td></tr>`;
        }
    });

    const tfootHTML = `<tfoot class="table-light fw-bold"><tr><td colspan="4" class="text-end">${t('grand_total')}</td><td></td>${schedule.columns.map(col => `<td>${columnTotals[col]}</td>`).join('')}<td>${totalDistributedOfAll}</td></tr></tfoot>`;
    const tableHTML = `<table class="table table-bordered table-striped"><thead class="table-light"><tr><th>${t('col_num')}</th><th style="min-width:220px; width:220px;">${t('col_teacher')}</th><th>${t('col_certificate')}</th><th>${t('col_specialization')}</th><th>${t('col_subject')}</th>${schedule.columns.map(c => `<th>${c}</th>`).join('')}<th>${t('col_assigned_total')}</th></tr></thead><tbody>${tbodyHTML}</tbody>${tfootHTML}</table>`;
    return `<h3>${t('download_comp_dist')} - ${activeScheduleName}</h3>${tableHTML}`;
}

function getSimpleDistributionHTML() {
    const schedule = allSchedules[activeScheduleName];
    if (schedule.teachers.length === 0) return null;

    let tableHTML = '<table class="table table-bordered table-striped">';
    tableHTML += `<thead class="table-light"><tr><th>${t('col_num')}</th><th>${t('col_teacher')}</th><th>${t('col_certificate')}</th><th>${t('col_job')}</th><th>${t('col_specialization')}</th><th>${t('col_subject')}</th>${schedule.columns.map(c => `<th>${c}</th>`).join('')}<th>${t('col_assigned_total')}</th></tr></thead><tbody>`;
    schedule.teachers.forEach((teacher, index) => {
        const distributed = schedule.columns.reduce((s, c) => s + (teacher.classes?.[c] ? Object.values(teacher.classes[c]).reduce((a, b) => a + Number(b), 0) : 0), 0);
        const subjects = teacher.subjects.map(s => `<div class="py-1">${s.name} (${s.periods})</div>`).join('<hr class="my-0" style="border-top: 1px solid #adb5bd !important;">');
        tableHTML += `<tr><td>${index + 1}</td><td>${teacher.name || ''}</td><td>${teacher.certificate || ''}</td><td>${teacher.jobTitle || ''}</td><td>${teacher.specialization || ''}</td><td style="white-space:normal;">${subjects}</td>`;
        schedule.columns.forEach(col => {
            let classContent = '';
            if (teacher.classes?.[col]) {
                classContent = Object.entries(teacher.classes[col]).map(([sub, p]) => `${sub}: ${p}`).join('<hr style="margin:2px 0">');
            }
            tableHTML += `<td>${classContent}</td>`;
        });
        tableHTML += `<td><span class="badge">${distributed}</span></td></tr>`;
    });
    const footerTotals = schedule.columns.map(c => schedule.teachers.reduce((s, t) => s + (t.classes?.[c] ? Object.values(t.classes[c]).reduce((a, b) => a + Number(b), 0) : 0), 0));
    tableHTML += `</tbody><tfoot class="table-light fw-bold"><tr><td colspan="6" class="text-end">کۆی گشتی:</td>${footerTotals.map(t => `<td>${t}</td>`).join('')}<td><span class="badge">${footerTotals.reduce((a, b) => a + b, 0)}</span></td></tr></tfoot></table>`;
    return `<h3>دابەشكرنا وانان (سادە) - ${activeScheduleName}</h3>${tableHTML}`;
}

function printAllTables() {
    const printAreaNode = document.querySelector(".print-area");
    if (!printAreaNode) { showToast('هیچ تشتەك نینە بۆ چاپکرنێ.', 'error'); return; }

    const printAreaClone = printAreaNode.cloneNode(true);
    // Hide only .no-print elements
    printAreaClone.querySelectorAll(".no-print").forEach(el => el.classList.add('d-none'));
    // Strip contenteditable without hiding the cells (they contain the user's data)
    printAreaClone.querySelectorAll("[contenteditable='true']").forEach(el => el.removeAttribute('contenteditable'));
    printWithContent(`چاپكرنا خشتان - ${activeScheduleName}`, printAreaClone.innerHTML);
}

