// --- Modal and Data Entry Functions (Refactored with Async/Await) ---
async function createSchedule() {
    const existingCount = Object.keys(allSchedules).length;
    const defaultSuggestedName = `خشتێ ${existingCount + 1}`;
    
    const { value: formValues, isConfirmed } = await Swal.fire({
        title: `<span style="font-size: 1.15rem; font-weight: 800;"><i class="fas fa-calendar-plus text-primary me-2"></i>${t('prompt_new_schedule_title') || 'دروستکرنا خشتەکێ نوی'}</span>`,
        html: `
            <div class="text-start" dir="rtl" style="font-size: 0.9rem;">
                <label class="form-label fw-bold mb-1">ناڤێ خشتێ نوی:</label>
                <input id="swalNewScheduleName" class="form-control mb-3" placeholder="ناڤێ خشتەی بنڤیسە..." value="${defaultSuggestedName}">
                
                <label class="form-label fw-bold mb-2">جۆرێ دروستکرنێ:</label>
                <div class="p-2 mb-2 rounded-3 border bg-light">
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="radio" name="newScheduleType" id="typeEmpty" value="empty" checked>
                        <label class="form-check-label fw-bold" for="typeEmpty">
                            <i class="fas fa-file text-secondary me-1"></i> خشتەیەکێ ڤالا و نوی (بدون ماموستا و پۆل)
                        </label>
                    </div>
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="newScheduleType" id="typeCopy" value="copy">
                        <label class="form-check-label fw-bold text-primary" for="typeCopy">
                            <i class="fas fa-copy text-primary me-1"></i> کۆپیکرنا هەمان ماموستا و پۆلان ژ خشتێ نوکە ("${activeScheduleName}")
                        </label>
                    </div>
                </div>
                <small class="text-muted"><i class="fas fa-info-circle me-1"></i> خشتێ بەرێ دێ مینیتە پاراستی و تو دشێی هەر دەم ب دەربازی ناڤبەرا وان ببیت.</small>
            </div>
        `,
        focusConfirm: false,
        showCancelButton: true,
        confirmButtonText: '<i class="fas fa-check me-1"></i> دروستکرن',
        cancelButtonText: t('cancel') || 'پاشگەزبوونەوە',
        preConfirm: () => {
            const nameInput = document.getElementById('swalNewScheduleName');
            const name = nameInput ? nameInput.value.trim() : '';
            if (!name) {
                Swal.showValidationMessage('تکایە ناڤێ خشتەی بنڤیسە!');
                return false;
            }
            if (allSchedules[name]) {
                Swal.showValidationMessage('ئەڤ ناڤە یێ هەی! تکایە ناڤەکێ دی هەلبژێرە.');
                return false;
            }
            const typeRadio = document.querySelector('input[name="newScheduleType"]:checked');
            const type = typeRadio ? typeRadio.value : 'empty';
            return { name, type };
        }
    });

    if (isConfirmed && formValues && formValues.name) {
        const scheduleName = formValues.name;
        const currentSch = allSchedules[activeScheduleName] || {};
        
        let newSchedule;
        if (formValues.type === 'copy') {
            newSchedule = {
                columns: JSON.parse(JSON.stringify(currentSch.columns || [])),
                teachers: JSON.parse(JSON.stringify(currentSch.teachers || [])),
                timetables: {},
                nisab: JSON.parse(JSON.stringify(currentSch.nisab || {})),
                settings: JSON.parse(JSON.stringify(currentSch.settings || { principalName: 'طاهر محمود محمد', studentTableRows: 6, leaveTableRows: 4, studentTableData: [], leaveTableData: [], periodsPerDay: 7, workDays: ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'] })),
                milak: JSON.parse(JSON.stringify(currentSch.milak || {}))
            };
        } else {
            newSchedule = {
                columns: [],
                teachers: [],
                timetables: {},
                nisab: {},
                settings: {
                    principalName: currentSch.settings?.principalName || 'طاهر محمود محمد',
                    studentTableRows: 6,
                    leaveTableRows: 4,
                    studentTableData: [],
                    leaveTableData: [],
                    periodsPerDay: 7,
                    workDays: ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب']
                },
                milak: {}
            };
        }

        allSchedules[scheduleName] = newSchedule;
        activeScheduleName = scheduleName;
        saveData(true);
        renderApp();
        showToast(`خشتێ نوی "${scheduleName}" هاتە دروستکرن و هەردو خشتە هاتنە پاراستن.`);
    }
}

async function renameActiveSchedule() {
    const oldName = activeScheduleName;
    if (!oldName) return;
    const { value: newName, isConfirmed } = await Swal.fire({
        title: t('prompt_rename_schedule_title'), input: 'text', inputValue: oldName, showCancelButton: true, confirmButtonText: t('confirm'), cancelButtonText: t('cancel'),
        inputValidator: v => !v ? '...' : (v !== oldName && allSchedules[v]) ? '...' : null
    });
    if (isConfirmed && newName && newName !== oldName) {
        allSchedules[newName] = allSchedules[oldName];
        delete allSchedules[oldName];
        activeScheduleName = newName;
        saveData();
        renderApp(searchInput.value);
        showToast(t('toast_schedule_renamed'));
    }
}

async function deleteActiveSchedule() {
    const scheduleKeys = Object.keys(allSchedules);
    if (scheduleKeys.length <= 1) {
        const { isConfirmed } = await Swal.fire({
            title: `${t('delete_schedule')} "${activeScheduleName}"`,
            text: 'ئەڤە داواین خشتەیە. ئایا تە دڤێت هەمی زانیاری و ماموستایێن ڤی خشتەیی پاقژ بکەی؟',
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: '#dc3545',
            cancelButtonColor: '#6c757d',
            confirmButtonText: 'بەلێ، هەمیێ پاقژ بکە',
            cancelButtonText: t('cancel')
        });
        if (isConfirmed) {
            const sch = allSchedules[activeScheduleName];
            sch.teachers = [];
            sch.columns = [];
            sch.timetables = {};
            sch.nisab = {};
            saveData(true);
            await deleteIDBBackup();
            renderApp();
            showToast(t('toast_schedule_deleted'));
        }
        return;
    }

    const { isConfirmed } = await Swal.fire({
        title: `${t('delete_schedule')} "${activeScheduleName}"`,
        icon: "warning",
        showCancelButton: true,
        confirmButtonColor: '#dc3545',
        cancelButtonColor: '#6c757d',
        confirmButtonText: t('btn_clear_data'),
        cancelButtonText: t('cancel')
    });
    if (isConfirmed) {
        delete allSchedules[activeScheduleName];
        activeScheduleName = Object.keys(allSchedules)[0];
        saveData(true);
        await deleteIDBBackup();
        renderApp();
        showToast(t('toast_schedule_deleted'));
    }
}

async function deleteIDBBackup() {
    try {
        const db = await getIDB();
        if (db) {
            return new Promise((resolve) => {
                const tx = db.transaction(IDB_STORE, 'readwrite');
                tx.objectStore(IDB_STORE).clear();
                tx.oncomplete = () => resolve(true);
                tx.onerror = () => resolve(false);
            });
        }
    } catch (e) {
        console.warn('IDB clear warning:', e);
    }
}

async function deleteAllData() {
    const { isConfirmed } = await Swal.fire({
        title: t('delete_all_data'),
        text: 'ئایا تۆ پشتراستی تە دڤێت هەمی خشتەیان و داتایێن ماموستایان ژێ ببەی؟ ئەڤ کارە هەمی داتایان ژێ دبه‌ت ب ته‌مامی!',
        icon: "warning",
        showCancelButton: true,
        confirmButtonColor: '#dc3545',
        cancelButtonColor: '#6c757d',
        confirmButtonText: 'بەلێ، هەمی داتایان ژێ ببە',
        cancelButtonText: t('cancel')
    });

    if (isConfirmed) {
        localStorage.clear();
        await deleteIDBBackup();
        const defaultName = activeScheduleName || 'خشتێ سه‌ره‌كی';
        allSchedules = {};
        allSchedules[defaultName] = {
            columns: [],
            teachers: [],
            nisab: {},
            timetables: {},
            settings: { principalName: 'طاهر محمود محمد', studentTableRows: 6, leaveTableRows: 4, studentTableData: [], leaveTableData: [], periodsPerDay: 7, workDays: ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'] }
        };
        activeScheduleName = defaultName;
        saveData(true);
        renderApp();
        showToast(t('toast_all_data_deleted'), "success");
    }
}

