        'زانست': { 1: 3, 2: 3, 3: 3, 4: 4, 5: 4, 6: 4 },
        'ئاین': { 1: 2, 2: 2, 3: 2, 4: 2, 5: 2, 6: 2 },
        'كومه‌لایه‌تی': { 4: 3, 5: 3, 6: 3 },
