function autoAssignAllSubstitutes(targetDayVal = null) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;

    const allTeachers = schedule.teachers || [];
    if (allTeachers.length === 0) {
        Swal.fire({ icon: 'warning', title: t('no_teachers_found') });
        return;
    }

    const subTeacherSelect = document.getElementById('substituteTeacherSelect');
    const rawAbsentName = subTeacherSelect ? subTeacherSelect.value : '';
    const absentTeacherName = (rawAbsentName && rawAbsentName !== 'all_teachers') ? rawAbsentName : '';
    const subDaySelect = document.getElementById('substituteDaySelect');
    const activeDay = targetDayVal !== null ? targetDayVal : (subDaySelect ? subDaySelect.value : 'all');

    const leaveNames = getLeaveTeacherNames(schedule);

    // 1. SECTION: 'grid' (خشتێ گشتی / مصفوفة المدرس المجاز)
    if (substituteSubViewMode === 'grid') {
        if (!absentTeacherName) {
            openSelectAbsentTeachersModal(activeDay);
            return;
        }
        const count = getTeacherLessonCount(absentTeacherName, schedule, activeDay);
        if (count === 0) {
            Swal.fire({
                icon: 'info',
                title: 'چ وانەیەک نییە',
                text: `مامۆستا (${absentTeacherName}) هیچ وانەیەکی لەم ڕۆژەدا نییە. تکایە مامۆستایەکی تر دیاربکە.`,
                confirmButtonText: 'هەڵبژاردنی مامۆستا'
            }).then(() => {
                openSelectAbsentTeachersModal(activeDay);
            });
            return;
        }
        executeBatchAutoAssignSubstitutes([absentTeacherName], activeDay);
        return;
    }

    // 2. SECTION: 'weekly_master_classes' / 'weekly_master' / 'vacancies_master' / 'master_teachers' / 'table'
    if (absentTeacherName) {
        const count = getTeacherLessonCount(absentTeacherName, schedule, activeDay);
        if (count > 0) {
            executeBatchAutoAssignSubstitutes([absentTeacherName], activeDay);
            return;
        }
    }

    // Check if there are teachers on leave who actually have lessons
    const validLeaveTeachersWithLessons = leaveNames.filter(name => getTeacherLessonCount(name, schedule, activeDay) > 0);

    if (validLeaveTeachersWithLessons.length > 0) {
        executeBatchAutoAssignSubstitutes(validLeaveTeachersWithLessons, activeDay);
    } else {
        // Open the selection dialog so the user can easily choose any teacher(s)
        openSelectAbsentTeachersModal(activeDay);
    }
}

function executeBatchAutoAssignSubstitutes(absentTeacherNames, selectedDayVal = 'all') {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !Array.isArray(absentTeacherNames) || absentTeacherNames.length === 0) return;

    // Filter out invalid names like 'all_teachers'
    const validAbsentNames = absentTeacherNames.filter(name => name && name !== 'all_teachers');
    if (validAbsentNames.length === 0) {
        openSelectAbsentTeachersModal(selectedDayVal);
        return;
    }

    schedule.substitutions = schedule.substitutions || {};
    // Strictly purge any administrative substitute assignments that may have existed
    Object.keys(schedule.substitutions).forEach(k => {
        const sub = schedule.substitutions[k];
        if (sub && isAdministrativeStaff(sub, schedule)) {
            delete schedule.substitutions[k];
        }
    });
    const defaultDaysKurdish = ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
    const days = (schedule.settings?.workDays && schedule.settings.workDays.length > 0)
        ? schedule.settings.workDays
        : defaultDaysKurdish;
    const periodsCount = schedule.settings?.periodsPerDay || 7;

    const daysToProcess = selectedDayVal === 'all'
        ? days.map((_, idx) => idx)
        : [parseInt(selectedDayVal, 10)].filter(idx => !isNaN(idx) && idx >= 0 && idx < days.length);

    // Collect all slots needing substitute grouped by (day, period)
    const slotsToAssign = [];
    const slotsByPeriod = {};

    validAbsentNames.forEach(absName => {
        daysToProcess.forEach(d => {
            for (let p = 1; p <= periodsCount; p++) {
                for (const cName of (schedule.columns || [])) {
                    const slotItem = schedule.timetables?.[cName]?.[d]?.[p];
                    if (slotItem && slotItem.teacher === absName) {
                        const slotObj = {
                            absentTeacherName: absName,
                            day: d,
                            period: p,
                            className: cName,
                            subject: slotItem.subject,
                            assignKey: `${absName}__${d}__${p}__${cName}`
                        };
                        slotsToAssign.push(slotObj);
                        const periodKey = `${d}_${p}`;
                        if (!slotsByPeriod[periodKey]) slotsByPeriod[periodKey] = [];
                        slotsByPeriod[periodKey].push(slotObj);
                    }
                }
            }
        });
    });

    if (slotsToAssign.length === 0) {
        Swal.fire({
            icon: 'info',
            title: 'چ وانەیەک نەدۆزرایەوە',
            text: 'مامۆستایانی دیاریکراو هیچ وانەیەکیان لە خشتەی پۆلەکاندا نییە بۆ دانانی بەدیل. دەتەوێت لە لیستەکە مامۆستای تر هەڵبژێریت؟',
            showCancelButton: true,
            confirmButtonText: 'هەڵبژاردنی مامۆستا',
            cancelButtonText: 'داخستن'
        }).then(r => {
            if (r.isConfirmed) {
                openSelectAbsentTeachersModal(selectedDayVal);
            }
        });
        return;
    }

    const assignedLog = [];
    const unassignedLog = [];
    const sessionDutiesCount = {};
    const absentSubPairsCount = {}; // Track substitutions per (absentTeacher -> substituteTeacher)

    // Process period by period with Maximum Bipartite Matching (Kuhn's Algorithm)
    Object.keys(slotsByPeriod).forEach(periodKey => {
        const periodSlots = slotsByPeriod[periodKey];
        if (!periodSlots || periodSlots.length === 0) return;

        const d = periodSlots[0].day;
        const p = periodSlots[0].period;
        const dayName = days[d];
        const rawDayName = ALL_DAYS_KURDISH[d] || dayName;

        const batchClassNamesAtPeriod = new Set(periodSlots.map(s => s.className));

        // Find eligible candidate teachers for this period
        const candidateTeachers = [];
        (schedule.teachers || []).forEach(cand => {
            // Strict Rule: Never assign administrative staff (مدير / معاون / مساعد)
            if (isAdministrativeStaff(cand, schedule)) return;

            // Strict Rule: Never assign on-leave teacher on this day
            if (isTeacherOnLeave(cand.name, d, schedule)) return;

            // Check if teacher is teaching a regular class at (d, p) that is NOT in this batch
            let busyInUnsubstitutedClass = false;
            for (const c of (schedule.columns || [])) {
                if (schedule.timetables?.[c]?.[d]?.[p]?.teacher === cand.name) {
                    if (!batchClassNamesAtPeriod.has(c)) {
                        busyInUnsubstitutedClass = true;
                        break;
                    }
                }
            }
            if (busyInUnsubstitutedClass) return;

            // Check if already assigned as substitute to a class at (d, p) outside this batch
            let busyInExternalSub = false;
            for (const [subKey, subTeacher] of Object.entries(schedule.substitutions || {})) {
                if (subTeacher === cand.name) {
                    const parts = subKey.split('__');
                    if (parts.length >= 4 && parseInt(parts[1], 10) === d && parseInt(parts[2], 10) === p) {
                        const subClass = parts[3];
                        if (!batchClassNamesAtPeriod.has(subClass)) {
                            busyInExternalSub = true;
                            break;
                        }
                    }
                }
            }
            if (busyInExternalSub) return;

            const offDays = cand.offDays || [];
            const isOffDay = offDays.includes(dayName) || offDays.includes(rawDayName);
            const blocked = cand.blockedPeriods || {};
            const blockedInDay = blocked[dayName] || blocked[rawDayName] || [];
            const isBlocked = Array.isArray(blockedInDay) && blockedInDay.includes(p);

            let baseDailyLoad = 0;
            for (let checkP = 1; checkP <= periodsCount; checkP++) {
                for (const c of (schedule.columns || [])) {
                    if (schedule.timetables?.[c]?.[d]?.[checkP]?.teacher === cand.name) {
                        baseDailyLoad++;
                        break;
                    }
                }
            }

            candidateTeachers.push({
                name: cand.name,
                specialization: cand.specialization || '',
                classes: cand.classes || {},
                isOffDay,
                isBlocked,
                baseDailyLoad,
                candObj: cand
            });
        });

        // Build preference list for each slot in this period
        const adj = [];
        for (let i = 0; i < periodSlots.length; i++) {
            const slot = periodSlots[i];
            const slotCands = [];

            candidateTeachers.forEach((cand, tIdx) => {
                // Hard Rule: Cannot substitute for own original class
                if (cand.name === slot.absentTeacherName) return;

                // Specialization match
                let isSameSpec = false;
                const candSpec = cand.specialization || '';
                if (candSpec && slot.subject) {
                    const cleanCandSpec = candSpec.trim();
                    const cleanSubj = slot.subject.trim();
                    if (cleanCandSpec === cleanSubj || (typeof SUBJECT_MAP !== 'undefined' && SUBJECT_MAP.hasOwnProperty(cleanCandSpec) && SUBJECT_MAP.hasOwnProperty(cleanSubj) && SUBJECT_MAP[cleanCandSpec] === SUBJECT_MAP[cleanSubj])) {
                        isSameSpec = true;
                    }
                }
                if (!isSameSpec && cand.classes) {
                    isSameSpec = Object.values(cand.classes).some(cls => cls && cls[slot.subject] > 0);
                }

                const pairKey = `${slot.absentTeacherName}__${cand.name}`;
                let previousAssignmentsForAbsent = absentSubPairsCount[pairKey] || 0;
                for (const [k, subName] of Object.entries(schedule.substitutions || {})) {
                    if (k.startsWith(`${slot.absentTeacherName}__`) && subName === cand.name) {
                        previousAssignmentsForAbsent++;
                    }
                }

                let score = 1000;
                if (isSameSpec) score += 300;
                if (!cand.isOffDay && !cand.isBlocked) score += 200;
                else if (!cand.isOffDay && cand.isBlocked) score += 50;

                // Heavy penalty for repeating the same substitute for the same absent teacher
                score -= (previousAssignmentsForAbsent * 600);

                // Load balance across teachers
                const duties = sessionDutiesCount[cand.name] || 0;
                score -= (duties * 120 + cand.baseDailyLoad * 10);
                score += Math.random() * 2;

                slotCands.push({
                    tIdx,
                    score,
                    isSameSpec
                });
            });

            slotCands.sort((a, b) => b.score - a.score);
            adj.push(slotCands);
        }

        // Kuhn's Maximum Bipartite Matching
        const match = new Array(candidateTeachers.length).fill(-1);
        const slotMatch = new Array(periodSlots.length).fill(-1);

        function dfsKuhn(u, visited) {
            for (const item of adj[u]) {
                const v = item.tIdx;
                if (visited[v]) continue;
                visited[v] = true;
                if (match[v] === -1 || dfsKuhn(match[v], visited)) {
                    match[v] = u;
                    slotMatch[u] = v;
                    return true;
                }
            }
            return false;
        }

        for (let i = 0; i < periodSlots.length; i++) {
            const visited = new Array(candidateTeachers.length).fill(false);
            dfsKuhn(i, visited);
        }

        // Apply matches
        for (let i = 0; i < periodSlots.length; i++) {
            const slot = periodSlots[i];
            const tIdx = slotMatch[i];
            if (tIdx !== -1) {
                const chosen = candidateTeachers[tIdx];
                schedule.substitutions[slot.assignKey] = chosen.name;
                sessionDutiesCount[chosen.name] = (sessionDutiesCount[chosen.name] || 0) + 1;
                const pairKey = `${slot.absentTeacherName}__${chosen.name}`;
                absentSubPairsCount[pairKey] = (absentSubPairsCount[pairKey] || 0) + 1;

                const candInfo = adj[i].find(item => item.tIdx === tIdx);
                assignedLog.push({
                    absentTeacherName: slot.absentTeacherName,
                    dayName,
                    period: p,
                    className: slot.className,
                    subject: slot.subject,
                    substituteName: chosen.name,
                    isSameSpec: candInfo ? candInfo.isSameSpec : false
                });
            } else {
                unassignedLog.push({
                    absentTeacherName: slot.absentTeacherName,
                    dayName,
                    period: p,
                    className: slot.className,
                    subject: slot.subject
                });
            }
        }
    });

    saveData();
    renderTimetableGrid();

    const assignedHtml = assignedLog.map(item => `
        <div class="d-flex justify-content-between align-items-center p-1.5 mb-1 rounded bg-light border shadow-xs" style="font-size: 0.74rem;">
            <div class="text-truncate me-2" style="min-width: 0;">
                <strong class="text-dark">${item.dayName} - ${t('period', 'وانە')} ${item.period}</strong> 
                <span class="text-primary">(${item.className} / ${translateSubjectName(item.subject)})</span>
                <span class="text-muted ms-1" style="font-size:0.66rem;">(م. ${item.absentTeacherName})</span>
            </div>
            <div class="text-success fw-bold text-nowrap d-flex align-items-center gap-1" style="font-size: 0.75rem;">
                <i class="fas fa-check-circle"></i>
                <span>${item.substituteName}</span>
                ${item.isSameSpec ? `<span class="badge bg-primary py-0.5 px-1 ms-0.5" style="font-size: 0.58rem;">${t('same_spec', '⭐ پسپۆڕی')}</span>` : ''}
            </div>
        </div>
    `).join('');

    const unassignedHtml = unassignedLog.length > 0 ? `
        <div class="alert alert-warning mt-1.5 mb-0 py-1.5 px-2" style="font-size: 0.72rem;">
            <div class="fw-bold mb-0.5"><i class="fas fa-exclamation-triangle me-1"></i>${t('sub_unassigned', 'وانەیێن بێ جهگر ماین')} (${unassignedLog.length}):</div>
            <ul class="mb-0 ps-3 small text-start">
                ${unassignedLog.map(u => `<li>${u.dayName} - ${t('period', 'وانە')} ${u.period} (${u.className} / ${translateSubjectName(u.subject)}) - م. ${u.absentTeacherName}</li>`).join('')}
            </ul>
        </div>
    ` : '';

    Swal.fire({
        icon: 'success',
        title: `<div style="font-size: 1rem; font-weight: bold; margin-top: -5px;">${t('sub_auto_done', 'توزيع تلقائي عادل وشامل لكافة الشواغر والأيام')}</div>`,
        html: `
            <div class="text-start" style="font-size: 0.75rem;">
                <div class="alert alert-success py-1 px-2.5 mb-1.5 small border-0 shadow-xs" style="font-size: 0.7rem; line-height: 1.3;">
                    <i class="fas fa-check-double me-1"></i>
                    <strong>${t('success', 'تم بنجاح')}:</strong> ${t('sub_auto_done_desc', 'تم تعيين البدلاء بدون أي تعارض (بناءً على الأكثر فراغاً في اليوم واستبعاد المدير والمعاونين).')}
                </div>
                <div class="mb-1 fw-bold text-dark" style="font-size: 0.75rem;">${t('sub_lessons_assigned', 'وانەیێن هاتینە دانان')} (${assignedLog.length} ${t('from', 'ژ')} ${slotsToAssign.length}):</div>
                <div style="max-height: 230px; overflow-y: auto; padding-right: 2px;">
                    ${assignedHtml || `<div class="text-muted text-center py-2">${t('sub_none_assigned', 'چ وانە نەهاتنە دانان')}</div>`}
                    ${unassignedHtml}
                </div>
            </div>
        `,
        width: '520px',
        padding: '0.75rem',
        confirmButtonText: t('ok', 'باشە'),
        customClass: {
            popup: 'rounded-4 shadow-lg border-0',
            icon: 'swal2-icon-compact',
            confirmButton: 'btn btn-sm btn-success fw-bold px-3 py-1 rounded-pill'
        }
    });
}

function autoAssignSubstitutes(targetDayVal = null) {
    const subTeacherSelect = document.getElementById('substituteTeacherSelect');
    const rawAbsentName = subTeacherSelect ? subTeacherSelect.value : '';
    const absentTeacherName = (rawAbsentName && rawAbsentName !== 'all_teachers') ? rawAbsentName : '';

    if (!absentTeacherName) {
        autoAssignAllSubstitutes(targetDayVal);
        return;
    }

    const schedule = allSchedules[activeScheduleName];
    const count = getTeacherLessonCount(absentTeacherName, schedule, targetDayVal || 'all');
    if (count === 0) {
        Swal.fire({
            icon: 'info',
            title: 'چ وانەیەک نییە',
            text: `مامۆستا (${absentTeacherName}) هیچ وانەیەکی لە خشتەدا نییە. تکایە لە لیستەکە مامۆستایەک دیاربکە.`,
            confirmButtonText: 'هەڵبژاردنی مامۆستا'
        }).then(() => {
            openSelectAbsentTeachersModal(targetDayVal || 'all');
        });
        return;
    }

    executeBatchAutoAssignSubstitutes([absentTeacherName], targetDayVal || 'all');
}

function clearSubstituteAssignments() {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !schedule.substitutions) return;

    const subTeacherSelect = document.getElementById('substituteTeacherSelect');
    const rawAbsentName = (subTeacherSelect ? subTeacherSelect.value : '') || '';
    const absentTeacherName = (rawAbsentName && rawAbsentName !== 'all_teachers') ? rawAbsentName : '';
    const isSpecificTeacher = !!absentTeacherName;

    const totalCount = Object.keys(schedule.substitutions).length;
    if (totalCount === 0) {
        showToast(t('sub_no_assignment_to_clear', 'هیچ جهگەرەک دیار نەکراوە بۆ پاقژکرن'), 'info');
        return;
    }

    let countForTeacher = 0;
    if (isSpecificTeacher) {
        const prefix = `${absentTeacherName}__`;
        countForTeacher = Object.keys(schedule.substitutions).filter(k => k.startsWith(prefix)).length;
    }

    Swal.fire({
        title: isSpecificTeacher ? t('sub_clear_teacher_title', `پاقژکرنا جهگرێن (${absentTeacherName})`) : t('sub_clear_all_title', 'پاقژکرنا هەموو جهگران (مسح الكل)'),
        text: isSpecificTeacher
            ? (countForTeacher > 0 ? `ئایا دڵنیای دتەوێت (${countForTeacher}) جهگرێن مامۆستا (${absentTeacherName}) بسڕیتەوە؟` : `هیچ جهگەرەک بۆ مامۆستا (${absentTeacherName}) دیارنەکراوە. ئایا دتەوێت تەواوی (${totalCount}) جهگرێن خشتەی بسڕیتەوە؟`)
            : `ئایا دڵنیای دتەوێت هەموو (${totalCount}) جهگرێن دیاریکراو لە تەواوی خشتەی دا بسڕیتەوە؟`,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        cancelButtonColor: '#6c757d',
        confirmButtonText: t('yes_delete', 'بەڵێ، بسڕەوە'),
        cancelButtonText: t('cancel', 'پاشگەزبوونەوە')
    }).then((result) => {
        if (result.isConfirmed) {
            let removedCount = 0;
            if (isSpecificTeacher && countForTeacher > 0) {
                const prefix = `${absentTeacherName}__`;
                for (const key of Object.keys(schedule.substitutions)) {
                    if (key.startsWith(prefix)) {
                        delete schedule.substitutions[key];
                        removedCount++;
                    }
                }
            } else {
                removedCount = Object.keys(schedule.substitutions).length;
                schedule.substitutions = {};
            }
            saveData();
            renderTimetableGrid();
            showToast(t('sub_cleared_count', `هەموو جهگران هاتنە پاقژکرن (${removedCount} وانە)`), 'info');
        }
    });
}

function setSubstituteAssignment(absentName, dayIndex, period, className, substituteName) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;
    if (typeof isAdministrativeStaff === 'function' && isAdministrativeStaff(substituteName, schedule)) {
        if (typeof Swal !== 'undefined') {
            Swal.fire({
                icon: 'warning',
                title: t('admin_staff_cannot_substitute', 'لا يمكن تعيين المدير أو المعاون كبديل'),
                text: t('admin_staff_cannot_substitute_desc', 'تم استبعاد الكادر الإداري (المدير والمعاونين) من جدول البدلاء، يرجى اختيار معلم فقط.')
            });
        } else {
            showToast('لا يمكن تعيين المدير أو المعاون كبديل للمعلم المجاز', 'warning');
        }
        return;
    }
    schedule.substitutions = schedule.substitutions || {};
    const key = `${absentName}__${dayIndex}__${period}__${className}`;
    schedule.substitutions[key] = substituteName;
    saveData();
    renderTimetableGrid();
    showToast(t('sub_assigned', 'هاتە دیاریکرن: {{sub}} وەک جهگرێ {{abs}}', { sub: substituteName, abs: absentName }), 'success');
}

function removeSubstituteAssignment(absentName, dayIndex, period, className) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !schedule.substitutions) return;
    const key = `${absentName}__${dayIndex}__${period}__${className}`;
    delete schedule.substitutions[key];
    saveData();
    renderTimetableGrid();
    showToast(t('cancel_substitute_assignment'), 'info');
}

function openSubstitutePickerModal(d, p, foundClass, foundSubject, targetTeacherName = null) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;

    const subTeacherSelect = document.getElementById('substituteTeacherSelect');
    let absentTeacherName = targetTeacherName || (subTeacherSelect ? subTeacherSelect.value : '') || '';
    if (!absentTeacherName || absentTeacherName === 'all_teachers') {
        const slotTeacher = schedule.timetables?.[foundClass]?.[d]?.[p]?.teacher || '';
        if (slotTeacher) {
            absentTeacherName = slotTeacher;
        } else {
            showToast(t('sub_select_absent_teacher', 'تکایە سەرەتا مامۆستایەکێ مۆڵەتپێدای دیاربکە'), 'warning');
            return;
        }
    }

    const defaultDaysKurdish = ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
    const savedDays = schedule.settings?.workDays || defaultDaysKurdish;
    const localizedWorkDays = typeof t === 'function' ? t('work_days') : defaultDaysKurdish;
    const days = savedDays.map((dStr) => {
        const indexInKurdish = typeof ALL_DAYS_KURDISH !== 'undefined' ? ALL_DAYS_KURDISH.indexOf(dStr) : -1;
        if (indexInKurdish !== -1 && Array.isArray(localizedWorkDays) && localizedWorkDays[indexInKurdish]) {
            return localizedWorkDays[indexInKurdish];
        }
        return dStr;
    });
    const periodsCount = schedule.settings?.periodsPerDay || schedule.periodsCount || 7;
    const dayName = days[d] || `رۆژ ${d + 1}`;

    const candidates = getSubstituteCandidates(schedule, absentTeacherName, d, p, foundSubject, days, periodsCount);

    let candidatesHtml = '';
    if (candidates.length === 0) {
        candidatesHtml = `
            <div class="text-center py-4 text-muted">
                <i class="fas fa-user-slash fa-2x text-secondary mb-2"></i>
                <div class="fw-bold">${typeof t === 'function' && t('no_substitute_found') ? t('no_substitute_found') : 'هیچ مامۆستایەک بەردەست نینە بۆ ڤێ وانەیێ!'}</div>
                <small class="text-muted">${t('sub_no_available_hint', 'هەمی مامۆستا وانە یان مۆڵەت یان رۆژا بێهنڤەدانێ نە.')}</small>
            </div>
        `;
    } else {
        candidatesHtml = `
            <div class="list-group list-group-flush text-start" style="max-height: 380px; overflow-y: auto;">
                ${candidates.map((cand) => `
                    <div class="list-group-item list-group-item-action p-2.5 d-flex justify-content-between align-items-center rounded-3 mb-1.5 border" style="background: #ffffff; transition: all 0.2s;">
                        <div class="d-flex align-items-center gap-2.5">
                            <span class="badge ${cand.isSameSpec ? 'bg-success' : 'bg-primary'} rounded-circle p-2" style="width: 34px; height: 34px; display: flex; align-items: center; justify-content: center;">
                                <i class="fas ${cand.isSameSpec ? 'fa-star' : 'fa-user'} text-white"></i>
                            </span>
                            <div>
                                <div class="fw-bold text-dark d-flex align-items-center gap-1.5">
                                    <span>${cand.name}</span>
                                    ${cand.isSameSpec ? `<span class="badge bg-success-subtle text-success border border-success-subtle py-0.5 px-1.5" style="font-size: 0.7rem;">${t('same_spec', '⭐ پسپۆڕی')}</span>` : ''}
                                    ${cand.isAdmin ? `<span class="badge bg-secondary-subtle text-secondary py-0.5 px-1.5" style="font-size: 0.7rem;">${t('admin_staff', 'کارگێڕی')}</span>` : ''}
                                </div>
                                <div class="small text-muted d-flex align-items-center gap-2 mt-0.5" style="font-size: 0.75rem;">
                                    <span><i class="fas fa-graduation-cap me-1 text-primary"></i>${translateSubjectName(cand.specialization) || t('teacher', 'مامۆستا')}</span>
                                    <span>•</span>
                                    <span><i class="fas fa-briefcase me-1 text-info"></i>${cand.dailyLoad} ${t('lessons_today', 'وانە ئەڤرۆ')}</span>
                                    <span>•</span>
                                    <span><i class="fas fa-calendar-alt me-1 text-secondary"></i>${cand.weeklyLoad} ${t('weekly_load', 'د حەفتیێ دا')}</span>
                                </div>
                            </div>
                        </div>
                        <button type="button" class="btn btn-sm btn-primary rounded-pill px-3 py-1.5 fw-bold shadow-xs d-flex align-items-center gap-1" onclick="Swal.close(); setSubstituteAssignment('${absentTeacherName.replace(/'/g, "\\'")}', ${d}, ${p}, '${foundClass.replace(/'/g, "\\'")}', '${cand.name.replace(/'/g, "\\'")}');">
                            <i class="fas fa-check"></i>
                            <span>${t('assign', 'دانان')}</span>
                        </button>
                    </div>
                `).join('')}
            </div>
        `;
    }

    Swal.fire({
        title: `<div class="d-flex align-items-center justify-content-center gap-2" style="font-size: 1.15rem; color: #1e293b;">
            <i class="fas fa-user-plus text-primary"></i>
            <span>${t('sub_assign_title', 'دیاریکردنا جهگر (تعيين بديل)')}</span>
        </div>`,
        html: `
            <div class="text-start mb-3 p-2.5 rounded-3 bg-light border d-flex justify-content-between align-items-center flex-wrap gap-2" style="font-size: 0.85rem;">
                <div>
                    <div><strong>${t('absent_teacher', 'مامۆستایێ مۆڵەتپێدای:')}</strong> <span class="text-danger fw-bold">${absentTeacherName}</span></div>
                    <div><strong>${t('lesson', 'وانە:')}</strong> <span class="text-primary fw-bold">${foundClass} - ${translateSubjectName(foundSubject)}</span></div>
                </div>
                <div class="text-end">
                    <span class="badge bg-dark">${dayName}</span>
                    <span class="badge bg-secondary">${t('period', 'وانا')} ${p}</span>
                </div>
            </div>
            ${candidatesHtml}
        `,
        showConfirmButton: false,
        showCloseButton: true,
        width: 600,
        customClass: {
            popup: 'rounded-4 shadow-lg border-0'
        }
    });
}

function autoAssignForTeacher(teacherName, dayVal = null) {
    executeBatchAutoAssignSubstitutes([teacherName], dayVal || 'all');
}

// Smart Teacher Name Formatter: shows first name, or first name + father's initial if there is another teacher with the same first name
function getSmartTeacherDisplayName(fullName, allTeachersList = null) {
    if (!fullName || typeof fullName !== 'string') return '';
    const cleanName = fullName.trim();
    if (!cleanName) return '';

    const parts = cleanName.split(/\s+/);
    const firstName = parts[0];
    if (parts.length === 1) return firstName;

    let teachers = allTeachersList;
    if (!teachers && typeof allSchedules !== 'undefined' && typeof activeScheduleName !== 'undefined' && allSchedules[activeScheduleName]) {
        teachers = allSchedules[activeScheduleName].teachers || [];
    }

    if (Array.isArray(teachers) && teachers.length > 0) {
        let countSameFirstName = 0;
        teachers.forEach(t => {
            const tFullName = (typeof t === 'string' ? t : (t?.name || '')).trim();
            if (tFullName) {
                const tFirst = tFullName.split(/\s+/)[0];
                if (tFirst.toLowerCase() === firstName.toLowerCase()) {
                    countSameFirstName++;
                }
            }
        });

        if (countSameFirstName > 1) {
            const fatherInitial = parts[1] ? parts[1].charAt(0) : '';
            return fatherInitial ? `${firstName} ${fatherInitial}.` : firstName;
        }
    }

    return firstName;
}

function getSubstituteCandidates(schedule, absentTeacherName, d, p, subject, daysList = null, periodsNum = null) {
    if (!schedule || !schedule.teachers) return [];
    const defaultDaysKurdish = ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
    const savedDays = schedule.settings?.workDays || defaultDaysKurdish;
    const localizedWorkDays = typeof t === 'function' ? t('work_days') : defaultDaysKurdish;
    const days = daysList || savedDays.map((dStr) => {
        const indexInKurdish = typeof ALL_DAYS_KURDISH !== 'undefined' ? ALL_DAYS_KURDISH.indexOf(dStr) : -1;
        if (indexInKurdish !== -1 && Array.isArray(localizedWorkDays) && localizedWorkDays[indexInKurdish]) {
            return localizedWorkDays[indexInKurdish];
        }
        return dStr;
    });
    const periodsCount = periodsNum || schedule.settings?.periodsPerDay || schedule.periodsCount || 7;

    const dayName = days[d] || '';
    const rawDayName = (typeof ALL_DAYS_KURDISH !== 'undefined' && ALL_DAYS_KURDISH[d]) ? ALL_DAYS_KURDISH[d] : dayName;
    const candidates = [];

    (schedule.teachers || []).forEach(cand => {
        if (absentTeacherName && cand.name === absentTeacherName) return;

        // Strict Rule: Never assign administrative staff (مدير / معاون / مساعد)
        if (typeof isAdministrativeStaff === 'function' && isAdministrativeStaff(cand, schedule)) return;

        // Strict Rule: Never assign a teacher if they are on leave on this day (لا يتم توزيع شاغر على معلم اذا كان مجاز)
        if (typeof isTeacherOnLeave === 'function' && isTeacherOnLeave(cand.name, d, schedule)) return;

        // Custom Teacher Selection Filter for Substitutes (تحديد المعلمين للبدلاء)
        const selectedSubIds = schedule.substituteSelectedTeacherIds;
        if (Array.isArray(selectedSubIds) && selectedSubIds.length > 0) {
            if (!selectedSubIds.includes(cand.id) && !selectedSubIds.includes(cand.name)) return;
        }

        // 1. Busy in any class?
        let isBusy = false;
        for (const c of (schedule.columns || [])) {
            if (schedule.timetables?.[c]?.[d]?.[p]?.teacher === cand.name) {
                isBusy = true;
                break;
            }
        }
        if (isBusy) return;

        // 1.5 Already assigned as substitute to another class at (d, p)?
        for (const [subKey, subTeacher] of Object.entries(schedule.substitutions || {})) {
            if (subTeacher === cand.name) {
                const parts = subKey.split('__');
                if (parts.length >= 4 && parseInt(parts[1], 10) === d && parseInt(parts[2], 10) === p) {
                    isBusy = true;
                    break;
                }
            }
        }
        if (isBusy) return;

        // 2. Off day?
        const offDays = cand.offDays || [];
        if (offDays.includes(dayName) || offDays.includes(rawDayName)) return;

        // 3. Blocked period?
        const blocked = cand.blockedPeriods || {};
        const blockedInDay = blocked[dayName] || blocked[rawDayName] || [];
        if (Array.isArray(blockedInDay) && blockedInDay.includes(p)) return;

        // Candidate is free!
        let isSameSpec = false;
        const candSpec = cand.specialization || '';
        if (candSpec && subject) {
            const cleanCandSpec = candSpec.trim();
            const cleanSubj = subject.trim();
            if (cleanCandSpec === cleanSubj) {
                isSameSpec = true;
            } else if (typeof SUBJECT_MAP !== 'undefined' && SUBJECT_MAP.hasOwnProperty(cleanCandSpec) && SUBJECT_MAP.hasOwnProperty(cleanSubj) && SUBJECT_MAP[cleanCandSpec] === SUBJECT_MAP[cleanSubj]) {
                isSameSpec = true;
            }
        }
        if (!isSameSpec && cand.classes) {
            isSameSpec = Object.values(cand.classes).some(cls => cls && cls[subject] > 0);
        }

        // Daily load
        let dailyLoad = 0;
        for (let checkP = 1; checkP <= periodsCount; checkP++) {
            for (const c of (schedule.columns || [])) {
                if (schedule.timetables?.[c]?.[d]?.[checkP]?.teacher === cand.name) {
                    dailyLoad++;
                    break;
                }
            }
        }

        // Total weekly load
        let weeklyLoad = 0;
        if (cand.classes) {
            Object.values(cand.classes).forEach(cls => {
                if (cls) Object.values(cls).forEach(v => weeklyLoad += (parseInt(v, 10) || 0));
            });
        }

        let timesAssignedForThisAbsent = 0;
        if (absentTeacherName && schedule.substitutions) {
            for (const [sKey, sTeacher] of Object.entries(schedule.substitutions)) {
                if (sTeacher === cand.name && sKey.startsWith(`${absentTeacherName}__`)) {
                    timesAssignedForThisAbsent++;
                }
            }
        }

        candidates.push({
            name: cand.name,
            specialization: cand.specialization || '',
            isSameSpec,
            isAdmin: false,
            dailyLoad,
            weeklyLoad,
            timesAssignedForThisAbsent
        });
    });

    // Sort candidates:
    // 1. Least times assigned for this absent teacher (to avoid repeating the same substitute unless necessary)
    // 2. Prioritize same specialization first
    // 3. Least classes today (most free periods)
    // 4. Weekly load
    candidates.sort((a, b) => {
        if (a.timesAssignedForThisAbsent !== b.timesAssignedForThisAbsent) return a.timesAssignedForThisAbsent - b.timesAssignedForThisAbsent;
        if (a.isSameSpec !== b.isSameSpec) return a.isSameSpec ? -1 : 1;
        if (a.dailyLoad !== b.dailyLoad) return a.dailyLoad - b.dailyLoad;
        return a.weeklyLoad - b.weeklyLoad;
    });

    return candidates;
}

// Open Modal to Select/Deselect Eligible Substitute Teachers (تحديد المعلمين للبدلاء)
function openSubstituteTeacherModal() {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;

    const isAr = (currentLang === 'ar');
    const allTeachers = Array.isArray(schedule.teachers) ? schedule.teachers : [];
    
    // Default: if substituteSelectedTeacherIds is not defined, select all non-admin, non-leave teachers
    let selectedIds;
    if (Array.isArray(schedule.substituteSelectedTeacherIds) && schedule.substituteSelectedTeacherIds.length > 0) {
        selectedIds = new Set(schedule.substituteSelectedTeacherIds);
    } else {
        selectedIds = new Set(
            allTeachers
                .filter(t => (typeof isAdministrativeStaff !== 'function' || !isAdministrativeStaff(t, schedule)) && !t.onLeave)
                .map(t => t.id)
        );
    }

    let listHTML = `<div class="text-start" style="max-height: 380px; overflow-y: auto;">
        <div class="d-flex justify-content-between align-items-center mb-2 pb-2 border-bottom flex-wrap gap-1">
            <span class="small fw-bold text-dark">${isAr ? 'اختر المعلمين المؤهلين كبدلاء:' : 'مامۆستایێن دەستنیشانکری بۆ جهگریێ هەڵبژێرە:'}</span>
            <div class="btn-group btn-group-sm">
                <button type="button" class="btn btn-xs btn-outline-primary" onclick="setAllSubstituteTeachers(true)">${isAr ? 'تحديد الكل' : 'هەمی'}</button>
                <button type="button" class="btn btn-xs btn-outline-secondary" onclick="setAllSubstituteTeachers(false)">${isAr ? 'إلغاء الكل' : 'چ نینە'}</button>
                <button type="button" class="btn btn-xs btn-outline-info" onclick="setSubstituteTeachersExcludeAdmin()">${isAr ? 'استثناء الإدارة' : 'لادانا کارگێریێ'}</button>
            </div>
        </div>
        <div class="row g-2" id="substituteTeachersCheckboxContainer">`;

    allTeachers.forEach(t => {
        const isChecked = selectedIds.has(t.id);
        const isHead = typeof isAdministrativeStaff === 'function' ? isAdministrativeStaff(t, schedule) : false;
        const badgeRole = isHead ? `<span class="badge bg-warning-subtle text-dark border ms-1" style="font-size:0.65rem;">${t.jobTitle || (isAr ? 'إدارة' : 'کارگێری')}</span>` : '';
        const badgeLeave = t.onLeave ? `<span class="badge bg-danger-subtle text-danger border ms-1" style="font-size:0.65rem;">${isAr ? 'مجاز' : 'مۆڵەت'}</span>` : '';

        listHTML += `
        <div class="col-12 col-md-6">
            <div class="form-check p-2 rounded border bg-light d-flex align-items-center gap-2">
                <input class="form-check-input ms-0 me-2 sub-cand-check" type="checkbox" value="${t.id}" id="chkSubCand_${t.id}" ${isChecked ? 'checked' : ''} style="cursor: pointer;">
                <label class="form-check-label text-dark fw-bold mb-0 w-100" for="chkSubCand_${t.id}" style="cursor: pointer; font-size: 0.82rem;">
                    ${t.name} ${badgeRole} ${badgeLeave}
                    <div class="text-muted fw-normal" style="font-size: 0.7rem;">${translateSubjectName(t.specialization || '')}</div>
                </label>
            </div>
        </div>`;
    });

    listHTML += `</div></div>`;

    Swal.fire({
        title: isAr ? 'تحديد المعلمين المرشحين للبدلاء' : 'دەستنیشانکرنا مامۆستایێن جهگر',
        html: listHTML,
        width: '600px',
        showCancelButton: true,
        confirmButtonText: isAr ? 'حفظ التحديد' : 'پاراستن',
        cancelButtonText: isAr ? 'إلغاء' : 'پاشگەزبوون',
        confirmButtonColor: '#198754',
        cancelButtonColor: '#6c757d',
        didOpen: () => {
            window.setAllSubstituteTeachers = function(check) {
                document.querySelectorAll('.sub-cand-check').forEach(chk => chk.checked = check);
            };
            window.setSubstituteTeachersExcludeAdmin = function() {
                allTeachers.forEach(t => {
                    const chk = document.getElementById(`chkSubCand_${t.id}`);
                    if (!chk) return;
                    const isHead = typeof isAdministrativeStaff === 'function' ? isAdministrativeStaff(t, schedule) : false;
                    chk.checked = (!t.onLeave && !isHead);
                });
            };
        }
    }).then(result => {
        if (result.isConfirmed) {
            const checkedBoxes = document.querySelectorAll('.sub-cand-check:checked');
            const newIds = Array.from(checkedBoxes).map(cb => Number(cb.value));
            schedule.substituteSelectedTeacherIds = newIds;
            if (typeof saveData === 'function') saveData();
            renderSubstituteTab();
            showToast(isAr ? `تم حفظ تحديد ${newIds.length} معلماً للبدلاء.` : `هەلبژارتنا ${newIds.length} ماموستایان بۆ جهگریێ هاتە پاراستن.`, 'success');
        }
    });
}
window.openSubstituteTeacherModal = openSubstituteTeacherModal;

let substituteSubViewMode = 'weekly_master'; // 'weekly_master' | 'weekly_master_classes' | 'vacancies_master' | 'grid' | 'master_teachers' | 'table'

function switchSubstituteSubView(viewMode) {
    substituteSubViewMode = viewMode;
    const activeTab = document.querySelector('#mainTabs .nav-link.active');
    if (activeTab && activeTab.id === 'substitute-tab') {
        renderSubstituteTab();
    } else {
        renderTimetableGrid();
    }
}
window.switchSubstituteSubView = switchSubstituteSubView;

function initSubstituteTab() {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;
    populateSubstituteControls();
    renderSubstituteTab();
}
window.initSubstituteTab = initSubstituteTab;

function populateSubstituteControls() {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;
    const subTeacherSelect = document.getElementById('substituteTeacherSelect');
    const subDaySelect = document.getElementById('substituteDaySelect');

    if (subTeacherSelect) {
        const curVal = subTeacherSelect.value;
        const allTeachersText = (typeof t === 'function' ? t('all_teachers') : 'هەمی مامۆستا') || 'هەمی مامۆستا';
        subTeacherSelect.innerHTML = `<option value="all_teachers">${allTeachersText}</option>` +
            (schedule.teachers || []).map(tItem => `<option value="${tItem.name}">${tItem.name} (${translateSubjectName(tItem.specialization || '')})</option>`).join('');
        if (curVal && (curVal === 'all_teachers' || (schedule.teachers || []).some(t => t.name === curVal))) {
            subTeacherSelect.value = curVal;
        } else {
            subTeacherSelect.value = 'all_teachers';
        }
    }
    if (subDaySelect) {
        const curDay = subDaySelect.value || 'all';
        const defaultDaysKurdish = ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
        const savedDays = schedule.settings?.workDays || defaultDaysKurdish;
        const localizedWorkDays = typeof t === 'function' ? t('work_days') : defaultDaysKurdish;
        const days = savedDays.map((dStr) => {
            const indexInKurdish = typeof ALL_DAYS_KURDISH !== 'undefined' ? ALL_DAYS_KURDISH.indexOf(dStr) : -1;
            if (indexInKurdish !== -1 && Array.isArray(localizedWorkDays) && localizedWorkDays[indexInKurdish]) {
                return localizedWorkDays[indexInKurdish];
            }
            return dStr;
        });
        const allDaysText = (typeof t === 'function' ? t('all_days_option') : 'هەمی ڕۆژێن حەفتیێ') || 'هەمی ڕۆژێن حەفتیێ';
        subDaySelect.innerHTML = `<option value="all">${allDaysText}</option>` +
            days.map((dName, dIdx) => `<option value="${dIdx}">${dName}</option>`).join('');
        subDaySelect.value = curDay;
    }
}
window.populateSubstituteControls = populateSubstituteControls;

function renderSubstituteTab() {
    const schedule = allSchedules[activeScheduleName];
    const container = document.getElementById('substituteMainContainer');
    if (!schedule || !container) return;

    const defaultDaysKurdish = ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
    const savedDays = schedule.settings?.workDays || defaultDaysKurdish;
    const localizedWorkDays = typeof t === 'function' ? t('work_days') : defaultDaysKurdish;
    const days = savedDays.map((dStr) => {
        const indexInKurdish = typeof ALL_DAYS_KURDISH !== 'undefined' ? ALL_DAYS_KURDISH.indexOf(dStr) : -1;
        if (indexInKurdish !== -1 && Array.isArray(localizedWorkDays) && localizedWorkDays[indexInKurdish]) {
            return localizedWorkDays[indexInKurdish];
        }
        return dStr;
    });
    const periodsCount = schedule.settings?.periodsPerDay || 7;

    renderSubstituteFinder(schedule, container, days, periodsCount);
}
window.renderSubstituteTab = renderSubstituteTab;

window.selectAbsentTeacherQuick = function(tName) {
    const subTeacherSelect = document.getElementById('substituteTeacherSelect');
    if (subTeacherSelect) {
        subTeacherSelect.value = tName;
    }
    renderSubstituteTab();
};

function renderSubstituteFinder(schedule, container, days, periodsCount) {
    if (!schedule || !container) return;

    // Automatically purge any previously stored administrative substitute assignments
    if (schedule.substitutions) {
        let hasAdmin = false;
        Object.keys(schedule.substitutions).forEach(k => {
            const sub = schedule.substitutions[k];
            if (sub && typeof isAdministrativeStaff === 'function' && isAdministrativeStaff(sub, schedule)) {
                delete schedule.substitutions[k];
                hasAdmin = true;
            }
        });
        if (hasAdmin && typeof saveData === 'function') saveData();
    }

    const subTeacherSelect = document.getElementById('substituteTeacherSelect');
    const subDaySelect = document.getElementById('substituteDaySelect');
    const absentTeacherName = subTeacherSelect ? subTeacherSelect.value : '';
    const selectedDayVal = subDaySelect ? subDaySelect.value : 'all';

    // If no absent teacher selected yet and not in one of the multi-teacher modes
    if (!absentTeacherName && !['weekly_master', 'weekly_master_classes', 'grid'].includes(substituteSubViewMode)) {
        const teachersListHtml = (schedule.teachers || []).map(tItem => {
            const spec = translateSubjectName(tItem.specialization || '');
            return `
                <button type="button" class="btn btn-outline-primary m-1 px-3 py-2 text-start rounded-3 shadow-sm substitute-pick-btn" onclick="selectAbsentTeacherQuick('${tItem.name.replace(/'/g, "\\'")}')">
                    <div class="fw-bold">${tItem.name}</div>
                    <div class="small text-muted">${spec || t('col_teacher')}</div>
                </button>
            `;
        }).join('');

        container.innerHTML = `
            <div class="text-center py-5 px-3 bg-white rounded-4 border shadow-sm my-3">
                <div class="mb-3">
                    <span class="d-inline-flex align-items-center justify-content-center bg-primary-subtle text-primary rounded-circle" style="width: 75px; height: 75px;">
                        <i class="fas fa-user-clock fa-2x"></i>
                    </span>
                </div>
                <h4 class="fw-bold text-primary mb-2">${t('substitute_finder_title')}</h4>
                <p class="text-muted mx-auto mb-4" style="max-width: 600px;">
                    ${t('select_teacher_first_prompt')}
                </p>
                <div class="card p-3 border-0 bg-light-subtle rounded-4 max-w-lg mx-auto" style="max-width: 750px;">
                    <h6 class="fw-bold text-secondary mb-3 text-start"><i class="fas fa-hand-pointer me-2 text-warning"></i>${t('select_absent_teacher')}</h6>
                    <div class="d-flex flex-wrap justify-content-center gap-1" style="max-height: 280px; overflow-y: auto;">
                        ${teachersListHtml || `<div class="text-muted p-3">${t('no_teachers_found')}</div>`}
                    </div>
                </div>
                <div class="mt-4 d-flex justify-content-center gap-2 flex-wrap">
                    <button type="button" class="btn btn-outline-primary fw-bold rounded-pill px-3 shadow-sm" onclick="switchSubstituteSubView('weekly_master')">
                        <i class="fas fa-chalkboard-teacher me-2"></i>ماستری مامۆستایان (الجدول العام للمعلمين)
                    </button>
                    <button type="button" class="btn btn-outline-success fw-bold rounded-pill px-3 shadow-sm" onclick="switchSubstituteSubView('weekly_master_classes')">
                        <i class="fas fa-chalkboard me-2"></i>ماستری پۆلان (الجدول العام للفصول)
                    </button>
                </div>
            </div>
        `;
        return;
    }

    const isAllTeachers = !absentTeacherName || absentTeacherName === 'all_teachers';
    const absentTeacherObj = !isAllTeachers ? (schedule.teachers || []).find(t => t.name === absentTeacherName) : null;
    const absentSpec = absentTeacherObj?.specialization || '';
    const leaveNames = getLeaveTeacherNames(schedule);

    // Collect all slots of the absent teacher(s) or on-leave teachers
    schedule.substitutions = schedule.substitutions || {};
    let totalSlotsCount = 0;
    let assignedCount = 0;
    const allSlotsList = [];

    // Count total substitutions across the whole schedule
    const totalAssignedSubstitutes = Object.keys(schedule.substitutions).length;

    for (let d = 0; d < days.length; d++) {
        for (let p = 1; p <= periodsCount; p++) {
            for (const cName of (schedule.columns || [])) {
                const slotItem = schedule.timetables?.[cName]?.[d]?.[p];
                if (slotItem && slotItem.teacher) {
                    const teacherForSlot = slotItem.teacher;
                    const isTargetSlot = !isAllTeachers
                        ? (teacherForSlot === absentTeacherName)
                        : (leaveNames.length > 0 ? isTeacherOnLeave(teacherForSlot, d, schedule) : true);

                    if (isTargetSlot) {
                        totalSlotsCount++;
                        const assignKey = `${teacherForSlot}__${d}__${p}__${cName}`;
                        const assignedSub = schedule.substitutions[assignKey] || '';
                        if (assignedSub) assignedCount++;

                        allSlotsList.push({
                            day: d,
                            period: p,
                            className: cName,
                            teacher: teacherForSlot,
                            subject: slotItem.subject,
                            assignedSub
                        });
                    }
                }
            }
        }
    }

    // Helper: get available candidates for a specific day and period
    const getCandidatesForSlot = (d, p, subject, teacherName = absentTeacherName) => getSubstituteCandidates(schedule, teacherName, d, p, subject, days, periodsCount);

    // Days to show based on dropdown
    const daysToProcess = selectedDayVal === 'all'
        ? days.map((_, idx) => idx)
        : [parseInt(selectedDayVal, 10)].filter(idx => !isNaN(idx) && idx >= 0 && idx < days.length);

    // Dynamic button label & tooltip based on active section
    let autoBtnLabel = t('sub_auto_btn_single', 'توزيع تلقائي');
    let autoBtnTitle = t('sub_auto_title_single', 'توزيع البدلاء تلقائياً');
    let clearBtnTitle = t('sub_clear_btn_title', 'مسح البدلاء');

    if (substituteSubViewMode === 'grid') {
        autoBtnLabel = !isAllTeachers ? `${t('sub_auto_btn_single', 'توزيع تلقائي')} (${absentTeacherName})` : t('sub_auto_btn_all_teachers', 'توزيع تلقائي (لكافة المعلمين)');
        autoBtnTitle = !isAllTeachers ? `${t('sub_auto_title_single', 'توزيع البدلاء تلقائياً لـ')} (${absentTeacherName})` : t('sub_auto_title_all_teachers', 'توزيع البدلاء لكافة المعلمين');
        clearBtnTitle = t('sub_clear_btn_title', 'مسح البدلاء');
    } else if (substituteSubViewMode === 'weekly_master') {
        autoBtnLabel = t('sub_auto_btn_all_teachers', 'توزيع تلقائي (لكافة المعلمين)');
        autoBtnTitle = t('sub_auto_title_all_teachers', 'توزيع البدلاء لكافة المعلمين بدون تعارض');
        clearBtnTitle = t('sub_clear_btn_title', 'مسح البدلاء');
    } else if (substituteSubViewMode === 'weekly_master_classes') {
        autoBtnLabel = t('sub_auto_btn_all_classes', 'دانانا ئۆتۆماتیکی (بۆ هەمی پۆلان)');
        autoBtnTitle = t('sub_auto_title_all_classes', 'توزيع البدلاء لكافة الشواغر في جدول الفصول كاملاً');
        clearBtnTitle = t('sub_clear_btn_title', 'مسح البدلاء');
    }

    let teacherBadgeDisplay = absentTeacherName;
    const isAr = (currentLang === 'ar');
    if (isAllTeachers) {
        if (substituteSubViewMode === 'weekly_master_classes') teacherBadgeDisplay = isAr ? 'جدول الفصول والبدلاء' : 'ماستەری پۆلان';
        else if (substituteSubViewMode === 'grid') teacherBadgeDisplay = isAr ? 'مصفوفة الإجازات' : 'خشتێ مۆڵەتان';
        else teacherBadgeDisplay = isAr ? 'جدول المعلمين والبدلاء' : 'ماستەری مامۆستایان';
    }

    // Pre-generate select options for teacher and day dropdowns
    const allTeachersText = (typeof t === 'function' ? t('all_teachers') : 'هەمی مامۆستا') || 'هەمی مامۆستا';
    const teacherOptionsHtml = `<option value="all_teachers" ${absentTeacherName === 'all_teachers' || !absentTeacherName ? 'selected' : ''}>${allTeachersText}</option>` +
        (schedule.teachers || []).map(tItem => `<option value="${tItem.name}" ${tItem.name === absentTeacherName ? 'selected' : ''}>${tItem.name} (${translateSubjectName(tItem.specialization || '')})</option>`).join('');

    const allDaysText = (typeof t === 'function' ? t('all_days_option') : 'هەمی ڕۆژێن حەفتیێ') || 'هەمی ڕۆژێن حەفتیێ';
    const dayOptionsHtml = `<option value="all" ${selectedDayVal === 'all' ? 'selected' : ''}>${allDaysText}</option>` +
        days.map((dName, dIdx) => `<option value="${dIdx}" ${String(dIdx) === String(selectedDayVal) ? 'selected' : ''}>${dName}</option>`).join('');

    // Build the Top Sub-View Bar
    const subViewBarHtml = `
        <div class="substitute-header-card mb-3">
            <!-- Tier 1: View Navigation Tabs (Right in RTL) & Status Context Badges (Left in RTL) -->
            <div class="substitute-toolbar-tier1 d-flex justify-content-between align-items-center flex-wrap gap-2 pb-2.5 mb-2.5 border-bottom">
                <!-- Segmented View Tabs -->
                <div class="substitute-segmented-nav shadow-xs" role="group">
                    <button type="button" class="substitute-segmented-tab ${substituteSubViewMode === 'weekly_master' ? 'active' : ''}" onclick="switchSubstituteSubView('weekly_master')">
                        <i class="fas fa-users-rectangle ${substituteSubViewMode === 'weekly_master' ? 'text-warning' : 'text-primary'} me-1"></i>
                        <span>${isAr ? 'جدول المعلمين' : 'خشتێ مامۆستایان'}</span>
                    </button>
                    <button type="button" class="substitute-segmented-tab ${substituteSubViewMode === 'weekly_master_classes' ? 'active' : ''}" onclick="switchSubstituteSubView('weekly_master_classes')">
                        <i class="fas fa-chalkboard ${substituteSubViewMode === 'weekly_master_classes' ? 'text-warning' : 'text-success'} me-1"></i>
                        <span>${isAr ? 'جدول الفصول' : 'خشتێ پۆلان'}</span>
                    </button>
                    <button type="button" class="substitute-segmented-tab ${substituteSubViewMode === 'grid' ? 'active' : ''}" onclick="switchSubstituteSubView('grid')">
                        <i class="fas fa-table-cells ${substituteSubViewMode === 'grid' ? 'text-warning' : 'text-primary'} me-1"></i>
                        <span>${isAr ? 'المصفوفة' : 'خشتێ مۆڵەتان'}</span>
                    </button>
                </div>

                <!-- Status Badges & Info Capsule -->
                <div class="d-flex align-items-center gap-2 flex-wrap substitute-status-info">
                    <div class="d-inline-flex align-items-center gap-1.5 py-1 px-2.5 rounded-pill bg-light border shadow-xs">
                        <i class="fas ${!isAllTeachers ? 'fa-user-clock text-danger' : 'fa-calendar-check text-primary'}"></i>
                        <span class="small fw-bold text-muted">${isAr ? 'الجدول:' : 'خشتە:'}</span>
                        <span class="badge ${!isAllTeachers ? 'bg-danger text-white' : 'bg-primary text-white'} rounded-pill px-2.5 py-1 fw-bold shadow-xs">
                            ${teacherBadgeDisplay}
                        </span>
                    </div>

                    <div class="d-inline-flex align-items-center gap-1.5 flex-wrap">
                        ${!isAllTeachers ? `
                            <span class="badge bg-light text-secondary border rounded-pill py-1.5 px-2.5"><i class="fas fa-graduation-cap me-1 text-primary"></i>${translateSubjectName(absentSpec) || (isAr ? 'معلم' : 'مامۆستا')}</span>
                            <span class="badge bg-primary-subtle text-primary border border-primary-subtle rounded-pill py-1.5 px-2.5"><i class="fas fa-book-reader me-1"></i>${totalSlotsCount} ${isAr ? 'حصة' : 'وانە'}</span>
                            <span class="badge ${assignedCount === totalSlotsCount && totalSlotsCount > 0 ? 'bg-success text-white' : 'bg-warning-subtle text-dark border border-warning-subtle'} rounded-pill py-1.5 px-2.5 shadow-xs">
                                <i class="fas fa-user-check me-1"></i>${assignedCount} / ${totalSlotsCount} ${isAr ? 'تم البديل' : 'هاتنە دانان'}
                            </span>
                        ` : `
                            ${leaveNames.length > 0 ? `
                                <span class="badge bg-danger-subtle text-danger border border-danger-subtle rounded-pill py-1.5 px-2.5"><i class="fas fa-user-clock me-1"></i>${leaveNames.length} ${isAr ? 'مستحق إجازة' : 'مۆڵەتدار'}</span>
                                <span class="badge ${assignedCount === totalSlotsCount && totalSlotsCount > 0 ? 'bg-success text-white' : 'bg-warning-subtle text-dark border border-warning-subtle'} rounded-pill py-1.5 px-2.5 shadow-xs">
                                    <i class="fas fa-user-check me-1"></i>${assignedCount} / ${totalSlotsCount} ${isAr ? 'بديل' : 'بەدیل'}
                                </span>
                            ` : `
                                <span class="badge bg-success-subtle text-success border border-success-subtle rounded-pill py-1.5 px-2.5"><i class="fas fa-check me-1"></i>${totalAssignedSubstitutes} ${isAr ? 'بديل مسند' : 'بەدیل'}</span>
                            `}
                        `}
                    </div>
                </div>
            </div>

            <!-- Tier 2: Filters Capsule (Right in RTL) & Action Buttons Toolbar (Left in RTL) -->
            <div class="substitute-toolbar-tier2 d-flex justify-content-between align-items-center flex-wrap gap-2.5">
                <!-- Filters: Teacher & Day Selects Capsule -->
                <div class="substitute-filters-group d-inline-flex align-items-center gap-1.5 p-1 px-2.5 rounded-pill bg-light border shadow-xs flex-wrap">
                    <span class="text-muted small fw-bold px-1 d-inline-flex align-items-center gap-1">
                        <i class="fas fa-filter text-primary" style="font-size: 0.78rem;"></i>
                    </span>
                    <select id="substituteTeacherSelect" class="form-select form-select-sm rounded-pill fw-bold substitute-select shadow-xs"
                        style="min-width: 170px; max-width: 250px;" onchange="renderSubstituteTab()">
                        ${teacherOptionsHtml}
                    </select>
                    <select id="substituteDaySelect" class="form-select form-select-sm rounded-pill fw-bold substitute-select shadow-xs"
                        style="min-width: 140px; max-width: 210px;" onchange="renderSubstituteTab()">
                        ${dayOptionsHtml}
                    </select>
                </div>

                <!-- Action Buttons Toolbar -->
                <div class="substitute-actions-toolbar d-flex align-items-center gap-1.5 flex-wrap">
                    <button type="button" class="btn btn-warning btn-sm rounded-pill fw-bold shadow-xs text-dark substitute-btn-action substitute-btn-auto" onclick="autoAssignAllSubstitutes()" title="${autoBtnTitle}">
                        <i class="fas fa-magic me-1"></i><span>${isAr ? 'توزيع تلقائي' : 'دابەشکرنا زیرەك'}</span>
                    </button>
                    <button type="button" class="btn btn-outline-primary btn-sm rounded-pill fw-bold shadow-xs substitute-btn-action substitute-btn-select" onclick="openSubstituteTeacherModal()" title="${isAr ? 'تحديد المعلمين المؤهلين للبدلاء' : 'دەستنیشانکرنا مامۆستایێن جهگر'}">
                        <i class="fas fa-user-check me-1 text-primary"></i><span>${isAr ? 'تحديد المعلمين' : 'دەستنیشانکرن'}</span>
                    </button>
                    <button type="button" class="btn btn-outline-secondary btn-sm rounded-pill fw-bold shadow-xs substitute-btn-action substitute-btn-other" onclick="promptSelectAbsentTeacher()" title="${isAr ? 'تغيير المعلم' : 'گوهورینا مامۆستایی'}">
                        <i class="fas fa-exchange-alt me-1 text-primary"></i><span>${isAr ? 'تغيير المعلم' : 'گوهورینا مامۆستایی'}</span>
                    </button>
                    <button type="button" class="btn btn-success btn-sm rounded-pill fw-bold shadow-xs text-white substitute-btn-action substitute-btn-html" onclick="downloadSubstituteHTML('current')" title="${isAr ? 'تنزيل كملف HTML' : 'داونلودکرنا فایلی HTML'}">
                        <i class="fas fa-file-code me-1"></i><span>HTML</span>
                    </button>
                    <button type="button" class="btn btn-dark btn-sm rounded-pill fw-bold shadow-xs text-white substitute-btn-action substitute-btn-print" onclick="printDailySubstitutionReport('current')" title="${isAr ? 'طباعة' : 'چاپکرن'}">
                        <i class="fas fa-print me-1 text-warning"></i><span>${isAr ? 'طباعة' : 'چاپکرن'}</span>
                    </button>
                    <button type="button" class="btn btn-outline-danger btn-sm rounded-pill fw-bold shadow-xs substitute-btn-action substitute-btn-clear" onclick="clearSubstituteAssignments()" title="${clearBtnTitle}">
                        <i class="fas fa-trash-alt me-1"></i><span>${isAr ? 'تفريغ' : 'ڤالاکرن'}</span>
                    </button>
                </div>
            </div>
        </div>
    `;

    let mainContentHtml = '';

    // -------------------------------------------------------------
    // SUB-VIEW 0: Weekly Master Timetable for All Teachers (ماستری گشتی یێ هەفتیانە)
    // -------------------------------------------------------------
    if (substituteSubViewMode === 'weekly_master') {
        const allTeachers = schedule.teachers || [];
        const schoolName = schedule.settings?.globalSchoolName || schedule.milak?.schoolName || '';

        let h = `<div class="text-center mb-2.5">
            <span class="badge bg-light text-dark border px-3 py-1.5 fs-6 fw-bold shadow-xs">
                <i class="fas fa-users me-1.5 text-primary"></i>${schoolName ? `${schoolName} - ` : ''}${isAr ? 'الجدول العام للمعلمين والبدلاء' : 'خشتێ گشتی یێ مامۆستایان و بەدیلان'}
            </span>
        </div>`;
        h += '<table class="table table-bordered text-center align-middle bg-white mb-0" style="font-size: 0.75rem; width: 100%; table-layout: fixed; min-width: ' + (daysToProcess.length * periodsCount * 44 + 200) + 'px;">' +
            '<thead class="table-light">' +
            '<tr>' +
            `<th rowspan="2" class="align-middle bg-secondary text-white fw-bold" style="width: 200px; min-width: 200px; max-width: 200px; position: sticky; right: 0; top: 0; z-index: 10; font-size: 0.92rem; background-clip: padding-box; border-left: 2px solid #adb5bd !important; box-shadow: -2px 0 6px rgba(0,0,0,0.1);">${t('col_teacher')}</th>`;

        daysToProcess.forEach(d => {
            h += '<th colspan="' + periodsCount + '" class="border-start border-end border-dark bg-dark text-white fw-bold py-1" style="font-size: 0.9rem; position: sticky; top: 0; z-index: 5; background-clip: padding-box;">' + days[d] + '</th>';
        });
        h += '</tr><tr>';
        daysToProcess.forEach(d => {
            for (let p = 1; p <= periodsCount; p++) {
                h += '<th class="' + (p === 1 ? 'border-start border-dark' : '') + ' ' + (p === periodsCount ? 'border-end border-dark' : '') + ' bg-secondary text-white py-1" style="font-size: 0.75rem; position: sticky; top: 32px; z-index: 4; background-clip: padding-box;">' + p + '</th>';
            }
        });
        h += '</tr></thead><tbody>';

        allTeachers.forEach(tItem => {
            const tName = tItem.name;
            const isLeave = isTeacherOnLeave(tName, null, schedule);
            const isSelectedAbsent = absentTeacherName && tName === absentTeacherName;
            h += `<tr><td class="fw-bold align-middle ${isSelectedAbsent || isLeave ? 'bg-danger text-white' : 'bg-light text-dark'}" style="position: sticky; right: 0; z-index: 2; font-size: 0.84rem; padding: 2px 8px; background-clip: padding-box; border: 1px solid #dee2e6; border-left: 2px solid #adb5bd !important; width: 200px; min-width: 200px; max-width: 200px; height: 40px; line-height: 1.2; box-shadow: -2px 0 6px rgba(0,0,0,0.08); text-align: center;" title="${tName}"><div class="d-flex align-items-center justify-content-center gap-1" style="white-space: nowrap; overflow: hidden; text-overflow: ellipsis; width: 100%;"><span class="text-truncate fw-bold" style="font-size: 0.84rem;">${tName}</span> ${isLeave ? '<span class="badge bg-warning text-dark py-0.5 px-1.5 flex-shrink-0" style="font-size:0.62rem;">مۆڵەت</span>' : ''}</div></td>`;

            daysToProcess.forEach(d => {
                const dayName = days[d];
                const rawDayName = (typeof ALL_DAYS_KURDISH !== 'undefined' ? ALL_DAYS_KURDISH[d] : null) || dayName;
                const offDays = tItem.offDays || [];
                const isOffDay = offDays.includes(dayName) || offDays.includes(rawDayName);
                const blocked = tItem.blockedPeriods || {};
                const blockedPeriods = blocked[dayName] || blocked[rawDayName] || [];

                for (let p = 1; p <= periodsCount; p++) {
                    const isBlocked = Array.isArray(blockedPeriods) && blockedPeriods.includes(p);
                    const borderClass = (p === 1 ? 'border-start border-dark ' : '') + (p === periodsCount ? 'border-end border-dark ' : '');

                    let foundClass = '', foundSubject = '';
                    for (const c of (schedule.columns || [])) {
                        const item = schedule.timetables?.[c]?.[d]?.[p];
                        if (item && item.teacher === tName) {
                            foundClass = c;
                            foundSubject = item.subject;
                            break;
                        }
                    }

                    if (foundClass) {
                        const assignKey = `${tName}__${d}__${p}__${foundClass}`;
                        const assignedSub = schedule.substitutions ? schedule.substitutions[assignKey] : '';

                        if (assignedSub) {
                            const subDisplayName = (getSmartTeacherDisplayName(assignedSub, schedule.teachers) || assignedSub).trim().split(/\s+/)[0];
                            h += `<td class="${borderClass} timetable-cell" style="background-color: #dcfce7 !important; border: 1px solid #16a34a; overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 40px; cursor: pointer; position: relative;" onclick="openSubstitutePickerModal(${d}, ${p}, '${foundClass.replace(/'/g, "\\'")}', '${foundSubject.replace(/'/g, "\\'")}', '${tName.replace(/'/g, "\\'")}')" title="البديل: ${assignedSub} (${foundClass} / ${foundSubject})">` +
                                `<a href="javascript:void(0)" onclick="event.stopPropagation(); removeSubstituteAssignment('${tName.replace(/'/g, "\\'")}', ${d}, ${p}, '${foundClass.replace(/'/g, "\\'")}')" title="إلغاء البديل" style="position: absolute; top: 1px; left: 2px; font-size: 0.65rem; color: #dc2626; text-decoration: none; font-weight: bold; z-index: 3;">✕</a>` +
                                getSvgFormattedText(subDisplayName, true, 'text-success fw-bold', 11) +
                                getSvgFormattedText(foundClass, false, 'text-muted fw-bold', 9.5) +
                                `</td>`;
                        } else {
                            const isTeacherAbsentHere = isTeacherOnLeave(tName, d, schedule) || isSelectedAbsent;
                            const teacherFirstName = (getSmartTeacherDisplayName(tName, schedule.teachers) || tName).trim().split(/\s+/)[0];
                            h += `<td class="${borderClass} timetable-cell ${isTeacherAbsentHere ? 'bg-danger-subtle' : 'bg-white'}" style="${isTeacherAbsentHere ? 'border: 1.5px dashed #dc2626; background-color: #fee2e2 !important;' : ''} overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 40px; cursor: pointer;" onclick="openSubstitutePickerModal(${d}, ${p}, '${foundClass.replace(/'/g, "\\'")}', '${foundSubject.replace(/'/g, "\\'")}', '${tName.replace(/'/g, "\\'")}')" title="${isTeacherAbsentHere ? 'شاغر / بحاجة لبديل - انقر للتعيين' : 'انقر لتعيين بديل'} (${foundSubject} - ${foundClass})">` +
                                (isTeacherAbsentHere ? `<div class="badge bg-danger mb-0.5" style="font-size:0.6rem; padding: 1px 3px;">شاغر</div>` : '') +
                                getSvgFormattedText(teacherFirstName, true, isTeacherAbsentHere ? 'text-danger' : 'text-primary', 11) +
                                getSvgFormattedText(foundClass, false, isTeacherAbsentHere ? 'text-danger fw-bold' : 'text-muted', 9.5) +
                                `</td>`;
                        }
                    } else if (isOffDay) {
                        h += `<td class="${borderClass} bg-light text-muted small" style="overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 40px; font-size: 0.65rem;">عطلة</td>`;
                    } else if (isBlocked) {
                        h += `<td class="${borderClass} bg-light text-danger small" style="overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 40px; font-size: 0.65rem;"><i class="fas fa-lock text-danger"></i></td>`;
                    } else {
                        // Check if teacher is assigned as a substitute in this slot
                        let subClassAssigned = '';
                        let absentTeacherCovered = '';
                        for (const [subKey, subTeacher] of Object.entries(schedule.substitutions || {})) {
                            if (subTeacher === tName) {
                                const parts = subKey.split('__');
                                if (parts.length >= 4 && parseInt(parts[1], 10) === d && parseInt(parts[2], 10) === p) {
                                    absentTeacherCovered = parts[0];
                                    subClassAssigned = parts[3];
                                    break;
                                }
                            }
                        }
                        if (subClassAssigned) {
                            const subCoveredFirst = absentTeacherCovered ? absentTeacherCovered.trim().split(/\s+/)[0] : '';
                            const subLabel = subCoveredFirst ? subCoveredFirst : (isAr ? 'بديل' : 'جهگر');
                            h += `<td class="${borderClass} bg-success-subtle text-success small fw-bold" style="border: 1px solid #16a34a; overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 40px;" title="${isAr ? 'بديل عن' : 'جهگر بۆ'} ${absentTeacherCovered || ''} (${subClassAssigned})">` +
                                getSvgFormattedText(subLabel, true, 'text-success fw-bold', 11) +
                                getSvgFormattedText(subClassAssigned, false, 'text-success fw-bold', 9.5) +
                                `</td>`;
                        } else {
                            h += `<td class="${borderClass} bg-white text-muted opacity-50" style="overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 40px;"></td>`;
                        }
                    }
                }
            });
            h += '</tr>';
        });
        h += '</tbody></table>';

        mainContentHtml = `
            <div class="card border-0 shadow-sm rounded-4 mb-4 bg-white" style="overflow: hidden;">
                <div class="p-3">
                    <div class="table-responsive" style="overflow-x: auto;">
                        ${h}
                    </div>
                </div>
            </div>

            <div class="alert alert-warning py-2.5 px-3 rounded-4 d-flex align-items-center justify-content-between shadow-sm border-0 small">
                <div>
                    <i class="fas fa-bolt text-dark me-2 fs-6"></i>
                    <strong>دانانا ئۆتۆماتیکی ب ئێک کلیک:</strong> بۆ دابەشکرنا بەدیلان بۆ تەواوی شواغرێن حەفتیێ بێی چ تێکچوون، کلیک ل سەر دوگمەیا زەرد یا سەرەوە <span class="badge bg-warning text-dark"><i class="fas fa-bolt me-1"></i>دانانا ئۆتۆماتیکی یا شواغران</span> بکە.
                </div>
            </div>
        `;
    }
    // -------------------------------------------------------------
    // SUB-VIEW 1: Weekly Master Timetable for All Classes (ماستری گشتی یێ پۆلان و بەدیلان)
    // -------------------------------------------------------------
    else if (substituteSubViewMode === 'weekly_master_classes') {
        const allClasses = schedule.columns || [];
        const schoolName = schedule.settings?.globalSchoolName || schedule.milak?.schoolName || '';

        let h = `<div class="text-center mb-2.5">
            <span class="badge bg-light text-dark border px-3 py-1.5 fs-6 fw-bold shadow-xs">
                <i class="fas fa-chalkboard me-1.5 text-success"></i>${schoolName ? `${schoolName} - ` : ''}${isAr ? 'الجدول العام للفصول والبدلاء' : 'خشتێ گشتی یێ پۆلان و بەدیلان'}
            </span>
        </div>`;
        h += '<table class="table table-bordered text-center align-middle bg-white mb-0" style="font-size: 0.75rem; width: 100%; table-layout: fixed; min-width: ' + (daysToProcess.length * periodsCount * 44 + 140) + 'px;">' +
            '<thead class="table-light">' +
            '<tr>' +
            `<th rowspan="2" class="align-middle bg-dark text-white fw-bold" style="width: 140px; min-width: 140px; max-width: 140px; position: sticky; right: 0; top: 0; z-index: 10; font-size: 0.95rem; background-clip: padding-box; border-left: 2px solid #adb5bd !important; box-shadow: -2px 0 6px rgba(0,0,0,0.1);">${t('col_class') || 'پۆل / الصف'}</th>`;

        daysToProcess.forEach(d => {
            h += '<th colspan="' + periodsCount + '" class="border-start border-end border-dark bg-dark text-white fw-bold py-1" style="font-size: 0.9rem; position: sticky; top: 0; z-index: 5; background-clip: padding-box;">' + days[d] + '</th>';
        });
        h += '</tr><tr>';
        daysToProcess.forEach(d => {
            for (let p = 1; p <= periodsCount; p++) {
                h += '<th class="' + (p === 1 ? 'border-start border-dark' : '') + ' ' + (p === periodsCount ? 'border-end border-dark' : '') + ' bg-secondary text-white py-1" style="font-size: 0.75rem; position: sticky; top: 32px; z-index: 4; background-clip: padding-box;">' + p + '</th>';
            }
        });
        h += '</tr></thead><tbody>';

        allClasses.forEach(className => {
            h += `<tr><td class="fw-bold align-middle bg-light text-dark" style="position: sticky; right: 0; z-index: 2; font-size: 0.9rem; padding: 2px 6px; background-clip: padding-box; border: 1px solid #dee2e6; border-left: 2px solid #adb5bd !important; width: 140px; min-width: 140px; max-width: 140px; height: 40px; line-height: 1.2; box-shadow: -2px 0 6px rgba(0,0,0,0.08); text-align: center;"><span class="badge bg-primary-subtle text-primary border border-primary-subtle fs-6">${className}</span></td>`;

            daysToProcess.forEach(d => {
                for (let p = 1; p <= periodsCount; p++) {
                    const borderClass = (p === 1 ? 'border-start border-dark ' : '') + (p === periodsCount ? 'border-end border-dark ' : '');
                    const slotItem = schedule.timetables?.[className]?.[d]?.[p];

                    if (slotItem && slotItem.teacher) {
                        const originalTeacher = slotItem.teacher;
                        const subject = slotItem.subject || '';
                        const assignKey = `${originalTeacher}__${d}__${p}__${className}`;
                        const assignedSub = schedule.substitutions ? schedule.substitutions[assignKey] : '';

                        if (assignedSub) {
                            const subDisplayName = getSmartTeacherDisplayName(assignedSub, schedule.teachers);
                            h += `<td class="${borderClass} timetable-cell" style="background-color: #dcfce7 !important; border: 1.5px solid #16a34a; overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 40px; cursor: pointer; position: relative;" onclick="openSubstitutePickerModal(${d}, ${p}, '${className.replace(/'/g, "\\'")}', '${subject.replace(/'/g, "\\'")}', '${originalTeacher.replace(/'/g, "\\'")}')" title="البديل: ${assignedSub} | الأصلي: ${originalTeacher} (${subject}) - انقر للتعديل">` +
                                `<a href="javascript:void(0)" onclick="event.stopPropagation(); removeSubstituteAssignment('${originalTeacher.replace(/'/g, "\\'")}', ${d}, ${p}, '${className.replace(/'/g, "\\'")}')" title="إلغاء البديل" style="position: absolute; top: 1px; left: 2px; font-size: 0.65rem; color: #dc2626; text-decoration: none; font-weight: bold; z-index: 3;">✕</a>` +
                                getSvgFormattedText(subDisplayName, true, 'text-success fw-bold', 11) +
                                getSvgFormattedText(getDisplaySubjectName(subject, true) + ' (' + getTeacherDisplayName(originalTeacher) + ')', false, 'text-muted', 8.5) +
                                `</td>`;
                        } else {
                            const isAbsent = isTeacherOnLeave(originalTeacher, d, schedule) || (absentTeacherName && originalTeacher === absentTeacherName && absentTeacherName !== 'all_teachers');
                            h += `<td class="${borderClass} timetable-cell ${isAbsent ? 'bg-danger-subtle' : 'bg-white'}" style="${isAbsent ? 'border: 1.5px dashed #dc2626; background-color: #fee2e2 !important;' : ''} overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 40px; cursor: pointer;" onclick="openSubstitutePickerModal(${d}, ${p}, '${className.replace(/'/g, "\\'")}', '${subject.replace(/'/g, "\\'")}', '${originalTeacher.replace(/'/g, "\\'")}')" title="${isAbsent ? 'شاغر / بحاجة لبديل - انقر لتعيين بديل' : 'انقر لتعيين بديل'} (${originalTeacher} - ${subject})">` +
                                (isAbsent ? `<div class="badge bg-danger mb-0.5" style="font-size:0.6rem; padding: 1px 3px;">شاغر</div>` : '') +
                                getSvgFormattedText(getDisplaySubjectName(subject, true), true, isAbsent ? 'text-danger' : 'text-primary', 11) +
                                getSvgFormattedText(getTeacherDisplayName(originalTeacher), false, isAbsent ? 'text-danger fw-bold' : 'text-muted', 9.5) +
                                `</td>`;
                        }
                    } else {
                        h += `<td class="${borderClass} bg-white text-muted opacity-50" style="overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 40px;"></td>`;
                    }
                }
            });
            h += '</tr>';
        });
        h += '</tbody></table>';

        mainContentHtml = `
            <div class="card border-0 shadow-sm rounded-4 mb-4 bg-white" style="overflow: hidden;">
                <div class="p-3">
                    <div class="table-responsive" style="overflow-x: auto;">
                        ${h}
                    </div>
                </div>
            </div>

            <div class="alert alert-info py-2.5 px-3 rounded-4 d-flex align-items-center justify-content-between shadow-sm border-0 small">
                <div>
                    <i class="fas fa-info-circle text-primary me-2 fs-6"></i>
                    <strong>خشتێ گشتی یێ پۆلان و بەدیلان:</strong> د ڤی خشتەی دا هەمی وانەیێن پۆلان دەردکەڤن، کلیک ل سەر هەر وانەیەکێ بکە بۆ دەستنیشانکرنا بەدیلێ شاغر یێ بەردەست ب ئێک کلیک.
                </div>
            </div>
        `;
    }
    // -------------------------------------------------------------
    // SUB-VIEW 2: Vacancies & Substitutions Master Matrix (ماستری شواغران و بەدیلان ب تنێ)
    // -------------------------------------------------------------
    else if (substituteSubViewMode === 'vacancies_master') {
        const schoolName = schedule.settings?.globalSchoolName || schedule.milak?.schoolName || '';
        schedule.substitutions = schedule.substitutions || {};

        // Find all teachers who either have assignments or are marked absent
        const teachersWithVacancies = [];
        (schedule.teachers || []).forEach(tItem => {
            const tName = tItem.name;
            let count = 0;
            for (let d = 0; d < days.length; d++) {
                for (let p = 1; p <= periodsCount; p++) {
                    for (const c of (schedule.columns || [])) {
                        if (schedule.timetables?.[c]?.[d]?.[p]?.teacher === tName) {
                            const assignKey = `${tName}__${d}__${p}__${c}`;
                            if (schedule.substitutions[assignKey] || (absentTeacherName && tName === absentTeacherName)) {
                                count++;
                            }
                        }
                    }
                }
            }
            if (count > 0 || (absentTeacherName && tName === absentTeacherName)) {
                teachersWithVacancies.push(tItem);
            }
        });

        const targetTeachers = teachersWithVacancies.length > 0 ? teachersWithVacancies : (schedule.teachers || []);

        let h = `<div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">` +
            `<h4 class="text-danger fw-bold mb-0" style="font-size: 1.35rem; letter-spacing: 0.5px;">` +
            (schoolName ? `${schoolName} - ` : '') +
            `جدول الشواغر وتوزيع البدلاء (ماستری شواغران و بەدیلان)</h4>` +
            `<span class="badge bg-primary-subtle text-primary border border-primary-subtle fs-6">${targetTeachers.length} ماموستا / معلماً مشمولاً</span>` +
            `</div>`;

        h += '<table class="table table-bordered text-center align-middle bg-white mb-0" style="font-size: 0.75rem; width: 100%; table-layout: fixed; min-width: ' + (daysToProcess.length * periodsCount * 48 + 155) + 'px;">' +
            '<thead class="table-light">' +
            '<tr>' +
            `<th rowspan="2" class="align-middle bg-danger text-white fw-bold" style="width: 155px; min-width: 155px; max-width: 155px; position: sticky; right: 0; top: 0; z-index: 10; font-size: 0.92rem; background-clip: padding-box; border-left: 2px solid #adb5bd !important; box-shadow: -2px 0 6px rgba(0,0,0,0.1);">${t('col_teacher')}</th>`;

        daysToProcess.forEach(d => {
            h += '<th colspan="' + periodsCount + '" class="border-start border-end border-dark bg-dark text-white fw-bold py-1" style="font-size: 0.9rem; position: sticky; top: 0; z-index: 5; background-clip: padding-box;">' + days[d] + '</th>';
        });
        h += '</tr><tr>';
        daysToProcess.forEach(d => {
            for (let p = 1; p <= periodsCount; p++) {
                h += '<th class="' + (p === 1 ? 'border-start border-dark' : '') + ' ' + (p === periodsCount ? 'border-end border-dark' : '') + ' bg-secondary text-white py-1" style="font-size: 0.75rem; position: sticky; top: 32px; z-index: 4; background-clip: padding-box;">' + p + '</th>';
            }
        });
        h += '</tr></thead><tbody>';

        targetTeachers.forEach(tItem => {
            const tName = tItem.name;
            const isSelectedAbsent = absentTeacherName && tName === absentTeacherName;
            h += `<tr><td class="fw-bold align-middle ${isSelectedAbsent ? 'bg-danger text-white' : 'bg-light text-dark'}" style="position: sticky; right: 0; z-index: 2; font-size: 0.82rem; padding: 2px 6px; background-clip: padding-box; border: 1px solid #dee2e6; border-left: 2px solid #adb5bd !important; width: 155px; min-width: 155px; max-width: 155px; height: 44px; line-height: 1.2; box-shadow: -2px 0 6px rgba(0,0,0,0.08); text-align: center;" title="${tName}"><div style="overflow: hidden; text-overflow: ellipsis; white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; word-break: break-word;">${tName}</div></td>`;

            daysToProcess.forEach(d => {
                for (let p = 1; p <= periodsCount; p++) {
                    const borderClass = (p === 1 ? 'border-start border-dark ' : '') + (p === periodsCount ? 'border-end border-dark ' : '');

                    let foundClass = '', foundSubject = '';
                    for (const c of (schedule.columns || [])) {
                        const item = schedule.timetables?.[c]?.[d]?.[p];
                        if (item && item.teacher === tName) {
                            foundClass = c;
                            foundSubject = item.subject;
                            break;
                        }
                    }

                    if (foundClass) {
                        const assignKey = `${tName}__${d}__${p}__${foundClass}`;
                        const assignedSub = schedule.substitutions ? schedule.substitutions[assignKey] : '';

                        if (assignedSub) {
                            const subDisplayName = getSmartTeacherDisplayName(assignedSub, schedule.teachers);
                            h += `<td class="${borderClass} timetable-cell" style="background-color: #dcfce7 !important; border: 1px solid #16a34a; overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 44px; cursor: pointer; position: relative;" title="البديل: ${assignedSub} (${foundClass} / ${foundSubject})">` +
                                `<a href="javascript:void(0)" onclick="event.stopPropagation(); removeSubstituteAssignment('${tName.replace(/'/g, "\\'")}', ${d}, ${p}, '${foundClass.replace(/'/g, "\\'")}')" title="إلغاء البديل" style="position: absolute; top: 1px; left: 2px; font-size: 0.65rem; color: #dc2626; text-decoration: none; font-weight: bold; z-index: 3;">✕</a>` +
                                getSvgFormattedText(subDisplayName, true, 'text-success', 11) +
                                getSvgFormattedText(foundClass + ' (' + getDisplaySubjectName(foundSubject, true) + ')', false, 'text-muted', 9) +
                                `</td>`;
                        } else if (isSelectedAbsent) {
                            h += `<td class="${borderClass} timetable-cell bg-danger-subtle" style="overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 44px; cursor: pointer; border: 1.5px dashed #dc2626;" onclick="openSubstitutePickerModal(${d}, ${p}, '${foundClass.replace(/'/g, "\\'")}', '${foundSubject.replace(/'/g, "\\'")}')" title="شاغر غير مغطى - انقر لتعيين بديل">` +
                                `<span class="badge bg-danger mb-0.5" style="font-size: 0.65rem;">شاغر</span>` +
                                getSvgFormattedText(foundClass, false, 'text-danger fw-bold', 9) +
                                `</td>`;
                        } else {
                            h += `<td class="${borderClass} timetable-cell bg-light text-muted opacity-75" style="overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 44px;" title="${foundSubject} (${foundClass})">` +
                                getSvgFormattedText(getDisplaySubjectName(foundSubject, true), true, 'text-secondary', 10.5) +
                                getSvgFormattedText(foundClass, false, 'text-muted', 9) +
                                `</td>`;
                        }
                    } else {
                        h += `<td class="${borderClass} bg-white text-muted opacity-25" style="overflow:hidden; vertical-align: middle; padding: 2px 1px; height: 44px;">·</td>`;
                    }
                }
            });
            h += '</tr>';
        });
        h += '</tbody></table>';

        mainContentHtml = `
            <div class="card border-0 shadow-sm rounded-4 mb-4 bg-white" style="overflow: hidden;">
                <div class="p-3">
                    <div class="table-responsive" style="overflow-x: auto;">
                        ${h}
                    </div>
                </div>
            </div>
        `;
    }
    // -------------------------------------------------------------
    // SUB-VIEW 3: Master Timetable Grid for Single Absent Teacher (خشتێ گشتی یێ مامۆستایێ مۆڵەتپێدای)
    // -------------------------------------------------------------
    else if (substituteSubViewMode === 'grid') {
        let periodHeaders = `<th style="width: 13%; background-color: #eff6ff; color: #2563eb; font-weight: bold; border: 1px solid #bfdbfe; font-size: 0.95rem;" class="py-2.5 text-center">اليوم / الحصة</th>`;
        for (let p = 1; p <= periodsCount; p++) {
            periodHeaders += `<th style="width: ${(87 / periodsCount).toFixed(2)}%; background-color: #eff6ff; color: #2563eb; font-weight: bold; border: 1px solid #bfdbfe; font-size: 1rem;" class="py-2.5 text-center">${p}</th>`;
        }

        const targetTeachersList = isAllTeachers ? (schedule.teachers || []) : (schedule.teachers || []).filter(t => t.name === absentTeacherName);

        let allGridsHtml = '';

        targetTeachersList.forEach((tItem, tIdx) => {
            const curTeacherName = tItem.name;
            const curTeacherSpec = tItem.specialization || '';
            let matrixRowsHtml = '';
            let curTotalSlots = 0;
            let curAssignedSlots = 0;

            daysToProcess.forEach(d => {
                const dayName = days[d];
                let rowCellsHtml = `<td class="fw-bold align-middle text-center" style="background-color: #ffffff; color: #1e293b; border: 1px solid #dbeafe; font-size: 0.95rem; width: 13%;">${dayName}</td>`;

                for (let p = 1; p <= periodsCount; p++) {
                    let foundClass = '', foundSubject = '';
                    for (const c of (schedule.columns || [])) {
                        const item = schedule.timetables?.[c]?.[d]?.[p];
                        if (item && item.teacher === curTeacherName) {
                            foundClass = c;
                            foundSubject = item.subject;
                            break;
                        }
                    }

                    if (foundClass) {
                        curTotalSlots++;
                        const assignKey = `${curTeacherName}__${d}__${p}__${foundClass}`;
                        const assignedSub = schedule.substitutions ? schedule.substitutions[assignKey] : '';
                        if (assignedSub) curAssignedSlots++;
                        const candidates = getSubstituteCandidates(schedule, curTeacherName, d, p, foundSubject, days, periodsCount);

                        rowCellsHtml += `
                            <td class="align-middle text-center p-2 position-relative" style="background-color: #ffffff; border: 1px solid #dbeafe; height: 75px; min-width: 100px;">
                                <div class="d-flex flex-column justify-content-center align-items-center h-100">
                                    <div class="fw-bold" style="color: #dc2626; font-size: 0.95rem;">${t('sub_class_label', 'فصل')} ${foundClass}</div>
                                    <div class="text-secondary small mt-0.5" style="font-size: 0.78rem;">${translateSubjectName(foundSubject)}</div>
                                    ${assignedSub ? `
                                        <div class="mt-1">
                                            <span class="badge bg-success text-white py-1 px-2 rounded-2 shadow-xs" style="font-size: 0.75rem;">
                                                ${assignedSub}
                                                <a href="javascript:void(0)" onclick="removeSubstituteAssignment('${curTeacherName.replace(/'/g, "\\'")}', ${d}, ${p}, '${foundClass.replace(/'/g, "\\'")}')" class="text-white ms-1 text-decoration-none fw-bold" title="${t('cancel', 'إلغاء البديل')}">✕</a>
                                            </span>
                                        </div>
                                    ` : `
                                        <div class="mt-1">
                                            <button type="button" class="btn btn-outline-warning btn-sm py-0.5 px-2 rounded-2 fw-bold" style="font-size: 0.72rem; border-style: dashed; color: #b45309;" onclick="openSubstitutePickerModal(${d}, ${p}, '${foundClass.replace(/'/g, "\\'")}', '${foundSubject.replace(/'/g, "\\'")}', '${curTeacherName.replace(/'/g, "\\'")}')">
                                                <i class="fas fa-user-plus me-1"></i>${candidates.length > 0 ? `${candidates.length} ${t('sub_available_count', 'متاح')}` : t('sub_assign_candidate_btn', 'تعيين بديل')}
                                            </button>
                                        </div>
                                    `}
                                </div>
                            </td>
                        `;
                    } else {
                        rowCellsHtml += `
                            <td class="align-middle text-center" style="background-color: #ffffff; border: 1px solid #dbeafe; height: 75px;"></td>
                        `;
                    }
                }
                matrixRowsHtml += `<tr>${rowCellsHtml}</tr>`;
            });

            const pageBreakClass = isAllTeachers && tIdx > 0 && tIdx % 2 === 0 ? 'page-break' : '';

            allGridsHtml += `
                <div class="card border-0 shadow-sm rounded-4 overflow-hidden mb-4 p-3.5 bg-white ${pageBreakClass}" style="border: 1px solid #dbeafe !important;">
                    <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2 px-2">
                        <div class="flex-grow-1 text-center">
                            <h5 class="fw-bold mb-0 text-dark" style="font-size: 1.2rem; letter-spacing: 0.5px;">
                                ${t('sub_teacher_name_label', 'اسم المعلم:')} <span class="text-primary">${curTeacherName}</span> ${curTeacherSpec ? `<span class="text-muted fs-6">(${translateSubjectName(curTeacherSpec)})</span>` : ''}
                            </h5>
                        </div>
                        <div class="d-flex align-items-center gap-2">
                            <span class="badge bg-light text-secondary border fs-7">${curTotalSlots} ${t('sub_weekly_lessons_badge', 'حصص أسبوعياً')}</span>
                            <span class="badge ${curAssignedSlots === curTotalSlots && curTotalSlots > 0 ? 'bg-success text-white' : 'bg-warning text-dark'} fs-7">
                                ${curAssignedSlots} / ${curTotalSlots} ${t('sub_covered_badge', 'مغطاة')}
                            </span>
                            ${isAllTeachers ? `
                                <button type="button" class="btn btn-outline-primary btn-sm py-0.5 px-2.5 fw-bold rounded-pill" onclick="selectAbsentTeacherQuick('${curTeacherName.replace(/'/g, "\\'")}')" title="${t('sub_focus_btn', 'تحديد')}">
                                    <i class="fas fa-search me-1"></i>${t('sub_focus_btn', 'تحديد')}
                                </button>
                            ` : ''}
                        </div>
                    </div>
                    <div class="table-responsive">
                        <table class="table table-bordered text-center align-middle mb-0" style="table-layout: fixed; border: 1px solid #bfdbfe;">
                            <thead>
                                <tr>${periodHeaders}</tr>
                            </thead>
                            <tbody>
                                ${matrixRowsHtml}
                            </tbody>
                        </table>
                    </div>
                </div>
            `;
        });

        mainContentHtml = allGridsHtml || `<div class="text-center p-4 bg-white rounded-4 shadow-sm text-muted">${t('no_teachers_found')}</div>`;
    }

    // -------------------------------------------------------------
    // SUB-VIEW 2: Master Teachers Availability (ماسترێ شواغران لكافة المعلمين)
    // -------------------------------------------------------------
    else if (substituteSubViewMode === 'master_teachers') {
        const currentD = selectedDayVal === 'all' ? 0 : parseInt(selectedDayVal, 10);
        const curDayName = days[currentD] || days[0];
        const rawDayName = ALL_DAYS_KURDISH[currentD] || curDayName;

        let masterPeriodHeaders = `<th style="width: 170px;" class="bg-dark text-white text-center">${t('col_teacher')}</th>`;
        for (let p = 1; p <= periodsCount; p++) {
            let absentSlotClass = '';
            for (const c of (schedule.columns || [])) {
                const item = schedule.timetables?.[c]?.[currentD]?.[p];
                if (item && item.teacher === absentTeacherName) {
                    absentSlotClass = c;
                    break;
                }
            }
            masterPeriodHeaders += `
                <th class="${absentSlotClass ? 'bg-danger text-white' : 'bg-secondary text-white'} text-center py-2" style="font-size: 0.8rem;">
                    <div>${t('day_period') || 'وانە'} ${p}</div>
                    ${absentSlotClass ? `<span class="badge bg-warning text-dark mt-1" style="font-size: 0.65rem;">پێدڤی ب جهگرە (${absentSlotClass})</span>` : ''}
                </th>
            `;
        }

        let masterTeacherRows = '';
        // Absent teacher first row
        let absentCells = `<td class="fw-bold bg-danger text-white text-start px-2 py-2" style="font-size: 0.82rem;">
            <i class="fas fa-user-times me-1"></i>${absentTeacherName} (المجاز)
        </td>`;
        for (let p = 1; p <= periodsCount; p++) {
            let foundC = '', foundS = '';
            for (const c of (schedule.columns || [])) {
                const item = schedule.timetables?.[c]?.[currentD]?.[p];
                if (item && item.teacher === absentTeacherName) { foundC = c; foundS = item.subject; break; }
            }
            if (foundC) {
                const assignKey = `${absentTeacherName}__${currentD}__${p}__${foundC}`;
                const assignedSub = schedule.substitutions[assignKey] || '';
                absentCells += `
                    <td class="p-1 align-middle bg-danger-subtle text-danger text-center fw-bold small" style="border: 1.5px solid #f87171;">
                        <span class="badge bg-danger mb-1">${foundC}</span>
                        <div style="font-size: 0.72rem;">${translateSubjectName(foundS)}</div>
                        ${assignedSub ? `<div class="badge bg-success text-white mt-1 p-1" style="font-size: 0.7rem; background-color: #15803d !important; color: #ffffff !important;">${assignedSub}</div>` : `<div class="badge bg-warning text-dark mt-1" style="font-size: 0.65rem;">شاغر</div>`}
                    </td>
                `;
            } else {
                absentCells += `<td class="p-1 align-middle text-center bg-light text-muted small">—</td>`;
            }
        }
        masterTeacherRows += `<tr>${absentCells}</tr>`;

        // Filter other teachers who have at least one free slot
        const printableTeachers = [];
        (schedule.teachers || []).forEach(tItem => {
            if (tItem.name === absentTeacherName) return;
            let freeSlotsCount = 0;
            let freeSubstituteSlotsCount = 0;
            let totalTeachingToday = 0;

            for (let p = 1; p <= periodsCount; p++) {
                let absentClass = '';
                for (const c of (schedule.columns || [])) {
                    const item = schedule.timetables?.[c]?.[currentD]?.[p];
                    if (item && item.teacher === absentTeacherName) { absentClass = c; break; }
                }

                let isBusy = false;
                for (const c of (schedule.columns || [])) {
                    const item = schedule.timetables?.[c]?.[currentD]?.[p];
                    if (item && item.teacher === tItem.name) { isBusy = true; break; }
                }
                if (isBusy) totalTeachingToday++;

                const offDays = tItem.offDays || [];
                const isOffDay = offDays.includes(curDayName) || offDays.includes(rawDayName);
                const blocked = tItem.blockedPeriods || {};
                const blockedPeriods = blocked[curDayName] || blocked[rawDayName] || [];
                const isBlocked = Array.isArray(blockedPeriods) && blockedPeriods.includes(p);

                if (!isBusy && !isOffDay && !isBlocked) {
                    freeSlotsCount++;
                    if (absentClass) freeSubstituteSlotsCount++;
                }
            }

            if (freeSlotsCount > 0) {
                // Strictly exclude administrative staff
                if (typeof isAdministrativeStaff === 'function' && isAdministrativeStaff(tItem, schedule)) return;

                printableTeachers.push({
                    teacher: tItem,
                    freeSlotsCount,
                    freeSubstituteSlotsCount,
                    totalTeachingToday,
                    isAdmin: false
                });
            }
        });

        printableTeachers.sort((a, b) => {
            if (a.isAdmin !== b.isAdmin) return a.isAdmin ? 1 : -1;
            if (a.freeSubstituteSlotsCount !== b.freeSubstituteSlotsCount) return b.freeSubstituteSlotsCount - a.freeSubstituteSlotsCount;
            return a.totalTeachingToday - b.totalTeachingToday;
        });

        printableTeachers.forEach(wrap => {
            const tItem = wrap.teacher;
            let rowCells = `
                <td class="fw-bold align-middle text-start px-2 py-1 bg-light text-dark" style="border: 1px solid #cbd5e1;">
                    <div class="fw-bold text-truncate" style="font-size: 0.8rem;" title="${tItem.name}">${tItem.name}</div>
                    <div class="text-muted small text-truncate" style="font-size: 0.68rem;">${translateSubjectName(tItem.specialization || '') || t('col_teacher')}</div>
                </td>
            `;

            for (let p = 1; p <= periodsCount; p++) {
                let absentClass = '', absentSubj = '';
                for (const c of (schedule.columns || [])) {
                    const item = schedule.timetables?.[c]?.[currentD]?.[p];
                    if (item && item.teacher === absentTeacherName) { absentClass = c; absentSubj = item.subject; break; }
                }

                let isBusyClass = '', isBusySubject = '';
                for (const c of (schedule.columns || [])) {
                    const item = schedule.timetables?.[c]?.[currentD]?.[p];
                    if (item && item.teacher === tItem.name) { isBusyClass = c; isBusySubject = item.subject; break; }
                }

                const offDays = tItem.offDays || [];
                const isOffDay = offDays.includes(curDayName) || offDays.includes(rawDayName);
                const blocked = tItem.blockedPeriods || {};
                const blockedPeriods = blocked[curDayName] || blocked[rawDayName] || [];
                const isBlocked = Array.isArray(blockedPeriods) && blockedPeriods.includes(p);

                if (isBusyClass) {
                    rowCells += `
                        <td class="p-1 align-middle text-center bg-white" style="border: 1px solid #e2e8f0;">
                            <span class="badge bg-secondary" style="font-size: 0.68rem;">${isBusyClass}</span>
                            <div class="text-muted small text-truncate" style="font-size: 0.65rem;">${translateSubjectName(isBusySubject)}</div>
                        </td>
                    `;
                } else if (isOffDay) {
                    rowCells += `<td class="p-1 align-middle text-center bg-light-subtle text-secondary small" style="border: 1px solid #e2e8f0; font-size: 0.68rem;">عطلة</td>`;
                } else if (isBlocked) {
                    rowCells += `<td class="p-1 align-middle text-center bg-light-subtle text-danger small" style="border: 1px solid #e2e8f0; font-size: 0.68rem;">🔒</td>`;
                } else {
                    const assignKey = `${absentTeacherName}__${currentD}__${p}__${absentClass}`;
                    const isAssigned = schedule.substitutions[assignKey] === tItem.name;

                    let isSameSpec = false;
                    const candSpec = tItem.specialization || '';
                    if (candSpec && absentSubj) {
                        const cleanCandSpec = candSpec.trim();
                        const cleanSubj = absentSubj.trim();
                        if (cleanCandSpec === cleanSubj || (typeof SUBJECT_MAP !== 'undefined' && SUBJECT_MAP.hasOwnProperty(cleanCandSpec) && SUBJECT_MAP[cleanCandSpec] === SUBJECT_MAP[cleanSubj])) {
                            isSameSpec = true;
                        }
                    }

                    if (isAssigned) {
                        rowCells += `
                            <td class="p-1 align-middle text-center" style="background-color: #15803d !important; color: #ffffff !important; border: 1.5px solid #16a34a;">
                                <div class="fw-bold" style="font-size: 0.75rem; color: #ffffff !important;">جهگر</div>
                            </td>
                        `;
                    } else if (absentClass) {
                        rowCells += `
                            <td class="p-1 align-middle text-center bg-warning-subtle" style="border: 1.5px solid #fde047;">
                                <button type="button" class="btn btn-sm btn-outline-success p-1 fw-bold w-100" style="font-size: 0.7rem;" onclick="assignSubstituteDirectly('${absentTeacherName.replace(/'/g, "\\'")}', ${currentD}, ${p}, '${absentClass.replace(/'/g, "\\'")}', '${tItem.name.replace(/'/g, "\\'")}')">
                                    ${isSameSpec ? '⭐ ' : ''}+ دەستنیشانکرن
                                </button>
                            </td>
                        `;
                    } else {
                        rowCells += `<td class="p-1 align-middle text-center bg-white text-success small" style="border: 1px solid #e2e8f0; font-size: 0.68rem;">شاغر</td>`;
                    }
                }
            }
            masterTeacherRows += `<tr>${rowCells}</tr>`;
        });

        mainContentHtml = `
            <div class="card border-0 shadow-sm rounded-4 overflow-hidden mb-4 bg-white">
                <div class="card-header bg-dark text-white py-2.5 px-3 d-flex justify-content-between align-items-center">
                    <h6 class="mb-0 fw-bold"><i class="fas fa-users-cog me-2 text-warning"></i>ماستری گشتی یێ شواغران (المعلمون الشاغرون فقط) - ${curDayName}</h6>
                    <span class="badge bg-light text-dark">${printableTeachers.length} مامۆستایێن بەردەست</span>
                </div>
                <div class="table-responsive">
                    <table class="table table-bordered text-center align-middle mb-0" style="table-layout: fixed;">
                        <thead>
                            <tr>${masterPeriodHeaders}</tr>
                        </thead>
                        <tbody>
                            ${masterTeacherRows}
                        </tbody>
                    </table>
                </div>
            </div>
        `;
    }

    // -------------------------------------------------------------
    // SUB-VIEW 3: Detailed Substitution Table (تۆمارا جهگران - سجل البدلاء)
    // -------------------------------------------------------------
    else if (substituteSubViewMode === 'table') {
        let tableRowsHtml = '';
        let rowIdx = 1;

        daysToProcess.forEach(d => {
            const dayName = days[d];
            for (let p = 1; p <= periodsCount; p++) {
                for (const cName of (schedule.columns || [])) {
                    const slotItem = schedule.timetables?.[cName]?.[d]?.[p];
                    if (slotItem && slotItem.teacher === absentTeacherName) {
                        const assignKey = `${absentTeacherName}__${d}__${p}__${cName}`;
                        const assignedSub = schedule.substitutions[assignKey] || '';
                        const candidates = getCandidatesForSlot(d, p, slotItem.subject);

                        const candBadgesHtml = candidates.length > 0
                            ? candidates.map(c => `
                                <button type="button" class="btn btn-sm ${c.isSameSpec ? 'btn-success' : 'btn-outline-primary'} m-0.5 py-0.5 px-1.5 shadow-sm" style="font-size: 0.72rem;" onclick="assignSubstituteDirectly('${absentTeacherName.replace(/'/g, "\\'")}', ${d}, ${p}, '${cName.replace(/'/g, "\\'")}', '${c.name.replace(/'/g, "\\'")}')">
                                    ${c.isSameSpec ? '⭐ ' : ''}${c.name} <span class="badge bg-light text-dark">${c.dailyLoad} و</span>
                                </button>
                            `).join('')
                            : `<span class="text-danger small">${t('no_free_teachers_found')}</span>`;

                        tableRowsHtml += `
                            <tr>
                                <td class="fw-bold align-middle">${rowIdx++}</td>
                                <td class="fw-bold align-middle bg-light">${dayName}</td>
                                <td class="fw-bold align-middle">${p}</td>
                                <td class="fw-bold align-middle text-danger">${cName}</td>
                                <td class="fw-bold align-middle text-primary">${translateSubjectName(slotItem.subject)}</td>
                                <td class="align-middle text-start">
                                    <div class="d-flex flex-wrap align-items-center gap-1">
                                        ${candBadgesHtml}
                                    </div>
                                </td>
                                <td class="align-middle fw-bold">
                                    ${assignedSub ? `
                                        <div class="d-flex align-items-center justify-content-between p-1 rounded" style="background-color: #15803d !important; color: #ffffff !important;">
                                            <span class="fw-bold text-truncate" style="color: #ffffff !important;">${assignedSub}</span>
                                            <button type="button" class="btn btn-link btn-sm p-0 ms-1 fw-bold" style="color: #fef08a !important;" onclick="removeSubstituteAssignment('${absentTeacherName.replace(/'/g, "\\'")}', ${d}, ${p}, '${cName.replace(/'/g, "\\'")}')" title="لابردن">
                                                <i class="fas fa-times"></i>
                                            </button>
                                        </div>
                                    ` : `
                                        <span class="text-muted small">چاوەڕوانە...</span>
                                    `}
                                </td>
                            </tr>
                        `;
                    }
                }
            }
        });

        mainContentHtml = `
            <div class="card border-0 shadow-sm rounded-4 overflow-hidden mb-4 bg-white">
                <div class="card-header bg-dark text-white py-2.5 px-3 d-flex justify-content-between align-items-center">
                    <h6 class="mb-0 fw-bold"><i class="fas fa-list-alt me-2 text-warning"></i>تۆمارا رۆژانە یا پڕکرنا وانەیان (سجل البدلاء)</h6>
                    <span class="badge bg-light text-dark">${totalSlotsCount} وانە</span>
                </div>
                <div class="table-responsive">
                    <table class="table table-bordered text-center align-middle mb-0">
                        <thead class="bg-light">
                            <tr>
                                <th style="width: 40px;">#</th>
                                <th style="width: 100px;">${t('val_day_lbl') || 'ڕۆژ'}</th>
                                <th style="width: 60px;">${t('day_period') || 'وانە'}</th>
                                <th style="width: 90px;">${t('class_label')}</th>
                                <th style="width: 120px;">${t('subject_label')}</th>
                                <th>مامۆستایێن بەتاڵ (المتاحون للبديل)</th>
                                <th style="width: 180px;">${t('substitute_teacher_col')}</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${tableRowsHtml || `<tr><td colspan="7" class="text-muted py-4">${t('no_slots_absent_teacher')}</td></tr>`}
                        </tbody>
                    </table>
                </div>
            </div>
        `;
    }

    container.innerHTML = subViewBarHtml + mainContentHtml;
}

function buildSubstitutePrintableHtml(arg1, arg2, arg3, arg4) {
    let schedule = allSchedules[activeScheduleName] || (typeof allSchedules === 'object' && Object.values(allSchedules)[0]);
    let absentTeacherName = '';
    let selectedDayVal = 'all';
    let activeFormat = 'all';

    if (arg1 && typeof arg1 === 'object' && arg1.teachers) {
        schedule = arg1;
        absentTeacherName = arg2 || '';
        selectedDayVal = arg3 || 'all';
        activeFormat = arg4 || 'all';
    } else {
        absentTeacherName = arg1 || '';
        selectedDayVal = arg2 || 'all';
        activeFormat = arg3 || 'all';
    }

    if (!schedule) return null;

    const defaultDaysKurdish = ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
    const savedDays = schedule.settings?.workDays || defaultDaysKurdish;
    const localizedWorkDays = typeof t === 'function' ? t('work_days') : defaultDaysKurdish;
    const days = savedDays.map((dStr) => {
        const indexInKurdish = typeof ALL_DAYS_KURDISH !== 'undefined' ? ALL_DAYS_KURDISH.indexOf(dStr) : -1;
        if (indexInKurdish !== -1 && Array.isArray(localizedWorkDays) && localizedWorkDays[indexInKurdish]) {
            return localizedWorkDays[indexInKurdish];
        }
        return dStr;
    });
    const periodsCount = schedule.settings?.periodsPerDay || schedule.periodsCount || 7;
    const schoolName = schedule.settings?.globalSchoolName || schedule.schoolName || schedule.milak?.schoolName || '';
    const principalName = schedule.settings?.principalName || schedule.principalName || '';
    const allTeachers = schedule.teachers || [];

    // Days to show based on selectedDayVal
    const daysToProcess = selectedDayVal === 'all'
        ? days.map((_, idx) => idx)
        : [parseInt(selectedDayVal, 10)].filter(idx => !isNaN(idx) && idx >= 0 && idx < days.length);

    // -------------------------------------------------------------
    // 0. SECTION: Weekly Master Schedule for All Teachers (ماستری گشتی یێ هەفتیانە لكافة المعلمين)
    // -------------------------------------------------------------
    const totalPeriods = daysToProcess.length * periodsCount;
    const teacherFirstColWidthPct = totalPeriods >= 30 ? 6.5 : (totalPeriods >= 20 ? 8 : 10);
    const teacherPeriodColWidthPct = ((100 - teacherFirstColWidthPct) / Math.max(1, totalPeriods)).toFixed(3);

    const classFirstColWidthPct = totalPeriods >= 30 ? 5.5 : (totalPeriods >= 20 ? 7 : 9);
    const classPeriodColWidthPct = ((100 - classFirstColWidthPct) / Math.max(1, totalPeriods)).toFixed(3);

    let baseFontSize = 7;
    let headerPeriodFontSize = 6.5;
    let cellMainFontSize = 6.2;
    let cellSubFontSize = 5.2;

    if (totalPeriods >= 35) {
        baseFontSize = 5.2;
        headerPeriodFontSize = 4.8;
        cellMainFontSize = 4.8;
        cellSubFontSize = 4.2;
    } else if (totalPeriods >= 28) {
        baseFontSize = 5.8;
        headerPeriodFontSize = 5.3;
        cellMainFontSize = 5.4;
        cellSubFontSize = 4.6;
    } else if (totalPeriods >= 20) {
        baseFontSize = 6.5;
        headerPeriodFontSize = 5.8;
        cellMainFontSize = 6.0;
        cellSubFontSize = 5.0;
    }

    const teacherCount = allTeachers.length;
    let targetRowHeight = 22;
    let cellPadding = '2.5px 1px';
    if (teacherCount <= 12) {
        targetRowHeight = 36;
        cellPadding = '6px 1px';
    } else if (teacherCount <= 18) {
        targetRowHeight = 28;
        cellPadding = '4.5px 1px';
    } else if (teacherCount <= 24) {
        targetRowHeight = 20;
        cellPadding = '2.5px 1px';
    } else if (teacherCount <= 32) {
        targetRowHeight = 15;
        cellPadding = '1px 0.5px';
    } else if (teacherCount <= 42) {
        targetRowHeight = 13;
        cellPadding = '0.5px';
    } else {
        targetRowHeight = 11.5;
        cellPadding = '0.5px';
    }

    let wmThead = `
        <thead class="table-light">
            <tr style="height: 22px;">
                <th rowspan="2" class="align-middle bg-secondary text-white" style="height: 44px; width: ${teacherFirstColWidthPct}%; max-width: ${teacherFirstColWidthPct}%; min-width: 0 !important; border: 2px solid #000 !important; border-right: 2px solid #000 !important; border-left: 2px solid #000 !important; font-size: ${baseFontSize}pt; padding: 2px 1px;">${t('col_teacher')}</th>
    `;
    daysToProcess.forEach(d => {
        const dayName = days[d];
        wmThead += `<th colspan="${periodsCount}" class="border-start border-end border-dark" style="height: 22px; border: 2px solid #000 !important; background: #fff !important; color: #000 !important; font-weight: bold; font-size: ${baseFontSize}pt; padding: 2px 1px;">${dayName}</th>`;
    });
    wmThead += `</tr><tr style="height: 22px;">`;
    daysToProcess.forEach(d => {
        for (let p = 1; p <= periodsCount; p++) {
            wmThead += `<th class="${p === 1 ? 'border-start border-dark' : ''} ${p === periodsCount ? 'border-end border-dark' : ''}" style="height: 22px; width: ${teacherPeriodColWidthPct}%; max-width: ${teacherPeriodColWidthPct}%; min-width: 0 !important; padding: 1px 0.5px; border: 1.5px solid #000 !important; background: #fff !important; color: #000 !important; font-weight: bold; font-size: ${headerPeriodFontSize}pt;">${p}</th>`;
        }
    });
    wmThead += `</tr></thead>`;

    let wmMasterRowsHtml = '';
    allTeachers.forEach(tItem => {
        const tName = tItem.name;
        let rowCells = `<td class="fw-bold bg-light" style="height: ${targetRowHeight}px; min-height: ${targetRowHeight}px; width: ${teacherFirstColWidthPct}%; max-width: ${teacherFirstColWidthPct}%; min-width: 0 !important; border: 1.5px solid #000 !important; border-right: 2px solid #000 !important; border-left: 2px solid #000 !important; padding: ${cellPadding} !important; font-size: ${baseFontSize}pt; line-height: 1.15; word-break: break-word; white-space: normal; overflow: hidden; vertical-align: middle;">${tName}</td>`;

        daysToProcess.forEach(d => {
            const dayName = days[d];
            const rawDayName = typeof ALL_DAYS_KURDISH !== 'undefined' ? (ALL_DAYS_KURDISH[d] || dayName) : dayName;
            const offDays = tItem.offDays || [];
            const isOffDay = offDays.includes(dayName) || offDays.includes(rawDayName);
            const blocked = tItem.blockedPeriods || {};
            const blockedPeriods = blocked[dayName] || blocked[rawDayName] || [];

            for (let p = 1; p <= periodsCount; p++) {
                const isBlocked = Array.isArray(blockedPeriods) && blockedPeriods.includes(p);
                const borderClass = (p === 1 ? 'border-start border-dark ' : '') + (p === periodsCount ? 'border-end border-dark ' : '');

                let foundClass = '', foundSubject = '';
                for (const c of (schedule.columns || [])) {
                    const item = schedule.timetables?.[c]?.[d]?.[p];
                    if (item && item.teacher === tName) {
                        foundClass = c;
                        foundSubject = item.subject;
                        break;
                    }
                }

                if (foundClass) {
                    const assignKey = `${tName}__${d}__${p}__${foundClass}`;
                    const assignedSub = schedule.substitutions?.[assignKey] || '';

                    if (assignedSub) {
                        const subDisplayName = (getSmartTeacherDisplayName(assignedSub, allTeachers) || assignedSub).trim().split(/\s+/)[0];
                        rowCells += `
                            <td class="${borderClass}" style="height: ${targetRowHeight}px; min-height: ${targetRowHeight}px; width: ${teacherPeriodColWidthPct}%; max-width: ${teacherPeriodColWidthPct}%; min-width: 0 !important; padding: ${cellPadding} !important; overflow:hidden; border: 1px solid #000 !important; vertical-align: middle; background-color: #dcfce7 !important;">
                                <div class="fw-bold text-success" style="font-size: ${cellMainFontSize}pt; line-height:1.1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="البديل: ${assignedSub}">${subDisplayName}</div>
                                <div class="text-muted fw-bold" style="font-size: ${cellSubFontSize}pt; line-height:1.05; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${foundClass}</div>
                            </td>
                        `;
                    } else {
                        const teacherFirstName = (getSmartTeacherDisplayName(tName, allTeachers) || tName).trim().split(/\s+/)[0];
                        const isTeacherAbsentHere = isTeacherOnLeave(tName, d, schedule);
                        rowCells += `
                            <td class="${borderClass}" style="height: ${targetRowHeight}px; min-height: ${targetRowHeight}px; width: ${teacherPeriodColWidthPct}%; max-width: ${teacherPeriodColWidthPct}%; min-width: 0 !important; padding: ${cellPadding} !important; overflow:hidden; border: 1px solid #000 !important; vertical-align: middle; ${isTeacherAbsentHere ? 'background-color: #fee2e2 !important;' : ''}">
                                <div class="fw-bold ${isTeacherAbsentHere ? 'text-danger' : 'text-primary'}" style="font-size: ${cellMainFontSize}pt; line-height:1.1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${teacherFirstName}</div>
                                <div class="${isTeacherAbsentHere ? 'text-danger' : 'text-muted'} fw-bold" style="font-size: ${cellSubFontSize}pt; line-height:1.05; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${foundClass}</div>
                            </td>
                        `;
                    }
                } else if (isOffDay) {
                    rowCells += `<td class="${borderClass}" style="height: ${targetRowHeight}px; min-height: ${targetRowHeight}px; width: ${teacherPeriodColWidthPct}%; max-width: ${teacherPeriodColWidthPct}%; min-width: 0 !important; padding: ${cellPadding} !important; overflow:hidden; border: 1px solid #000 !important; vertical-align: middle;"><div class="text-muted small" style="font-size: ${cellSubFontSize}pt;">عطلة</div></td>`;
                } else if (isBlocked) {
                    rowCells += `<td class="${borderClass}" style="height: ${targetRowHeight}px; min-height: ${targetRowHeight}px; width: ${teacherPeriodColWidthPct}%; max-width: ${teacherPeriodColWidthPct}%; min-width: 0 !important; padding: ${cellPadding} !important; overflow:hidden; border: 1px solid #000 !important; vertical-align: middle;"><div class="text-danger small" style="font-size: ${cellSubFontSize}pt;">🔒</div></td>`;
                } else {
                    let subClassAssigned = '';
                    let absentTeacherCovered = '';
                    for (const [subKey, subTeacher] of Object.entries(schedule.substitutions || {})) {
                        if (subTeacher === tName) {
                            const parts = subKey.split('__');
                            if (parts.length >= 4 && parseInt(parts[1], 10) === d && parseInt(parts[2], 10) === p) {
                                absentTeacherCovered = parts[0];
                                subClassAssigned = parts[3];
                                break;
                            }
                        }
                    }
                    if (subClassAssigned) {
                        const subCoveredFirst = absentTeacherCovered ? absentTeacherCovered.trim().split(/\s+/)[0] : '';
                        const subLabel = subCoveredFirst ? subCoveredFirst : (isAr ? 'بديل' : 'جهگر');
                        rowCells += `
                            <td class="${borderClass}" style="height: ${targetRowHeight}px; min-height: ${targetRowHeight}px; width: ${teacherPeriodColWidthPct}%; max-width: ${teacherPeriodColWidthPct}%; min-width: 0 !important; padding: ${cellPadding} !important; overflow:hidden; border: 1px solid #000 !important; vertical-align: middle; background-color: #dcfce7 !important;">
                                <div class="fw-bold text-success" style="font-size: ${cellMainFontSize}pt; line-height:1.1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${subLabel}</div>
                                <div class="text-success fw-bold" style="font-size: ${cellSubFontSize}pt; line-height:1.05; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${subClassAssigned}</div>
                            </td>
                        `;
                    } else {
                        rowCells += `<td class="${borderClass}" style="height: ${targetRowHeight}px; min-height: ${targetRowHeight}px; width: ${teacherPeriodColWidthPct}%; max-width: ${teacherPeriodColWidthPct}%; min-width: 0 !important; padding: ${cellPadding} !important; overflow:hidden; border: 1px solid #000 !important; vertical-align: middle;"></td>`;
                    }
                }
            }
        });

        wmMasterRowsHtml += `<tr style="height: ${targetRowHeight}px;">${rowCells}</tr>`;
    });

    const masterTitle = t('sub_leave_teacher_schedule_title', 'جدول بدل معلم مجاز');
    const masterFullTitle = `${masterTitle}${schoolName ? ' - ' + schoolName : ''}`;

    const weeklyMasterSection = `
        <h3 class="text-center mb-2" style="font-size: 12.5pt !important; font-weight: bold; color: #000; margin-top: 0; margin-bottom: 6px !important;">${masterFullTitle}</h3>
        <div class="table-responsive" style="overflow: visible !important; width: 100% !important; max-width: 100% !important;">
            <table class="table table-bordered text-center align-middle preserve-table-styles" style="font-size: ${baseFontSize}pt; width: 100% !important; max-width: 100% !important; table-layout: fixed !important; border-collapse: collapse !important; border: 2px solid #000 !important; margin: 0 !important;">
                ${wmThead}
                <tbody>
                    ${wmMasterRowsHtml}
                </tbody>
            </table>
        </div>
        <div class="print-signature-wrapper" style="display: block; width: 100%; margin-top: 6px; clear: both; page-break-inside: avoid;">
            <div class="print-signature-left" style="float: left; text-align: center; width: 220px; direction: rtl; margin-left: 20px;">
                <p class="mb-0" style="font-size: 8.5pt; font-weight: bold; margin-bottom: 2px;">${t('signature_approved_by')}</p>
                <p class="fw-bold mb-0" style="font-size: 8.5pt; margin-bottom: 2px;">${t('signature_principal')}</p>
                <p class="fw-bold mb-0" style="font-size: 8.5pt; margin-top: 2px; margin-bottom: 0;">${principalName || '................................'}</p>
            </div>
            <div style="clear: both;"></div>
        </div>
    `;

    if (activeFormat === 'weekly_master') {
        return weeklyMasterSection;
    }

    // -------------------------------------------------------------
    // SECTION: Weekly Master Classes Timetable with Substitutes (ماستری پۆلان ل گەل بەدیلان)
    // -------------------------------------------------------------
    const classCount = (schedule.columns || []).length;
    let classTargetRowHeight = 22;
    let classCellPadding = '2.5px 1px';
    if (classCount <= 12) {
        classTargetRowHeight = 38;
        classCellPadding = '7px 1px';
    } else if (classCount <= 18) {
        classTargetRowHeight = 30;
        classCellPadding = '5px 1px';
    } else if (classCount <= 26) {
        classTargetRowHeight = 23;
        classCellPadding = '3.5px 1px';
    } else if (classCount <= 36) {
        classTargetRowHeight = 17.5;
        classCellPadding = '2px 0.5px';
    } else {
        classTargetRowHeight = 14;
        classCellPadding = '1px 0.5px';
    }

    let wmcThead = `
        <thead class="table-light">
            <tr style="height: 22px;">
                <th rowspan="2" class="align-middle bg-secondary text-white" style="height: 44px; width: ${classFirstColWidthPct}%; max-width: ${classFirstColWidthPct}%; min-width: 0 !important; border: 2px solid #000 !important; border-right: 2px solid #000 !important; border-left: 2px solid #000 !important; font-size: ${baseFontSize}pt; padding: 2px 1px;">${t('col_class') || 'پۆل'}</th>
    `;
    daysToProcess.forEach(d => {
        const dayName = days[d];
        wmcThead += `<th colspan="${periodsCount}" class="border-start border-end border-dark" style="height: 22px; border: 2px solid #000 !important; background: #fff !important; color: #000 !important; font-weight: bold; font-size: ${baseFontSize}pt; padding: 2px 1px;">${dayName}</th>`;
    });
    wmcThead += `</tr><tr style="height: 22px;">`;
    daysToProcess.forEach(d => {
        for (let p = 1; p <= periodsCount; p++) {
            wmcThead += `<th class="${p === 1 ? 'border-start border-dark' : ''} ${p === periodsCount ? 'border-end border-dark' : ''}" style="height: 22px; width: ${classPeriodColWidthPct}%; max-width: ${classPeriodColWidthPct}%; min-width: 0 !important; padding: 1px 0.5px; border: 1.5px solid #000 !important; background: #fff !important; color: #000 !important; font-weight: bold; font-size: ${headerPeriodFontSize}pt;">${p}</th>`;
        }
    });
    wmcThead += `</tr></thead>`;

    let wmcMasterRowsHtml = '';
    (schedule.columns || []).forEach(className => {
        let rowCells = `<td class="fw-bold bg-light" style="height: ${classTargetRowHeight}px; min-height: ${classTargetRowHeight}px; width: ${classFirstColWidthPct}%; max-width: ${classFirstColWidthPct}%; min-width: 0 !important; border: 1.5px solid #000 !important; border-right: 2px solid #000 !important; border-left: 2px solid #000 !important; padding: ${classCellPadding} !important; font-size: ${baseFontSize}pt; line-height: 1.15; word-break: break-word; white-space: normal; overflow: hidden; vertical-align: middle;">${className}</td>`;

        daysToProcess.forEach(d => {
            for (let p = 1; p <= periodsCount; p++) {
                const borderClass = (p === 1 ? 'border-start border-dark ' : '') + (p === periodsCount ? 'border-end border-dark ' : '');
                const item = schedule.timetables?.[className]?.[d]?.[p];

                if (item && item.teacher) {
                    const originalTeacher = item.teacher;
                    const foundSubject = item.subject || '';
                    const assignKey = `${originalTeacher}__${d}__${p}__${className}`;
                    const assignedSub = schedule.substitutions?.[assignKey] || '';

                    if (assignedSub) {
                        const subDisplayName = getSmartTeacherDisplayName(assignedSub, allTeachers);
                        rowCells += `
                            <td class="${borderClass}" style="height: ${classTargetRowHeight}px; min-height: ${classTargetRowHeight}px; width: ${classPeriodColWidthPct}%; max-width: ${classPeriodColWidthPct}%; min-width: 0 !important; padding: ${classCellPadding} !important; overflow:hidden; border: 1px solid #000 !important; vertical-align: middle;">
                                <div class="fw-bold text-success" style="font-size: ${cellMainFontSize}pt; line-height:1.1; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${subDisplayName}</div>
                                <div class="text-muted" style="font-size: ${cellSubFontSize}pt; line-height:1.05; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${translateSubjectName(foundSubject)} (${getTeacherDisplayName(originalTeacher)})</div>
                            </td>
                        `;
                    } else {
                        const isAbsent = isTeacherOnLeave(originalTeacher, d, schedule) || (absentTeacherName && originalTeacher === absentTeacherName && absentTeacherName !== 'all_teachers');
                        if (isAbsent) {
                            rowCells += `
                                <td class="${borderClass}" style="height: ${classTargetRowHeight}px; min-height: ${classTargetRowHeight}px; width: ${classPeriodColWidthPct}%; max-width: ${classPeriodColWidthPct}%; min-width: 0 !important; padding: ${classCellPadding} !important; overflow:hidden; border: 1.5px dashed #dc2626 !important; background-color: #fee2e2 !important; vertical-align: middle;">
                                    <div class="fw-bold text-danger" style="font-size: ${cellMainFontSize}pt; line-height:1.1; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${translateSubjectName(foundSubject)}</div>
                                    <div class="text-danger fw-bold" style="font-size: ${cellSubFontSize}pt; line-height:1.05; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">[شاغر] ${getTeacherDisplayName(originalTeacher)}</div>
                                </td>
                            `;
                        } else {
                            rowCells += `
                                <td class="${borderClass}" style="height: ${classTargetRowHeight}px; min-height: ${classTargetRowHeight}px; width: ${classPeriodColWidthPct}%; max-width: ${classPeriodColWidthPct}%; min-width: 0 !important; padding: ${classCellPadding} !important; overflow:hidden; border: 1px solid #000 !important; vertical-align: middle;">
                                    <div class="fw-bold text-primary" style="font-size: ${cellMainFontSize}pt; line-height:1.1; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${translateSubjectName(foundSubject)}</div>
                                    <div class="text-muted" style="font-size: ${cellSubFontSize}pt; line-height:1.05; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${getTeacherDisplayName(originalTeacher)}</div>
                                </td>
                            `;
                        }
                    }
                } else {
                    rowCells += `<td class="${borderClass}" style="height: ${classTargetRowHeight}px; min-height: ${classTargetRowHeight}px; width: ${classPeriodColWidthPct}%; max-width: ${classPeriodColWidthPct}%; min-width: 0 !important; padding: ${classCellPadding} !important; overflow:hidden; border: 1px solid #000 !important; vertical-align: middle;"></td>`;
                }
            }
        });
        wmcMasterRowsHtml += `<tr style="height: ${classTargetRowHeight}px;">${rowCells}</tr>`;
    });

    const classMasterTitle = t('sub_leave_teacher_schedule_title', 'جدول بدل معلم مجاز');
    const classMasterFullTitle = `${classMasterTitle}${schoolName ? ' - ' + schoolName : ''}`;

    const weeklyMasterClassesSection = `
        <h3 class="text-center mb-3" style="font-size: 13.5pt !important; font-weight: bold; color: #000;">${classMasterFullTitle}</h3>
        <div class="table-responsive" style="overflow: visible !important; width: 100% !important; max-width: 100% !important;">
            <table class="table table-bordered text-center align-middle preserve-table-styles" style="font-size: ${baseFontSize}pt; width: 100% !important; max-width: 100% !important; table-layout: fixed !important; border-collapse: collapse !important; border: 2px solid #000 !important; margin: 0 !important;">
                ${wmcThead}
                <tbody>
                    ${wmcMasterRowsHtml}
                </tbody>
            </table>
        </div>
        <div class="print-signature-wrapper" style="display: block; width: 100%; margin-top: 14px; clear: both; page-break-inside: avoid;">
            <div class="print-signature-left" style="float: left; text-align: center; width: 220px; direction: rtl; margin-left: 20px;">
                <p class="mb-0" style="font-size: 8.5pt; font-weight: bold; margin-bottom: 2px;">${t('signature_approved_by')}</p>
                <p class="fw-bold mb-0" style="font-size: 8.5pt; margin-bottom: 2px;">${t('signature_principal')}</p>
                <p class="fw-bold mb-0" style="font-size: 8.5pt; margin-top: 2px; margin-bottom: 0;">${principalName || '................................'}</p>
            </div>
            <div style="clear: both;"></div>
        </div>
    `;

    if (activeFormat === 'weekly_master_classes') {
        return weeklyMasterClassesSection;
    }

    if (activeFormat === 'vacancies_master') {
        return weeklyMasterSection;
    }

    // Count total slots of absent teacher (if absent teacher given)
    let totalSlots = 0;
    if (absentTeacherName) {
        daysToProcess.forEach(d => {
            for (let p = 1; p <= periodsCount; p++) {
                for (const cName of (schedule.columns || [])) {
                    if (schedule.timetables?.[cName]?.[d]?.[p]?.teacher === absentTeacherName) {
                        totalSlots++;
                    }
                }
            }
        });
    }

    // -------------------------------------------------------------
    // 1. SECTION: Grid View (خشتێ گشتی یێ مامۆستایێ مۆڵەتپێدای - التصميم النظيف)
    // -------------------------------------------------------------
    let periodHeaders = `<th style="width: 14%; background-color: #eff6ff; color: #2563eb; font-weight: bold; border: 1px solid #bfdbfe; font-size: 10pt; padding: 8px; text-align: center;">اليوم / الحصة</th>`;
    for (let p = 1; p <= periodsCount; p++) {
        periodHeaders += `<th style="width: ${(86 / periodsCount).toFixed(2)}%; background-color: #eff6ff; color: #2563eb; font-weight: bold; border: 1px solid #bfdbfe; font-size: 10.5pt; padding: 8px; text-align: center;">${p}</th>`;
    }

    const targetGridTeachers = (absentTeacherName === 'all_teachers' || !absentTeacherName)
        ? (schedule.teachers || [])
        : (schedule.teachers || []).filter(t => t.name === absentTeacherName);

    let gridSectionHtml = '';

    targetGridTeachers.forEach((tItem, tIdx) => {
        const curTName = tItem.name;
        const curTSpec = tItem.specialization || '';
        let curTotalSlots = 0;
        let curAssignedSlots = 0;
        let matrixRowsHtml = '';

        daysToProcess.forEach(d => {
            const dayName = days[d];
            matrixRowsHtml += `<tr><td style="font-weight: bold; background-color: #ffffff; color: #1e293b; border: 1px solid #dbeafe; padding: 8px; font-size: 10pt; text-align: center;">${dayName}</td>`;
            for (let p = 1; p <= periodsCount; p++) {
                let foundClass = '', foundSubject = '';
                for (const c of (schedule.columns || [])) {
                    const item = schedule.timetables?.[c]?.[d]?.[p];
                    if (item && item.teacher === curTName) {
                        foundClass = c;
                        foundSubject = item.subject;
                        break;
                    }
                }

                if (foundClass) {
                    curTotalSlots++;
                    const assignKey = `${curTName}__${d}__${p}__${foundClass}`;
                    const assignedSub = schedule.substitutions?.[assignKey] || '';
                    if (assignedSub) curAssignedSlots++;

                    matrixRowsHtml += `
                        <td style="border: 1px solid #dbeafe; padding: 6px 4px; vertical-align: middle; background-color: #ffffff; text-align: center; height: 55px;">
                            <div style="font-weight: bold; color: #dc2626; font-size: 10.5pt; line-height: 1.2;">فصل ${foundClass}</div>
                            <div style="color: #64748b; font-size: 8.5pt; margin-top: 2px; line-height: 1.1;">${translateSubjectName(foundSubject)}</div>
                            ${assignedSub ? `
                                <div style="background-color: #15803d; color: #ffffff; font-weight: bold; font-size: 7.5pt; padding: 2px 6px; border-radius: 4px; display: inline-block; margin-top: 3px;">
                                    ${assignedSub}
                                </div>
                            ` : ''}
                        </td>
                    `;
                } else {
                    matrixRowsHtml += `<td style="border: 1px solid #dbeafe; padding: 6px; background-color: #ffffff; text-align: center; height: 55px;"></td>`;
                }
            }
            matrixRowsHtml += `</tr>`;
        });

        const pageBreakStyle = (targetGridTeachers.length > 1 && tIdx > 0 && tIdx % 2 === 0) ? 'page-break-before: always;' : '';

        gridSectionHtml += `
            <div style="margin-bottom: 30px; ${pageBreakStyle}">
                <div style="text-align: center; margin-bottom: 12px;">
                    <h3 style="font-size: 13pt; font-weight: bold; color: #1e293b; margin: 0 0 4px 0;">
                        اسم المعلم: ${curTName} ${curTSpec ? `<span style="font-size: 10pt; color: #64748b; font-weight: normal;">(${translateSubjectName(curTSpec)})</span>` : ''}
                    </h3>
                </div>
                <table class="table table-bordered text-center align-middle" style="width: 100%; border-collapse: collapse; border: 1.5px solid #bfdbfe; font-size: 9.5pt; table-layout: fixed; margin: 0 auto;">
                    <thead>
                        <tr>${periodHeaders}</tr>
                    </thead>
                    <tbody>
                        ${matrixRowsHtml}
                    </tbody>
                </table>
            </div>
        `;
    });

    const gridSection = gridSectionHtml || `
        <div style="margin-bottom: 25px;">
            <p class="text-center text-muted">هیچ جدولێک نەدۆزرایەوە</p>
        </div>
    `;

    // -------------------------------------------------------------
    // 2. SECTION: Master Teachers Availability (ماسترێ شواغران لكافة المعلمين)
    // -------------------------------------------------------------
    const currentD = selectedDayVal === 'all' ? 0 : parseInt(selectedDayVal, 10);
    const curDayName = days[currentD] || days[0];
    const rawDayName = typeof ALL_DAYS_KURDISH !== 'undefined' ? (ALL_DAYS_KURDISH[currentD] || curDayName) : curDayName;

    let masterPeriodHeaders = `<th style="width: 160px; background-color: #1e293b; color: #fff; padding: 6px;">${t('col_teacher')}</th>`;
    for (let p = 1; p <= periodsCount; p++) {
        let absentSlotClass = '';
        for (const c of (schedule.columns || [])) {
            const item = schedule.timetables?.[c]?.[currentD]?.[p];
            if (item && item.teacher === absentTeacherName) { absentSlotClass = c; break; }
        }
        masterPeriodHeaders += `
            <th style="background-color: ${absentSlotClass ? '#dc2626' : '#334155'}; color: #fff; padding: 6px; font-size: 8.5pt;">
                <div>${t('day_period') || 'وانە'} ${p}</div>
                ${absentSlotClass ? `<div style="background-color:#fef08a; color:#854d0e; font-size:7pt; padding:1px 3px; border-radius:3px; margin-top:2px;">پێدڤی ب جهگرە (${absentSlotClass})</div>` : ''}
            </th>
        `;
    }

    let masterTeacherRows = '';
    // Absent teacher first
    let absentCells = `<td style="font-weight: bold; background-color: #dc2626; color: #fff; text-align: right; padding: 6px;">
        ${absentTeacherName || 'مامۆستا'} (المجاز)
    </td>`;
    for (let p = 1; p <= periodsCount; p++) {
        let foundC = '', foundS = '';
        for (const c of (schedule.columns || [])) {
            const item = schedule.timetables?.[c]?.[currentD]?.[p];
            if (item && item.teacher === absentTeacherName) { foundC = c; foundS = item.subject; break; }
        }
        if (foundC) {
            const assignKey = `${absentTeacherName}__${currentD}__${p}__${foundC}`;
            const assignedSub = schedule.substitutions?.[assignKey] || '';
            absentCells += `
                <td style="background-color: #fee2e2; color: #991b1b; font-weight: bold; padding: 6px; border: 1.5px solid #f87171;">
                    <div>${foundC} - ${translateSubjectName(foundS)}</div>
                    ${assignedSub ? `<div style="background-color: #16a34a; color: #fff; padding: 2px 4px; border-radius: 4px; font-size: 8pt; margin-top: 3px;">${isAr ? 'البديل: ' : 'جهگر: '}${assignedSub}</div>` : `<div style="background-color: #dc2626; color: #fff; padding: 2px 4px; border-radius: 4px; font-size: 7.5pt; margin-top: 3px;">شاغر (مطلوب بديل)</div>`}
                </td>
            `;
        } else {
            absentCells += `<td style="background-color: #f8fafc; color: #94a3b8; padding: 6px; border: 1px solid #cbd5e1;">—</td>`;
        }
    }
    masterTeacherRows += `<tr>${absentCells}</tr>`;

    // Filter other teachers: ONLY show teachers with at least one free slot (شاغر)
    const printableTeachersWithVacancies = [];
    allTeachers.forEach(tItem => {
        if (tItem.name === absentTeacherName) return;

        let freeSlotsCount = 0;
        let freeSubstituteSlotsCount = 0;
        let totalTeachingToday = 0;

        for (let p = 1; p <= periodsCount; p++) {
            let absentClass = '';
            for (const c of (schedule.columns || [])) {
                const item = schedule.timetables?.[c]?.[currentD]?.[p];
                if (item && item.teacher === absentTeacherName) { absentClass = c; break; }
            }

            let isBusy = false;
            for (const c of (schedule.columns || [])) {
                const item = schedule.timetables?.[c]?.[currentD]?.[p];
                if (item && item.teacher === tItem.name) { isBusy = true; break; }
            }
            if (isBusy) totalTeachingToday++;

            const offDays = tItem.offDays || [];
            const isOffDay = offDays.includes(curDayName) || offDays.includes(rawDayName);
            const blocked = tItem.blockedPeriods || {};
            const blockedPeriods = blocked[curDayName] || blocked[rawDayName] || [];
            const isBlocked = Array.isArray(blockedPeriods) && blockedPeriods.includes(p);

            if (!isBusy && !isOffDay && !isBlocked) {
                freeSlotsCount++;
                if (absentClass) {
                    freeSubstituteSlotsCount++;
                }
            }
        }

        if (freeSlotsCount > 0) {
            // Strictly exclude administrative staff
            if (typeof isAdministrativeStaff === 'function' && isAdministrativeStaff(tItem, schedule)) return;

            printableTeachersWithVacancies.push({
                teacher: tItem,
                freeSlotsCount,
                freeSubstituteSlotsCount,
                totalTeachingToday,
                isAdmin: false
            });
        }
    });

    printableTeachersWithVacancies.sort((a, b) => {
        if (a.isAdmin !== b.isAdmin) return a.isAdmin ? 1 : -1;
        if (a.freeSubstituteSlotsCount !== b.freeSubstituteSlotsCount) {
            return b.freeSubstituteSlotsCount - a.freeSubstituteSlotsCount;
        }
        return a.totalTeachingToday - b.totalTeachingToday;
    });

    printableTeachersWithVacancies.forEach(wrap => {
        const tItem = wrap.teacher;

        let rowCells = `
            <td style="font-weight: bold; background-color: #f1f5f9; text-align: right; padding: 6px; border: 1px solid #cbd5e1;">
                <div>${tItem.name}</div>
                <div style="font-size: 7.5pt; color: #64748b;">${translateSubjectName(tItem.specialization || '')}</div>
            </td>
        `;

        for (let p = 1; p <= periodsCount; p++) {
            let absentClass = '', absentSubj = '';
            for (const c of (schedule.columns || [])) {
                const item = schedule.timetables?.[c]?.[currentD]?.[p];
                if (item && item.teacher === absentTeacherName) { absentClass = c; absentSubj = item.subject; break; }
            }

            let isBusyClass = '', isBusySubject = '';
            for (const c of (schedule.columns || [])) {
                const item = schedule.timetables?.[c]?.[currentD]?.[p];
                if (item && item.teacher === tItem.name) { isBusyClass = c; isBusySubject = item.subject; break; }
            }

            const offDays = tItem.offDays || [];
            const isOffDay = offDays.includes(curDayName) || offDays.includes(rawDayName);
            const blocked = tItem.blockedPeriods || {};
            const blockedPeriods = blocked[curDayName] || blocked[rawDayName] || [];
            const isBlocked = Array.isArray(blockedPeriods) && blockedPeriods.includes(p);

            if (isBusyClass) {
                rowCells += `
                    <td style="background-color: #fff; padding: 4px; border: 1px solid #cbd5e1;">
                        <span style="background-color: #64748b; color: #fff; font-size: 7.5pt; font-weight: bold; padding: 1px 4px; border-radius: 3px;">${isBusyClass}</span>
                        <div style="font-size: 7.5pt; color: #64748b; margin-top: 2px;">${translateSubjectName(isBusySubject)}</div>
                    </td>
                `;
            } else if (isOffDay) {
                rowCells += `<td style="background-color: #f8fafc; color: #64748b; font-size: 7.5pt; padding: 4px; border: 1px solid #cbd5e1;">عطلة</td>`;
            } else if (isBlocked) {
                rowCells += `<td style="background-color: #f8fafc; color: #dc2626; font-size: 7.5pt; padding: 4px; border: 1px solid #cbd5e1;">محظور 🔒</td>`;
            } else {
                const assignKey = `${absentTeacherName}__${currentD}__${p}__${absentClass}`;
                const isAssigned = schedule.substitutions?.[assignKey] === tItem.name;

                let isSameSpec = false;
                const candSpec = tItem.specialization || '';
                if (candSpec && absentSubj) {
                    const cleanCandSpec = candSpec.trim();
                    const cleanSubj = absentSubj.trim();
                    if (cleanCandSpec === cleanSubj || (typeof SUBJECT_MAP !== 'undefined' && SUBJECT_MAP.hasOwnProperty(cleanCandSpec) && SUBJECT_MAP[cleanCandSpec] === SUBJECT_MAP[cleanSubj])) {
                        isSameSpec = true;
                    }
                }

                if (isAssigned) {
                    rowCells += `
                        <td style="background-color: #dcfce7; color: #166534; font-weight: bold; padding: 4px; border: 1.5px solid #16a34a;">
                            <div style="font-size: 8pt;">جهگرێ دیاریکری</div>
                        </td>
                    `;
                } else if (absentClass) {
                    rowCells += `
                        <td style="background-color: #f0fdf4; color: #15803d; font-weight: bold; padding: 4px; border: 1.5px solid #86efac;">
                            <div style="font-size: 8pt;">${isSameSpec ? '⭐ ' : ''}شاغر (متاح للبديل)</div>
                        </td>
                    `;
                } else {
                    rowCells += `
                        <td style="background-color: #fff; color: #16a34a; font-size: 7.5pt; padding: 4px; border: 1px solid #cbd5e1;">
                            شاغر
                        </td>
                    `;
                }
            }
        }
        masterTeacherRows += `<tr>${rowCells}</tr>`;
    });

    const masterTeachersSection = `
        <div style="margin-bottom: 25px;">
            <h4 style="margin-bottom: 10px; font-weight: bold; text-align: center; color: #1e3a8a;">
                ماستری گشتی یێ شواغران (المعلمون الشاغرون فقط) - ${curDayName}
            </h4>
            <table class="table table-bordered text-center align-middle" style="width: 100%; border: 2px solid #334155; font-size: 8.5pt; table-layout: fixed;">
                <thead>
                    <tr>${masterPeriodHeaders}</tr>
                </thead>
                <tbody>
                    ${masterTeacherRows}
                </tbody>
            </table>
        </div>
    `;
    // -------------------------------------------------------------
    // 3. SECTION: Table View with Candidate Suggestions (سجل البدلاء والشواغر)
    // -------------------------------------------------------------
    let candidateTableRowsHtml = '';
    let cIndex = 1;

    daysToProcess.forEach(d => {
        const dayName = days[d];
        for (let p = 1; p <= periodsCount; p++) {
            for (const cName of (schedule.columns || [])) {
                const slotItem = schedule.timetables?.[cName]?.[d]?.[p];
                if (slotItem && (slotItem.teacher === absentTeacherName || !absentTeacherName)) {
                    const assignKey = `${slotItem.teacher}__${d}__${p}__${cName}`;
                    const assignedSub = schedule.substitutions?.[assignKey] || '';
                    const candidates = getSubstituteCandidates(schedule, absentTeacherName, d, p, slotItem.subject, days, periodsCount);

                    const candBadgesHtml = candidates.length > 0
                        ? candidates.map(c => `<span style="display:inline-block; margin:2px; padding:2px 6px; border-radius:4px; font-size:8pt; ${c.isSameSpec ? 'background-color:#dcfce7; color:#166534; border:1px solid #86efac; font-weight:bold;' : 'background-color:#f1f5f9; color:#334155; border:1px solid #cbd5e1;'}">${c.isSameSpec ? '⭐ ' : ''}${c.name} (${c.dailyLoad} حصص)</span>`).join('')
                        : `<span style="color:#dc2626; font-size:8pt;">لا يوجد أي معلم شاغر</span>`;

                    candidateTableRowsHtml += `
                        <tr>
                            <td style="font-weight: bold; padding: 6px; width: 35px;">${cIndex++}</td>
                            <td style="font-weight: bold; padding: 6px; width: 90px; background-color: #f8fafc;">${dayName}</td>
                            <td style="font-weight: bold; padding: 6px; width: 60px;">${p}</td>
                            <td style="font-weight: bold; padding: 6px; width: 75px; color: #dc2626;">${cName}</td>
                            <td style="font-weight: bold; padding: 6px; width: 110px; color: #1e40af;">${translateSubjectName(slotItem.subject)}</td>
                            <td style="padding: 6px; text-align: right; line-height: 1.6;">
                                ${candBadgesHtml}
                            </td>
                            <td style="font-weight: bold; padding: 6px; width: 160px;">
                                ${assignedSub ? `<span style="background-color:#15803d; color:#ffffff !important; padding:3px 8px; border-radius:6px; font-weight:bold; display:inline-block;">${assignedSub}</span>` : `<span style="color:#94a3b8; font-size:8.5pt;">چاوەڕوانە (قيد الانتظار)</span>`}
                            </td>
                        </tr>
                    `;
                }
            }
        }
    });

    const tableSection = `
        <div style="margin-bottom: 25px;">
            <h4 style="margin-bottom: 10px; font-weight: bold; text-align: center; color: #1e3a8a;">
                تۆمارا رۆژانە یا پڕکرنا وانەیان (سجل تكليف المعلمين البدلاء والشواغر)
            </h4>
            <table class="table table-bordered text-center align-middle" style="width: 100%; border: 2px solid #334155; font-size: 8.5pt;">
                <thead style="background-color: #1e293b; color: #fff;">
                    <tr>
                        <th style="padding: 6px;">#</th>
                        <th style="padding: 6px;">${t('val_day_lbl') || 'ڕۆژ'}</th>
                        <th style="padding: 6px;">${t('day_period') || 'وانە'}</th>
                        <th style="padding: 6px;">${t('class_label')}</th>
                        <th style="padding: 6px;">${t('subject_label')}</th>
                        <th style="padding: 6px;">مامۆستایێن بەتاڵ (المتاحون للبديل)</th>
                        <th style="padding: 6px;">${t('substitute_teacher_col')}</th>
                    </tr>
                </thead>
                <tbody>
                    ${candidateTableRowsHtml || '<tr><td colspan="7" class="text-muted p-3">هیچ تۆمارەک بەردەست نینە</td></tr>'}
                </tbody>
            </table>
        </div>
    `;

    // -------------------------------------------------------------
    // 4. SECTION: Official Slip (فۆڕما فەرمی یا واژووکرنێ)
    // -------------------------------------------------------------
    let slipRowsHtml = '';
    let counter = 1;

    daysToProcess.forEach(d => {
        const dayName = days[d];
        for (let p = 1; p <= periodsCount; p++) {
            for (const cName of (schedule.columns || [])) {
                const item = schedule.timetables?.[cName]?.[d]?.[p];
                if (item && (item.teacher === absentTeacherName || !absentTeacherName)) {
                    const tOwner = item.teacher;
                    const assignKey = `${tOwner}__${d}__${p}__${cName}`;
                    const assignedSub = schedule.substitutions?.[assignKey] || '';

                    slipRowsHtml += `
                        <tr>
                            <td style="font-weight: bold; width: 35px; padding: 6px;">${counter++}</td>
                            <td style="font-weight: bold; width: 90px; padding: 6px;">${dayName}</td>
                            <td style="font-weight: bold; width: 65px; padding: 6px;">${p}</td>
                            <td style="font-weight: bold; width: 85px; padding: 6px;">${cName}</td>
                            <td style="font-weight: bold; width: 120px; padding: 6px;">${translateSubjectName(item.subject)}</td>
                            <td style="font-weight: bold; font-size: 1.05em; color: #166534; width: 170px; padding: 6px;">${assignedSub ? assignedSub : '....................................'}</td>
                            <td style="width: 110px; padding: 6px;">...................</td>
                            <td style="padding: 6px;"></td>
                        </tr>
                    `;
                }
            }
        }
    });

    const slipSection = `
        <div>
            <h4 style="margin-bottom: 8px; font-weight: bold; text-align: center; color: #1e3a8a;">
                سجلا فەرمی یا دابەشکرنا جهگران (استمارة حصص الانتظار والتكليف)
            </h4>
            <table class="table table-bordered text-center align-middle" style="width: 100%; border: 2px solid #000; font-size: 9.5pt;">
                <thead style="background-color: #1f2937; color: #fff;">
                    <tr>
                        <th style="padding: 6px;">#</th>
                        <th style="padding: 6px;">${t('val_day_lbl') || 'ڕۆژ'}</th>
                        <th style="padding: 6px;">${t('day_period') || 'وانە'}</th>
                        <th style="padding: 6px;">${t('class_label')}</th>
                        <th style="padding: 6px;">${t('subject_label')}</th>
                        <th style="padding: 6px;">${t('substitute_teacher_col')}</th>
                        <th style="padding: 6px;">${t('substitute_signature_col')}</th>
                        <th style="padding: 6px;">${t('substitute_notes_col')}</th>
                    </tr>
                </thead>
                <tbody>
                    ${slipRowsHtml || '<tr><td colspan="8" class="text-muted p-3">هیچ وانەیەک نینە</td></tr>'}
                </tbody>
            </table>
        </div>
    `;

    // Determine final content to output
    if (activeFormat === 'weekly_master') {
        return weeklyMasterSection;
    }

    let bodyContent = '';
    if (activeFormat === 'grid') {
        bodyContent = gridSection;
    } else if (activeFormat === 'master_teachers') {
        bodyContent = masterTeachersSection;
    } else if (activeFormat === 'table') {
        bodyContent = tableSection;
    } else if (activeFormat === 'slip') {
        bodyContent = slipSection;
    } else if (activeFormat === 'all') {
        bodyContent = gridSection + slipSection;
    } else {
        bodyContent = gridSection;
    }

    const reportMainTitle = 'خشتەیێ دابەشکرنا جهگران (جدول حصص الانتظار والبدلاء)';
    const absentTeacherObj = allTeachers.find(t => t.name === absentTeacherName);
    const absentSpec = absentTeacherObj?.specialization || '';

    return `
        <div style="direction: rtl; font-family: 'Noto Kufi Arabic', Tahoma, sans-serif; padding: 15px; color: #000;">
            <!-- Official Header -->
            <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #000; padding-bottom: 10px; margin-bottom: 15px;">
                <div style="font-weight: bold; font-size: 10.5pt; line-height: 1.6;">
                    <div>حکومەتی هەرێمی کوردستان</div>
                    <div>وەزارەتی پەروەردە</div>
                    <div>${schoolName ? schoolName : 'قوتابخانە'}</div>
                </div>
                <div style="text-align: center;">
                    <h3 style="margin: 0; font-size: 14pt; font-weight: bold; text-decoration: underline; color: #1e3a8a;">
                        ${reportMainTitle}
                    </h3>
                    ${absentTeacherName ? `
                        <div style="font-size: 10.5pt; margin-top: 5px; font-weight: bold;">
                            ${t('absent_teacher_col')}: <span style="color: #b91c1c; font-size: 1.1em;">${absentTeacherName}</span> 
                            ${absentSpec ? `<span style="color: #4b5563;">(${translateSubjectName(absentSpec)})</span>` : ''}
                        </div>
                    ` : `
                        <div style="font-size: 10pt; margin-top: 5px; font-weight: bold; color: #475569;">
                            خشتێ گشتی بۆ تەواوی مامۆستایان (${allTeachers.length} مامۆستا)
                        </div>
                    `}
                </div>
                <div style="font-size: 9.5pt; font-weight: bold; text-align: left; line-height: 1.6;">
                    <div>بەروار (التاريخ): .... / .... / 202...</div>
                    <div>ڕۆژ (اليوم): ${selectedDayVal === 'all' ? (t('all_days_option') || 'هەمی ڕۆژێن حەفتیێ') : days[parseInt(selectedDayVal, 10)]}</div>
                    ${totalSlots > 0 ? `<div>کۆی وانەکان: ${totalSlots} وانە</div>` : ''}
                </div>
            </div>

            <!-- Content -->
            ${bodyContent}

            <!-- Official Signatures -->
            <div style="margin-top: 35px; display: flex; justify-content: space-between; align-items: flex-end; padding: 0 40px; font-weight: bold; font-size: 11pt; page-break-inside: avoid;">
                <div style="text-align: center;">
                    <div>دەستەی کارگێڕی / یاریدەدەر</div>
                    <div style="margin-top: 35px;">.........................................</div>
                </div>
                <div style="text-align: center;">
                    <div>${t('signature_principal') || 'رێڤەبەر'}: ${principalName || '................................'}</div>
                    <div style="margin-top: 35px;">مۆر و واژوو (الختم والتوقيع)</div>
                </div>
            </div>
        </div>
    `;
}

function buildSubstituteWebUiHtml(schedule, absentTeacherName, selectedDayVal, resolvedFormat) {
    if (!schedule) return '';
    const defaultDaysKurdish = ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
    const savedDays = schedule.settings?.workDays || defaultDaysKurdish;
    const localizedWorkDays = typeof t === 'function' ? t('work_days') : defaultDaysKurdish;
    const days = savedDays.map((dStr) => {
        const indexInKurdish = typeof ALL_DAYS_KURDISH !== 'undefined' ? ALL_DAYS_KURDISH.indexOf(dStr) : -1;
        if (indexInKurdish !== -1 && Array.isArray(localizedWorkDays) && localizedWorkDays[indexInKurdish]) {
            return localizedWorkDays[indexInKurdish];
        }
        return dStr;
    });
    const periodsCount = schedule.settings?.periodsPerDay || schedule.periodsCount || 7;
    const schoolName = schedule.settings?.globalSchoolName || schedule.schoolName || schedule.milak?.schoolName || '';
    const principalName = schedule.settings?.principalName || schedule.principalName || '';
    const allTeachers = schedule.teachers || [];

    const daysToProcess = selectedDayVal === 'all'
        ? days.map((_, idx) => idx)
        : [parseInt(selectedDayVal, 10)].filter(idx => !isNaN(idx) && idx >= 0 && idx < days.length);

    if (resolvedFormat === 'weekly_master') {
        const totalCols = daysToProcess.length * periodsCount;
        const colGroupHtml = `<colgroup><col style="width: 200px; min-width: 200px; max-width: 200px;">` + Array(totalCols).fill('<col style="width: 58px; min-width: 58px; max-width: 58px;">').join('') + `</colgroup>`;

        let totalAssignedSubCount = 0;
        let totalLessonsCount = 0;
        let totalVacanciesCount = 0;

        // Calm, soothing pastel & executive color palette for days
        const calmDayGradients = [
            'linear-gradient(145deg, #334e68 0%, #1e293b 100%)', // Calm Slate-Navy
            'linear-gradient(145deg, #0284c7 0%, #0369a1 100%)', // Calm Ocean Blue
            'linear-gradient(145deg, #059669 0%, #047857 100%)', // Calm Sage Green
            'linear-gradient(145deg, #d97706 0%, #b45309 100%)', // Calm Warm Amber
            'linear-gradient(145deg, #7c3aed 0%, #6d28d9 100%)', // Calm Dusty Lavender
            'linear-gradient(145deg, #e11d48 0%, #be123c 100%)', // Calm Soft Rose
            'linear-gradient(145deg, #64748b 0%, #475569 100%)'  // Calm Muted Slate
        ];

        let headerRow1 = `<th rowspan="2" style="width: 200px; min-width: 200px; position: sticky; right: 0; top: 0; z-index: 35; background: linear-gradient(145deg, #1e293b, #0f172a); color: #ffffff; border: 1px solid #334155; font-size: 0.82rem; font-weight: 800; border-radius: 10px 0 0 0; box-shadow: -3px 3px 8px rgba(0,0,0,0.15);" class="align-middle text-center p-2">${typeof t === 'function' ? t('col_teacher') : 'مامۆستا'}</th>`;
        let headerRow2 = '';

        daysToProcess.forEach((d, dIdx) => {
            const dayName = days[d];
            const bgGrad = calmDayGradients[dIdx % calmDayGradients.length];
            headerRow1 += `<th colspan="${periodsCount}" class="text-white text-center py-1.5 px-1" style="background: ${bgGrad}; border-left: 1.5px solid #ffffff; border-right: 1.5px solid #ffffff; position: sticky; top: 0; z-index: 20; font-size: 0.8rem; font-weight: 800; border-radius: 8px 8px 0 0; box-shadow: inset 1px 1px 2px rgba(255,255,255,0.4); text-shadow: 0 1px 2px rgba(0,0,0,0.2); white-space: nowrap;">${dayName}</th>`;
            for (let p = 1; p <= periodsCount; p++) {
                headerRow2 += `<th class="text-white text-center py-0.5" style="width: 58px; min-width: 58px; font-size: 0.68rem; font-weight: 700; position: sticky; top: 34px; z-index: 18; background-color: #334155; border: 1px solid #475569; height: 24px; white-space: nowrap;">${p}</th>`;
            }
        });

        let masterRowsHtml = '';

        allTeachers.forEach((tItem, tIdx) => {
            const tName = tItem.name;
            const tSpec = translateSubjectName(tItem.specialization || '');
            const isSelectedAbsent = tName === absentTeacherName;

            let weeklyQuota = 0;
            if (tItem.classes) {
                Object.values(tItem.classes).forEach(cls => {
                    if (cls) Object.values(cls).forEach(v => weeklyQuota += (parseInt(v, 10) || 0));
                });
            }

            let rowCells = `
                <td class="align-middle text-start px-2.5 py-1.5" style="width: 200px; min-width: 200px; max-width: 200px; position: sticky; right: 0; z-index: 10; border: 1px solid #cbd5e1; background-color: ${isSelectedAbsent ? '#fff1f2' : (tIdx % 2 === 0 ? '#ffffff' : '#f8fafc')}; color: ${isSelectedAbsent ? '#be123c' : '#1e293b'}; box-shadow: -3px 0 6px rgba(0,0,0,0.04);">
                    <div class="d-flex justify-content-between align-items-center mb-1 gap-1">
                        <div class="fw-bold text-truncate" style="font-size: 0.74rem; color: ${isSelectedAbsent ? '#be123c' : '#0f172a'}; line-height: 1.2; white-space: nowrap;" title="${tName}">
                            ${isSelectedAbsent ? '<i class="fas fa-user-times text-danger me-1" style="font-size: 0.65rem;"></i>' : '<i class="fas fa-chalkboard-teacher text-secondary opacity-75 me-1" style="font-size: 0.65rem;"></i>'}${tName}
                        </div>
                        <span style="font-size: 0.58rem; font-weight: 700; padding: 2px 5px; background: #e2e8f0; color: #334155; border-radius: 8px; box-shadow: inset 1px 1px 1px rgba(0,0,0,0.06); white-space: nowrap;">${weeklyQuota}و</span>
                    </div>
                    <div class="d-flex align-items-center justify-content-between text-muted" style="font-size: 0.62rem; white-space: nowrap;">
                        <span class="text-truncate" style="color: #0284c7; font-weight: 600;" title="${tSpec}">
                            <i class="fas fa-graduation-cap me-1 text-primary opacity-75" style="font-size: 0.58rem;"></i>${tSpec || (typeof t === 'function' ? t('col_teacher') : 'مامۆستا')}
                        </span>
                        ${isSelectedAbsent ? '<span class="badge bg-danger-subtle text-danger border border-danger-subtle px-1.5 py-0.5" style="font-size: 0.52rem; font-weight: 700;">مۆڵەت</span>' : ''}
                    </div>
                </td>
            `;

            daysToProcess.forEach(d => {
                const dayName = days[d];
                const rawDayName = (typeof ALL_DAYS_KURDISH !== 'undefined' && ALL_DAYS_KURDISH[d]) ? ALL_DAYS_KURDISH[d] : dayName;
                const offDays = tItem.offDays || [];
                const isOffDay = offDays.includes(dayName) || offDays.includes(rawDayName);
                const blocked = tItem.blockedPeriods || {};
                const blockedPeriods = blocked[dayName] || blocked[rawDayName] || [];

                for (let p = 1; p <= periodsCount; p++) {
                    const isBlocked = Array.isArray(blockedPeriods) && blockedPeriods.includes(p);

                    let foundClass = '', foundSubject = '';
                    for (const c of (schedule.columns || [])) {
                        const item = schedule.timetables?.[c]?.[d]?.[p];
                        if (item && item.teacher === tName) {
                            foundClass = c;
                            foundSubject = item.subject;
                            break;
                        }
                    }

                    if (foundClass) {
                        totalLessonsCount++;
                        const assignKey = `${tName}__${d}__${p}__${foundClass}`;
                        const assignedSub = schedule.substitutions?.[assignKey] || '';

                        if (assignedSub) {
                            totalAssignedSubCount++;
                            const subDisplayName = (getSmartTeacherDisplayName(assignedSub, schedule.teachers) || assignedSub).trim().split(/\s+/)[0];
                            rowCells += `
                                <td class="p-0.5 align-middle text-center" style="height: 46px; width: 58px; min-width: 58px; border: 1px solid #86efac; background-color: #f0fdf4;">
                                    <div class="p-0.5 d-flex flex-column justify-content-center align-items-center h-100" style="background: linear-gradient(145deg, #10b981, #059669); color: #ffffff !important; border-radius: 6px; box-shadow: 2px 2px 5px rgba(5, 150, 105, 0.25), inset 1px 1px 1px rgba(255,255,255,0.5); border: 1px solid rgba(255,255,255,0.3);">
                                        <div class="fw-bold text-truncate mb-0.5" style="font-size: 0.65rem; color: #ffffff !important; line-height: 1.1; max-width: 52px; white-space: nowrap;" title="مامۆستایێ جهگر: ${assignedSub}">
                                            ${subDisplayName}
                                        </div>
                                        <div class="text-truncate" style="font-size: 0.56rem; color: #f0fdf4 !important; line-height: 1.1; white-space: nowrap;">
                                            <span style="background: rgba(0,0,0,0.32); color: #ffffff !important; padding: 1px 5px; border-radius: 3px; font-weight: 800; white-space: nowrap;">${foundClass}</span>
                                        </div>
                                    </div>
                                </td>
                            `;
                        } else {
                            const teacherFirstName = (getSmartTeacherDisplayName(tName, schedule.teachers) || tName).trim().split(/\s+/)[0];
                            rowCells += `
                                <td class="p-0.5 align-middle text-center" style="height: 46px; width: 58px; min-width: 58px; border: 1px solid #e2e8f0; background-color: #ffffff;">
                                    <div class="d-flex flex-column align-items-center justify-content-center h-100 p-0.5" style="background: linear-gradient(145deg, #ffffff, #f8fafc); border: 1px solid #e2e8f0; border-radius: 6px; box-shadow: 1px 1px 3px rgba(166, 180, 200, 0.25), inset 1px 1px 1px #ffffff;">
                                        <span class="shadow-sm mb-0.5" style="font-size: 0.56rem; padding: 0 4px; background: linear-gradient(135deg, #3b82f6, #2563eb); color: #ffffff; border-radius: 4px; font-weight: 800; line-height: 1.2; white-space: nowrap;">${foundClass}</span>
                                        <div class="fw-bold text-truncate" style="font-size: 0.56rem; max-width: 52px; color: #1e293b; line-height: 1.1; white-space: nowrap;" title="${teacherFirstName}">
                                            ${teacherFirstName}
                                        </div>
                                    </div>
                                </td>
                            `;
                        }
                    } else if (isOffDay) {
                        rowCells += `
                            <td class="p-0.5 align-middle text-center" style="height: 46px; width: 58px; min-width: 58px; border: 1px solid #e2e8f0; background-color: #f8fafc;">
                                <span style="font-size: 0.58rem; font-weight: 600; color: #64748b; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 6px; padding: 2px 6px; box-shadow: 1px 1px 2px #e2e8f0; white-space: nowrap; display: inline-block;">عطلة</span>
                            </td>
                        `;
                    } else if (isBlocked) {
                        rowCells += `
                            <td class="p-0.5 align-middle text-center" style="height: 46px; width: 58px; min-width: 58px; border: 1px solid #e2e8f0; background-color: #fff1f2;">
                                <span style="font-size: 0.58rem; color: #e11d48; background: #ffffff; border: 1px solid #fecdd3; border-radius: 6px; padding: 2px 5px; display: inline-block; white-space: nowrap;">🔒</span>
                            </td>
                        `;
                    } else {
                        totalVacanciesCount++;
                        rowCells += `
                            <td class="p-0.5 align-middle text-center" style="height: 46px; width: 58px; min-width: 58px; border: 1px solid #e2e8f0; background-color: #ffffff;">
                                <span style="font-size: 0.58rem; font-weight: 700; color: #059669; background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 6px; padding: 2px 6px; box-shadow: 1px 1px 2px rgba(0,0,0,0.02); white-space: nowrap; display: inline-block;">شاغر</span>
                            </td>
                        `;
                    }
                }
            });

            masterRowsHtml += `<tr>${rowCells}</tr>`;
        });

        return `
            <div class="container-fluid py-2 px-1 px-md-3" style="direction: rtl; font-family: 'Noto Kufi Arabic', Tahoma, sans-serif; background-color: #eef2f7;">
                <!-- Header Banner (Claymorphism Card) -->
                <div class="card border-0 rounded-4 mb-3 p-2.5 p-md-3 clay-card" style="background: linear-gradient(145deg, #ffffff, #f8fafc); border-right: 5px solid #10b981 !important;">
                    <div class="d-flex justify-content-between align-items-center flex-wrap gap-2">
                        <div class="d-flex align-items-center gap-2.5">
                            <div class="d-inline-flex align-items-center justify-content-center text-white" style="width: 44px; height: 44px; min-width: 44px; background: linear-gradient(135deg, #334e68, #1e293b); border-radius: 14px; box-shadow: 3px 3px 10px rgba(30, 41, 59, 0.3), inset 1px 1px 2px rgba(255,255,255,0.4);">
                                <i class="fas fa-calendar-alt fs-5"></i>
                            </div>
                            <div>
                                <div class="text-muted fw-bold" style="font-size: 0.68rem; letter-spacing: 0.2px;">حکومەتی هەرێمی کوردستان • وەزارەتی پەروەردە</div>
                                <h5 class="fw-bold mb-0" style="color: #1e293b; font-size: 1rem;">${typeof t === 'function' ? t('sub_leave_teacher_schedule_title', 'جدول بدل معلم مجاز') : 'جدول بدل معلم مجاز'}${schoolName ? ' - ' + schoolName : ''}</h5>
                                <div class="text-muted" style="font-size: 0.65rem;">خشتەی گشتی هەفتانە بۆ سەرجەم مامۆستایان و دابەشکرنا جهگران (جدول الحصص والبدلاء)</div>
                            </div>
                        </div>
                        <div class="d-flex align-items-center gap-2 flex-wrap">
                            <div class="d-flex align-items-center gap-1 bg-white px-2 py-1 rounded-pill clay-pill border" title="قەبارە / حجم العرض">
                                <span class="text-muted small fw-bold me-1" style="font-size: 0.65rem;"><i class="fas fa-search-plus text-primary"></i></span>
                                <button type="button" class="btn btn-sm btn-light rounded-pill px-1.5 py-0 fw-bold border zoom-btn" onclick="changeMasterZoom(0.75, this)" style="font-size: 0.65rem;">75%</button>
                                <button type="button" class="btn btn-sm btn-light rounded-pill px-1.5 py-0 fw-bold border zoom-btn" onclick="changeMasterZoom(0.88, this)" style="font-size: 0.65rem;">88%</button>
                                <button type="button" class="btn btn-sm btn-primary rounded-pill px-2 py-0 fw-bold zoom-btn active" onclick="changeMasterZoom(1, this)" style="font-size: 0.65rem;">100%</button>
                                <button type="button" class="btn btn-sm btn-light rounded-pill px-1.5 py-0 fw-bold border zoom-btn" onclick="changeMasterZoom(1.15, this)" style="font-size: 0.65rem;">115%</button>
                            </div>
                            <span class="clay-pill px-2.5 py-1 fw-bold" style="font-size: 0.7rem; background: linear-gradient(135deg, #334e68, #1e293b); color: #ffffff;">
                                <i class="fas fa-users me-1"></i>${allTeachers.length} مامۆستا
                            </span>
                            <span class="clay-pill px-2.5 py-1 fw-bold" style="font-size: 0.7rem; background: linear-gradient(135deg, #10b981, #059669); color: #ffffff;">
                                <i class="fas fa-user-check me-1"></i>${totalAssignedSubCount} جهگر
                            </span>
                            <span class="clay-pill px-2.5 py-1 fw-bold" style="font-size: 0.7rem; background: #ffffff; color: #475569; border: 1px solid #e2e8f0;">
                                <i class="far fa-calendar-alt me-1 text-primary"></i>${new Date().toLocaleDateString('ar-IQ')}
                            </span>
                        </div>
                    </div>
                </div>

                <!-- Full Table Display (Compact Claymorphism Card) -->
                <div class="card border-0 rounded-4 mb-3 clay-card p-1.5 p-md-2" style="overflow: visible;">
                    <div class="table-responsive" id="masterTableContainer" style="overflow-x: auto; overflow-y: visible; width: 100%; -webkit-overflow-scrolling: touch; border-radius: 12px;">
                        <table id="masterTimetableTable" class="table table-bordered text-center align-middle mb-0" style="table-layout: fixed; min-width: ${daysToProcess.length * periodsCount * 58 + 200}px; width: 100%; border-collapse: separate !important; border-spacing: 0 !important; transition: transform 0.2s ease; transform-origin: top right;">
                            ${colGroupHtml}
                            <thead>
                                <tr>${headerRow1}</tr>
                                <tr>${headerRow2}</tr>
                            </thead>
                            <tbody>
                                ${masterRowsHtml}
                            </tbody>
                        </table>
                    </div>
                </div>

                <!-- Footer / Signatures (Compact Claymorphism Card) -->
                <div class="card border-0 rounded-4 clay-card p-3">
                    <div class="d-flex justify-content-between align-items-center flex-wrap gap-3">
                        <div class="text-center" style="min-width: 180px;">
                            <div class="text-muted small fw-bold mb-1" style="font-size: 0.7rem;">دەستەی کارگێڕی / یاریدەدەر</div>
                            <div class="fw-bold mt-3" style="color: #94a3b8; letter-spacing: 2px; font-size: 0.75rem;">................................................</div>
                        </div>
                        <div class="text-center text-muted" style="font-size: 0.65rem;">
                            <i class="fas fa-info-circle me-1 text-primary"></i>ئەم خشتەیە بە شێوەیەکی ئۆتۆماتیکی لە سیستەمی پێشکەوتووی خشتەی قوتابخانە دروستکراوە
                        </div>
                        <div class="text-center" style="min-width: 180px;">
                            <div class="text-muted small fw-bold mb-0.5" style="font-size: 0.7rem;">${typeof t === 'function' ? t('signature_principal') : 'بەڕێوەبەر'}</div>
                            <div class="fw-bold text-dark" style="font-size: 0.75rem;">${principalName || '................................'}</div>
                            <div class="text-muted" style="font-size: 0.62rem;">مۆر و واژوو (الختم والتوقيع)</div>
                        </div>
                    </div>
                </div>
            </div>
            <script>
                function changeMasterZoom(scale, btn) {
                    var tbl = document.getElementById('masterTimetableTable');
                    if (tbl) {
                        tbl.style.zoom = scale;
                    }
                    if (btn) {
                        document.querySelectorAll('.zoom-btn').forEach(function(b) {
                            b.classList.remove('btn-primary', 'active');
                            b.classList.add('btn-light');
                        });
                        btn.classList.remove('btn-light');
                        btn.classList.add('btn-primary', 'active');
                    }
                }
            </script>
        `;
    }

    const standardContent = buildSubstitutePrintableHtml(schedule, absentTeacherName, selectedDayVal, resolvedFormat);
    return `
        <div class="container-fluid py-3 px-2 px-md-4" style="direction: rtl; font-family: 'Noto Kufi Arabic', Tahoma, sans-serif; background-color: #eef2f7;">
            <div class="card border-0 rounded-4 clay-card p-3 p-md-4 mb-4" style="overflow: visible;">
                ${standardContent}
            </div>
        </div>
    `;
}

function downloadSubstituteHTML(format = 'current') {
    const schedule = allSchedules[activeScheduleName] || (typeof allSchedules === 'object' && Object.values(allSchedules)[0]);
    if (!schedule) {
        Swal.fire({ icon: 'warning', title: (typeof t === 'function' && t('toast_no_schedule_loaded')) || 'No schedule loaded' });
        return;
    }

    const subTeacherSelect = document.getElementById('substituteTeacherSelect');
    const subDaySelect = document.getElementById('substituteDaySelect');
    let absentTeacherName = subTeacherSelect ? subTeacherSelect.value : '';
    const selectedDayVal = subDaySelect ? subDaySelect.value : 'all';

    const resolvedFormat = format === 'current' ? (typeof substituteSubViewMode !== 'undefined' ? substituteSubViewMode : 'weekly_master') : format;

    if (!absentTeacherName && !['weekly_master', 'weekly_master_classes', 'vacancies_master', 'grid'].includes(resolvedFormat)) {
        const teachers = schedule.teachers || [];
        if (teachers.length === 0) {
            Swal.fire({ icon: 'warning', title: typeof t === 'function' ? t('toast_no_teachers_to_print') : 'No teachers' });
            return;
        }
        const teacherOpts = {};
        teachers.forEach(tItem => {
            teacherOpts[tItem.name] = `${tItem.name} (${translateSubjectName(tItem.specialization || '')})`;
        });
        Swal.fire({
            title: (typeof t === 'function' && t('select_absent_teacher')) || 'دیاریکردنا مامۆستایێ مۆڵەتپێدای',
            text: (typeof t === 'function' && t('select_teacher_first_prompt')) || 'تکایە سەرەتا مامۆستایێ مۆڵەتپێدای هەڵبژێرە',
            input: 'select',
            inputOptions: teacherOpts,
            inputPlaceholder: `-- ${(typeof t === 'function' && t('select_absent_teacher')) || 'دیاریکردن'} --`,
            showCancelButton: true,
            confirmButtonText: typeof t === 'function' ? t('confirm', 'دیاریکردن') : 'دیاریکردن',
            cancelButtonText: typeof t === 'function' ? t('cancel', 'هەڵوەشاندن') : 'هەڵوەشاندن'
        }).then(res => {
            if (res.isConfirmed && res.value) {
                selectAbsentTeacherQuick(res.value);
                downloadSubstituteHTML(format);
            }
        });
        return;
    }

    const contentHtml = buildSubstituteWebUiHtml(schedule, absentTeacherName, selectedDayVal, resolvedFormat);
    if (!contentHtml) {
        Swal.fire({
            icon: 'info',
            title: (typeof t === 'function' && t('no_lessons_for_absent')) || 'هیچ داتایەک نینە',
            text: (typeof t === 'function' && t('no_lessons_for_absent')) || 'هیچ وانەیەک نینە بۆ نیشاندان'
        });
        return;
    }

    const formatSuffix = resolvedFormat === 'weekly_master' ? 'ماستری_گشتی_ماموستایان' : (resolvedFormat === 'weekly_master_classes' ? 'ماستری_گشتی_پۆلان' : (resolvedFormat === 'vacancies_master' ? 'ماستر_شواغر_وبدلاء' : (resolvedFormat === 'master_teachers' ? 'ماستر_شواغر' : (resolvedFormat === 'table' ? 'سجل_تۆمار' : (resolvedFormat === 'grid' ? 'خشتێ_گشتی' : (resolvedFormat === 'slip' ? 'استمارة' : 'شامل'))))));
    const title = ['weekly_master', 'weekly_master_classes', 'vacancies_master', 'grid'].includes(resolvedFormat)
        ? `ماستری_گشتی_${formatSuffix}_${selectedDayVal}`
        : `خشتێ_جهگران_${sanitizeDownloadFileName(absentTeacherName || 'general')}_${formatSuffix}_${selectedDayVal}`;
    const filename = ['weekly_master', 'weekly_master_classes', 'vacancies_master', 'grid'].includes(resolvedFormat)
        ? `${resolvedFormat}_substitutes_${selectedDayVal}.html`
        : `substitute_${sanitizeDownloadFileName(absentTeacherName || 'general')}_${formatSuffix}_${selectedDayVal}.html`;

    downloadHTMLFile(title, contentHtml, { filename, isWebExport: true });
    if (typeof showToast === 'function') {
        showToast('فایلی HTML ب سەرکەفتیانە هاتە هەڵگرتن (تم حفظ ملف HTML بنجاح)', 'success');
    }
}

function printDailySubstitutionReport(format = 'current') {
    const schedule = allSchedules[activeScheduleName] || (typeof allSchedules === 'object' && Object.values(allSchedules)[0]);
    if (!schedule) {
        Swal.fire({ icon: 'warning', title: (typeof t === 'function' && t('toast_no_schedule_loaded')) || 'No schedule loaded' });
        return;
    }

    const subTeacherSelect = document.getElementById('substituteTeacherSelect');
    const subDaySelect = document.getElementById('substituteDaySelect');
    let absentTeacherName = subTeacherSelect ? subTeacherSelect.value : '';
    const selectedDayVal = subDaySelect ? subDaySelect.value : 'all';

    const resolvedFormat = format === 'current' ? (typeof substituteSubViewMode !== 'undefined' ? substituteSubViewMode : 'weekly_master') : format;

    if (!absentTeacherName && !['weekly_master', 'weekly_master_classes', 'vacancies_master', 'grid'].includes(resolvedFormat)) {
        const teachers = schedule.teachers || [];
        if (teachers.length === 0) {
            Swal.fire({ icon: 'warning', title: typeof t === 'function' ? t('toast_no_teachers_to_print') : 'No teachers' });
            return;
        }
        const teacherOpts = {};
        teachers.forEach(tItem => {
            teacherOpts[tItem.name] = `${tItem.name} (${translateSubjectName(tItem.specialization || '')})`;
        });
        Swal.fire({
            title: (typeof t === 'function' && t('select_absent_teacher')) || 'دیاریکردنا مامۆستایێ مۆڵەتپێدای',
            text: (typeof t === 'function' && t('select_teacher_first_prompt')) || 'تکایە سەرەتا مامۆستایێ مۆڵەتپێدای هەڵبژێرە',
            input: 'select',
            inputOptions: teacherOpts,
            inputPlaceholder: `-- ${(typeof t === 'function' && t('select_absent_teacher')) || 'دیاریکردن'} --`,
            showCancelButton: true,
            confirmButtonText: typeof t === 'function' ? t('btn_print', 'چاپکرن') : 'چاپکرن',
            cancelButtonText: typeof t === 'function' ? t('cancel', 'هەڵوەشاندن') : 'هەڵوەشاندن'
        }).then(res => {
            if (res.isConfirmed && res.value) {
                selectAbsentTeacherQuick(res.value);
                printDailySubstitutionReport(format);
            }
        });
        return;
    }

    const contentHtml = buildSubstitutePrintableHtml(schedule, absentTeacherName, selectedDayVal, resolvedFormat);
    if (!contentHtml) {
        Swal.fire({
            icon: 'info',
            title: (typeof t === 'function' && t('no_lessons_for_absent')) || 'هیچ داتایەک نینە',
            text: (typeof t === 'function' && t('no_lessons_for_absent')) || 'هیچ وانەیەک نینە بۆ نیشاندان'
        });
        return;
    }

    const formatSuffix = resolvedFormat === 'weekly_master' ? 'ماستری گشتی یێ مامۆستایان' : (resolvedFormat === 'weekly_master_classes' ? 'ماستری گشتی یێ پۆلان' : (resolvedFormat === 'vacancies_master' ? 'ماسترێ شواغران' : (resolvedFormat === 'master_teachers' ? 'ماسترێ شواغران' : (resolvedFormat === 'table' ? 'تۆمارا جهگران' : (resolvedFormat === 'grid' ? 'خشتێ گشتی' : (resolvedFormat === 'slip' ? 'فۆڕما واژووکرنێ' : 'راپۆرتا گشتی'))))));
    const title = ['weekly_master', 'weekly_master_classes', 'vacancies_master'].includes(resolvedFormat)
        ? `${formatSuffix} ل گەل بەدیلان`
        : `خشتەیێ جهگران (${formatSuffix}) - ${absentTeacherName || 'گشتی'}`;
    const pageOrientation = ['weekly_master', 'weekly_master_classes', 'vacancies_master', 'grid', 'master_teachers'].includes(resolvedFormat) ? 'landscape' : 'portrait';
    printWithContent(title, contentHtml, { orientation: pageOrientation });
}

function renderTimetableGrid() {
    const activeTab = document.querySelector('#mainTabs .nav-link.active');
    if (activeTab && activeTab.id === 'substitute-tab') {
        if (typeof renderSubstituteTab === 'function') {
            renderSubstituteTab();
            return;
        }
    }
    const checkedRadio = document.querySelector('input[name="ttViewMode"]:checked');
    const mode = checkedRadio ? checkedRadio.value : 'class';
    const schedule = allSchedules[activeScheduleName];
    const container = document.getElementById('timetableGridContainer');

    const defaultDaysKurdish = ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
    const savedDays = schedule.settings.workDays || defaultDaysKurdish;
    const localizedWorkDays = typeof t === 'function' ? t('work_days') : defaultDaysKurdish;
    const days = savedDays.map((dStr) => {
        const indexInKurdish = ALL_DAYS_KURDISH.indexOf(dStr);
        if (indexInKurdish !== -1 && Array.isArray(localizedWorkDays) && localizedWorkDays[indexInKurdish]) {
            return localizedWorkDays[indexInKurdish];
        }
        return dStr;
    });

    const periodsCount = schedule.settings.periodsPerDay || 7;

    sortables.forEach(s => s.destroy()); sortables = [];

    if (mode === 'substitute') {
        renderSubstituteFinder(schedule, container, days, periodsCount);
        return;
    }

    if (mode === 'class') {
        const className = document.getElementById('timetableClassSelect').value;
        if (!className) return;
        if (className === "all_classes") {
            document.getElementById('unassignedCol').classList.remove('d-none');
            document.getElementById('gridCol').className = 'col-md-9';

            let periodHeaders = `<th style="width: 12%;">${t('day_period')}</th>`;
            for (let p = 1; p <= periodsCount; p++) periodHeaders += '<th style="width: ' + (88 / periodsCount) + '%;">' + p + '</th>';

            let finalHTML = `<div class="d-flex justify-content-center align-items-center mb-4 px-3"><h3 class="text-primary mb-0">${t('master_class_title')}</h3>` +
                '</div><div>';

            schedule.columns.forEach((cName, colIndex) => {
                if (colIndex % 2 === 0) {
                    const breakClass = colIndex > 0 ? 'page-break' : '';
                    finalHTML += `<div class="${breakClass}">`;
                }

                let h = `<div class="mb-4"><h5 class="text-center mt-4 mb-2 text-secondary fw-bold">${t('class_label')} ${cName}</h5>` +
                    '<table class="table table-bordered text-center align-middle" style="page-break-inside: avoid;">' +
                    '<thead class="table-secondary"><tr>' + periodHeaders + '</tr></thead><tbody>';
                for (let d = 0; d < days.length; d++) {
                    h += '<tr><td class="fw-bold bg-light align-middle">' + days[d] + '</td>';
                    for (let p = 1; p <= periodsCount; p++) {
                        h += '<td class="timetable-cell bg-white" data-day="' + d + '" data-period="' + p + '" data-class="' + cName + '" style="height: 60px; min-width: 60px;">';
                        const item = schedule.timetables?.[cName]?.[d]?.[p];
                        if (item) {
                            const isLocked = !!item.locked;
                            const lockBadge = isLocked ? `<span class="locked-slot-badge" onclick="event.stopPropagation(); toggleSlotLock('${cName}', ${d}, ${p})" title="${t('unlock_slot')}"><i class="fas fa-lock"></i></span>` : '';
                            h += `<div class="timetable-item mb-0 bg-white border ${isLocked ? 'border-warning is-locked' : 'border-secondary'} rounded shadow-sm text-center position-relative" style="cursor: grab;" data-subject="${item.subject}" data-teacher="${item.teacher}" data-id="${item.id}" data-class="${cName}" data-locked="${isLocked ? '1' : '0'}" onclick="handleTimetableCellClick('${cName}', ${d}, ${p})">
                                ${lockBadge}
                                <div class="fw-bold text-primary">${translateSubjectName(item.subject)}</div>
                                <div class="text-muted">${item.teacher || ''}</div>
                            </div>`;
                        } else {
                            h += `<div class="w-100 h-100 d-flex align-items-center justify-content-center text-muted opacity-25 cell-click-hint" style="min-height: 40px;" onclick="handleTimetableCellClick('${cName}', ${d}, ${p})" title="${t('select_unassigned_for_slot')}">
                                <i class="fas fa-plus-circle"></i>
                            </div>`;
                        }
                        h += '</td>';
                    }
                    h += '</tr>';
                }
                h += '</tbody></table></div>';
                finalHTML += h;

                if (colIndex % 2 === 1 || colIndex === schedule.columns.length - 1) {
                    finalHTML += '</div>';
                }
            });
            finalHTML += '</div>';
            container.innerHTML = finalHTML;
        } else {
            document.getElementById('unassignedCol').classList.remove('d-none');
            document.getElementById('gridCol').className = 'col-md-9';

            if (!schedule.timetables) schedule.timetables = {};
            if (!schedule.timetables[className]) schedule.timetables[className] = {};

            let periodHeaders = `<th style="width: 12%;">${t('day_period')}</th>`;
            for (let p = 1; p <= periodsCount; p++) periodHeaders += '<th style="width: ' + (88 / periodsCount) + '%;">' + p + '</th>';

            let h = `<h4 class="text-center mb-3 text-primary" id="timetableGridTitle">${t('tab_timetable')} - ${t('class_label')} ${className}</h4>` +
                '<table class="table table-bordered text-center align-middle" id="timetableGridTable">' +
                '<thead class="table-secondary"><tr>' + periodHeaders + '</tr></thead>' +
                '<tbody id="timetableGridBody">';
            for (let d = 0; d < days.length; d++) {
                h += '<tr><td class="fw-bold bg-light align-middle">' + days[d] + '</td>';
                for (let p = 1; p <= periodsCount; p++) {
                    h += '<td class="timetable-cell bg-white" data-day="' + d + '" data-period="' + p + '" data-class="' + className + '">';
                    const item = schedule.timetables[className]?.[d]?.[p];
                    if (item) {
                        const isLocked = !!item.locked;
                        const lockBadge = isLocked ? `<span class="locked-slot-badge" onclick="event.stopPropagation(); toggleSlotLock('${className}', ${d}, ${p})" title="${t('unlock_slot')}"><i class="fas fa-lock"></i></span>` : '';
                        h += `<div class="timetable-item mb-0 bg-white border ${isLocked ? 'border-warning is-locked' : 'border-secondary'} rounded shadow-sm text-center position-relative" style="cursor: grab;" data-subject="${item.subject}" data-teacher="${item.teacher}" data-id="${item.id}" data-class="${className}" data-locked="${isLocked ? '1' : '0'}" onclick="handleTimetableCellClick('${className}', ${d}, ${p})">
                            ${lockBadge}
                            <div class="fw-bold text-primary">${translateSubjectName(item.subject)}</div>
                            <div class="text-muted">${item.teacher || ''}</div>
                        </div>`;
                    } else {
                        h += `<div class="w-100 h-100 d-flex align-items-center justify-content-center text-muted opacity-25 cell-click-hint" style="min-height: 40px;" onclick="handleTimetableCellClick('${className}', ${d}, ${p})" title="${t('select_unassigned_for_slot')}">
                            <i class="fas fa-plus-circle"></i>
                        </div>`;
                    }
                    h += '</td>';
                }
                h += '</tr>';
            }
            h += '</tbody></table>';
            container.innerHTML = h;
        }

        const unassignedList = document.getElementById('unassignedSubjectsList');
        let unassignedHTML = '';
        let requiredItems = [];
        let classesToProcess = className === "all_classes" ? schedule.columns : [className];

        classesToProcess.forEach(cName => {
            schedule.teachers.forEach(teacher => {
                if (teacher.classes?.[cName]) {
                    Object.entries(teacher.classes[cName]).forEach(([subject, periods]) => {
                        for (let i = 0; i < periods; i++) { requiredItems.push({ id: 't_' + teacher.id + '_' + cName + '_' + subject + '_' + i, subject: subject, teacher: teacher.name, className: cName }); }
                    });
                }
            });
        });

        const assignedItems = [];
        classesToProcess.forEach(cName => {
            if (schedule.timetables?.[cName]) {
                Object.values(schedule.timetables[cName]).forEach(dayObj => { Object.values(dayObj).forEach(item => assignedItems.push({ ...item, className: cName })); });
            }
        });

        let remainingItems = [...requiredItems];
        assignedItems.forEach(assigned => {
            const index = remainingItems.findIndex(req => req.teacher === assigned.teacher && req.subject === assigned.subject && req.className === assigned.className);
            if (index !== -1) remainingItems.splice(index, 1);
        });

        if (remainingItems.length === 0) {
            unassignedHTML = `<div class="text-center text-success mt-5"><i class="fas fa-check-circle fa-3x mb-2"></i><h6>${t('all_lessons_assigned')}</h6></div>`;
        } else {
            remainingItems.forEach(item => {
                unassignedHTML += '<div class="timetable-item mb-2 bg-white border border-primary rounded shadow-sm" style="cursor: grab;" data-subject="' + item.subject + '" data-teacher="' + item.teacher + '" data-id="' + item.id + '" data-class="' + item.className + '"><div class="d-flex justify-content-between align-items-center"><span class="fw-bold text-primary">' + translateSubjectName(item.subject) + '</span><span class="badge bg-secondary">' + (item.teacher || '') + '</span></div><div class="text-muted small text-start">' + t('class_label') + ' ' + item.className + '</div></div>';
            });
        }
        unassignedList.innerHTML = unassignedHTML;
        initSortables();
    }
    else if (mode === 'teacher') {
        const teacherName = document.getElementById('timetableTeacherSelect').value;
        if (!teacherName) return;

        if (teacherName === "all_teachers") {
            let finalHTML = `<div class="d-flex justify-content-center align-items-center mb-4 px-3"><h3 class="text-primary mb-0">${t('master_teacher_title')}</h3>` +
                '</div><div>';
            let hasAny = false;
            let renderedCount = 0;

            const activeTeachers = schedule.teachers.filter(t =>
                schedule.columns.some(c => t.classes?.[c] && Object.values(t.classes[c]).some(v => v > 0))
            );

            activeTeachers.forEach((tItem, idx) => {
                hasAny = true;
                if (renderedCount % 2 === 0) {
                    const breakClass = renderedCount > 0 ? 'page-break' : '';
                    finalHTML += `<div class="${breakClass}">`;
                }

                let periodHeaders = `<th style="width: 12%;">${t('day_period')}</th>`;
                for (let p = 1; p <= periodsCount; p++) periodHeaders += '<th style="width: ' + (88 / periodsCount) + '%;">' + p + '</th>';

                let h = `<div class="mb-4"><h5 class="text-center mt-4 mb-2 text-secondary fw-bold">${t('col_teacher')}: ${tItem.name}</h5>` +
                    '<table class="table table-bordered text-center align-middle" style="page-break-inside: avoid;">' +
                    '<thead class="table-light"><tr>' + periodHeaders + '</tr></thead><tbody>';
                for (let d = 0; d < days.length; d++) {
                    h += '<tr><td class="fw-bold bg-light align-middle">' + days[d] + '</td>';
                    for (let p = 1; p <= periodsCount; p++) {
                        let foundClass = '', foundSubject = '';
                        for (const cName of schedule.columns) {
                            const item = schedule.timetables?.[cName]?.[d]?.[p];
                            if (item && item.teacher === tItem.name) { foundClass = cName; foundSubject = item.subject; break; }
                        }
                        if (foundClass) {
                            const foundItem = schedule.timetables?.[foundClass]?.[d]?.[p];
                            const isLocked = !!foundItem?.locked;
                            const lockBadge = isLocked ? `<span class="locked-slot-badge" title="${t('unlock_slot')}"><i class="fas fa-lock"></i></span>` : '';
                            h += `<td class="timetable-cell ${isLocked ? 'bg-warning-subtle' : 'bg-white'}" style="height: 60px; cursor: pointer; position: relative;" onclick="handleTimetableCellClick('${foundClass}', ${d}, ${p})">` +
                                lockBadge + `<span class="fw-bold text-danger d-block">${t('class_label')} ${foundClass}</span><span class="text-muted small">${translateSubjectName(foundSubject)}</span></td>`;
                        } else {
                            h += '<td style="height: 60px;"></td>';
                        }
                    }
                    h += '</tr>';
                }
                h += '</tbody></table></div>';
                finalHTML += h;

                if (renderedCount % 2 === 1 || idx === activeTeachers.length - 1) {
                    finalHTML += '</div>';
                }
                renderedCount++;
            });
            if (!hasAny) finalHTML += `<div class="text-center p-4 text-muted">${t('no_teachers_found')}</div>`;
            finalHTML += '</div>';
            container.innerHTML = finalHTML;
            return;
        }

        let periodHeaders = `<th style="width: 12%;">${t('day_period')}</th>`;
        for (let p = 1; p <= periodsCount; p++) periodHeaders += '<th style="width: ' + (88 / periodsCount) + '%;">' + p + '</th>';

        let h = `<h4 class="text-center mb-3 text-primary" id="timetableGridTitle">${t('tab_timetable')} - ${t('col_teacher')}: ${teacherName}</h4>` +
            '<table class="table table-bordered text-center align-middle" id="timetableGridTable">' +
            '<thead class="table-light"><tr>' + periodHeaders + '</tr></thead><tbody>';
        for (let d = 0; d < days.length; d++) {
            h += '<tr><td class="fw-bold bg-light align-middle">' + days[d] + '</td>';
            for (let p = 1; p <= periodsCount; p++) {
                let foundClass = '', foundSubject = '';
                for (const cName of schedule.columns) {
                    const item = schedule.timetables?.[cName]?.[d]?.[p];
                    if (item && item.teacher === teacherName) { foundClass = cName; foundSubject = item.subject; break; }
                }
                if (foundClass) {
                    const foundItem = schedule.timetables?.[foundClass]?.[d]?.[p];
                    const isLocked = !!foundItem?.locked;
                    const lockBadge = isLocked ? `<span class="locked-slot-badge" title="${t('unlock_slot')}"><i class="fas fa-lock"></i></span>` : '';
                    h += `<td class="timetable-cell ${isLocked ? 'bg-warning-subtle' : 'bg-white'}" style="height: 80px; cursor: pointer; position: relative;" onclick="handleTimetableCellClick('${foundClass}', ${d}, ${p})">` +
                        lockBadge + `<span class="fw-bold text-danger d-block">${t('class_label')} ${foundClass}</span><span class="text-muted small">${translateSubjectName(foundSubject)}</span></td>`;
                } else {
                    h += '<td style="height: 80px;"></td>';
                }
            }
            h += '</tr>';
        }
        h += '</tbody></table>';
        container.innerHTML = h;
    }
    else if (mode === 'master') {
        let h = `<h4 class="text-center mb-3 text-danger">${t('master_class_title')}</h4>`;
        h += '<table class="table table-bordered text-center align-middle bg-white" style="font-size: 0.75rem; width: 100%; table-layout: fixed; min-width: ' + (periodsCount * days.length * 36 + 44) + 'px;">' +
            '<thead class="table-light">' +
            '<tr>' +
            `<th rowspan="2" class="align-middle bg-secondary text-white" style="width: 44px; min-width: 44px; max-width: 44px; position: sticky; right: 0; z-index: 2; font-size: 0.82rem; padding: 2px 2px; line-height: 1.15;">${t('col_class')}</th>`;
        for (let d = 0; d < days.length; d++) h += '<th colspan="' + periodsCount + '" class="border-start border-end border-dark bg-dark text-white py-1" style="font-size: 0.88rem;">' + days[d] + '</th>';
        h += '</tr><tr>';
        for (let d = 0; d < days.length; d++) {
            for (let p = 1; p <= periodsCount; p++) h += '<th class="' + (p === 1 ? 'border-start border-dark' : '') + ' ' + (p === periodsCount ? 'border-end border-dark' : '') + ' bg-secondary text-white py-1" style="font-size: 0.75rem;">' + p + '</th>';
        }
        h += '</tr></thead><tbody>';

        schedule.columns.forEach(className => {
            h += '<tr><td class="fw-bold bg-light text-nowrap align-middle" style="position: sticky; right: 0; z-index: 1; font-size: 0.88rem; width: 44px; min-width: 44px; max-width: 44px; padding: 2px 2px; text-align: center;">' + className + '</td>';
            for (let d = 0; d < days.length; d++) {
                for (let p = 1; p <= periodsCount; p++) {
                    const item = schedule.timetables?.[className]?.[d]?.[p];
                    const borderClass = (p === 1 ? 'border-start border-dark ' : '') + (p === periodsCount ? 'border-end border-dark ' : '');
                    if (item) {
                        const isLocked = !!item.locked;
                        const lockBadge = isLocked ? `<span class="locked-slot-badge" style="font-size: 0.55rem; padding: 1px 3px;" title="${t('unlock_slot')}"><i class="fas fa-lock"></i></span>` : '';
                        h += `<td class="${borderClass} ${isLocked ? 'bg-warning-subtle' : ''} timetable-cell" style="overflow:hidden; vertical-align: middle; cursor: pointer; position: relative;" onclick="handleTimetableCellClick('${className}', ${d}, ${p})" title="${translateSubjectName(item.subject)} (${item.teacher}) - ${t('swap_with_slot')}">` +
                            lockBadge + getSvgFormattedText(getDisplaySubjectName(item.subject, true), true, 'text-primary', 11) + getSvgFormattedText(getTeacherDisplayName(item.teacher), false, 'text-muted', 9.5) + '</td>';
                    } else {
                        h += `<td class="${borderClass} timetable-cell bg-light text-muted opacity-50" style="overflow:hidden; vertical-align: middle; cursor: pointer;" onclick="handleTimetableCellClick('${className}', ${d}, ${p})" title="${t('select_unassigned_for_slot')}"><i class="fas fa-plus text-primary opacity-50" style="font-size: 0.75rem;"></i></td>`;
                    }
                }
            }
            h += '</tr>';
        });
        h += '</tbody></table>';
        container.innerHTML = h;
    }
    else if (mode === 'master_teacher') {
        const activeTeachers = schedule.teachers.filter(t => schedule.columns.reduce((s, c) => s + (t.classes?.[c] ? Object.values(t.classes[c]).reduce((a, b) => a + parseInt(b, 10), 0) : 0), 0) > 0);
        let h = `<h4 class="text-center mb-3 text-warning">${t('master_teacher_title')}</h4>`;
        h += '<table class="table table-bordered text-center align-middle bg-white" style="font-size: 0.75rem; width: 100%; table-layout: fixed; min-width: ' + (periodsCount * days.length * 45 + 155) + 'px;">' +
            '<thead class="table-light">' +
            '<tr>' +
            `<th rowspan="2" class="align-middle bg-secondary text-white" style="width: 155px; min-width: 155px; max-width: 155px; position: sticky; right: 0; top: 0; z-index: 10; border-left: 2px solid #adb5bd !important; box-shadow: -2px 0 6px rgba(0,0,0,0.1);">${t('teacher_period')}</th>`;
        for (let d = 0; d < days.length; d++) h += '<th colspan="' + periodsCount + '" class="border-start border-end border-dark bg-dark text-white">' + days[d] + '</th>';
        h += '</tr><tr>';
        for (let d = 0; d < days.length; d++) {
            for (let p = 1; p <= periodsCount; p++) h += '<th class="' + (p === 1 ? 'border-start border-dark' : '') + ' ' + (p === periodsCount ? 'border-end border-dark' : '') + ' bg-secondary text-white py-1">' + p + '</th>';
        }
        h += '</tr></thead><tbody>';

        activeTeachers.forEach(teacher => {
            h += `<tr><td class="fw-bold bg-light align-middle" style="position: sticky; right: 0; z-index: 2; width: 155px; min-width: 155px; max-width: 155px; border-left: 2px solid #adb5bd !important; box-shadow: -2px 0 6px rgba(0,0,0,0.08); padding: 3px 6px; text-align: center;" title="${teacher.name}"><div style="overflow: hidden; text-overflow: ellipsis; white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; word-break: break-word; line-height: 1.25;">${teacher.name}</div></td>`;
            for (let d = 0; d < days.length; d++) {
                for (let p = 1; p <= periodsCount; p++) {
                    let foundClass = '', foundSubject = '';
                    for (const cName of schedule.columns) {
                        const item = schedule.timetables?.[cName]?.[d]?.[p];
                        if (item && item.teacher === teacher.name) { foundClass = cName; foundSubject = item.subject; break; }
                    }
                    const borderClass = (p === 1 ? 'border-start border-dark ' : '') + (p === periodsCount ? 'border-end border-dark ' : '');
                    if (foundClass) {
                        const foundItem = schedule.timetables?.[foundClass]?.[d]?.[p];
                        const isLocked = !!foundItem?.locked;
                        const lockBadge = isLocked ? `<span class="locked-slot-badge" style="font-size: 0.55rem; padding: 1px 3px;" title="${t('unlock_slot')}"><i class="fas fa-lock"></i></span>` : '';
                        h += `<td class="${borderClass} ${isLocked ? 'bg-warning-subtle' : ''} timetable-cell" style="overflow:hidden; vertical-align: middle; cursor: pointer; position: relative; height: 40px;" onclick="handleTimetableCellClick('${foundClass}', ${d}, ${p})" title="${foundClass} - ${translateSubjectName(foundSubject)}">` +
                            lockBadge + getSvgFormattedText(foundClass, true, 'text-danger', 11) + getSvgFormattedText(getDisplaySubjectName(foundSubject, true), false, 'text-muted', 9.5) + '</td>';
                    } else {
                        h += '<td class="' + borderClass + '" style="overflow:hidden; vertical-align: middle; height: 40px;"></td>';
                    }
                }
            }
            h += '</tr>';
        });
        h += '</tbody></table>';
        container.innerHTML = h;
    }
}

function initSortables() {
    if (typeof Sortable === 'undefined') return;
    sortables.forEach(s => s.destroy());
    sortables = [];

    const commonOptions = {
        group: 'timetable',
        animation: 150,
        ghostClass: 'bg-light',
        onEnd: handleTimetableDrop
    };

    const unassignedList = document.getElementById('unassignedSubjectsList');
    if (unassignedList) sortables.push(new Sortable(unassignedList, commonOptions));

    const cells = document.querySelectorAll('.timetable-cell');
    cells.forEach(cell => {
        sortables.push(new Sortable(cell, { ...commonOptions }));
    });
}




function handleTimetableDrop(evt) {
    const itemEl = evt.item;
    const toEl = evt.to;
    const fromEl = evt.from;
    const schedule = allSchedules[activeScheduleName];

    const toDay = toEl.getAttribute('data-day');
    const toPeriod = toEl.getAttribute('data-period');
    const teacherName = itemEl.getAttribute('data-teacher');

    const targetClassName = toEl.getAttribute('data-class') || document.getElementById('timetableClassSelect').value;
    const itemClassName = itemEl.getAttribute('data-class');

    if (itemClassName && targetClassName && itemClassName !== targetClassName) {
        showToast("نەشێی وانەیەکا پولەکێ ببەیە پولەکا دی!", "error");
        fromEl.appendChild(itemEl);
        return;
    }

    const className = targetClassName;

    if (toDay && toPeriod) {
        Array.from(toEl.children).forEach(child => {
            if (child !== itemEl) {
                document.getElementById('unassignedSubjectsList').appendChild(child);
            }
        });

        let hasConflict = false;
        let conflictClass = '';
        for (const cName in schedule.timetables) {
            if (cName !== className && schedule.timetables[cName]?.[toDay]?.[toPeriod]) {
                if (schedule.timetables[cName][toDay][toPeriod].teacher === teacherName) {
                    hasConflict = true;
                    conflictClass = cName;
                    break;
                }
            }
        }

        if (hasConflict) {
            Swal.fire(t('teacher_busy_title'), t('col_teacher') + ' "' + teacherName + '" ' + t('teacher_busy_conflict'), 'error');
            fromEl.appendChild(itemEl);
            saveTimetableState(className);
            return;
        }

        const subject = itemEl.getAttribute('data-subject');
        let weeklyLoad = 0;
        schedule.teachers.forEach(t => {
            if (t.classes?.[className]?.[subject]) {
                weeklyLoad += parseInt(t.classes[className][subject], 10) || 0;
            }
        });

        const fromDay = fromEl.getAttribute('data-day');
        let existingSubjectCount = 0;
        for (let p in schedule.timetables[className]?.[toDay] || {}) {
            if (schedule.timetables[className][toDay][p]?.subject === subject) {
                existingSubjectCount++;
            }
        }
        if (fromDay === toDay) {
            existingSubjectCount = Math.max(0, existingSubjectCount - 1);
        }

        const maxAllowed = ttGetSubjectMaxDaily(weeklyLoad, (schedule.settings?.workDays || []).length || 5);
        if (existingSubjectCount >= maxAllowed) {
            const errorMsg = maxAllowed === 1
                ? `${t('val_err_duplicate')}: ${translateSubjectName(subject)} (${t('val_load_lbl')}: ${weeklyLoad})`
                : `${t('val_err_limit')}: ${translateSubjectName(subject)} (${t('val_load_lbl')}: ${weeklyLoad})`;
            Swal.fire({
                title: t('val_title') || 'فحص الجدول',
                text: errorMsg,
                icon: 'error'
            });
            fromEl.appendChild(itemEl);
            saveTimetableState(className);
            return;
        }

        const workDays = schedule.settings?.workDays || ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
        if (!ttSubjectCanTakeSlot(subject, workDays[toDay], toPeriod, schedule, className)) {
            showToast(t('subject_restricted_period_warn'), 'warning');
        }
    }

    if (!itemClassName) {
        itemEl.setAttribute('data-class', className);
    }
    saveTimetableState(className);
}
function saveTimetableState(className) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule.timetables[className]) schedule.timetables[className] = {};

    for (let d in schedule.timetables[className]) {
        for (let p in schedule.timetables[className][d]) {
            delete schedule.timetables[className][d][p];
        }
    }

    const cells = document.querySelectorAll('.timetable-cell[data-class="' + className + '"]');
    if (cells.length === 0) {
        // fallback for single view without data-class bound tightly
        const fallbackCells = document.querySelectorAll('#timetableGridTable .timetable-cell');
        fallbackCells.forEach(cell => {
            const day = cell.getAttribute('data-day');
            const period = cell.getAttribute('data-period');
            const itemEl = cell.querySelector('.timetable-item');
            if (itemEl) {
                if (!schedule.timetables[className][day]) schedule.timetables[className][day] = {};
                const isLocked = itemEl.getAttribute('data-locked') === '1' || itemEl.classList.contains('is-locked');
                schedule.timetables[className][day][period] = {
                    id: itemEl.getAttribute('data-id'),
                    subject: itemEl.getAttribute('data-subject'),
                    teacher: itemEl.getAttribute('data-teacher'),
                    className: className,
                    locked: isLocked
                };
            }
        });
    } else {
        cells.forEach(cell => {
            const day = cell.getAttribute('data-day');
            const period = cell.getAttribute('data-period');
            const itemEl = cell.querySelector('.timetable-item');

            if (itemEl) {
                if (!schedule.timetables[className][day]) schedule.timetables[className][day] = {};
                const isLocked = itemEl.getAttribute('data-locked') === '1' || itemEl.classList.contains('is-locked');
                schedule.timetables[className][day][period] = {
                    id: itemEl.getAttribute('data-id'),
                    subject: itemEl.getAttribute('data-subject'),
                    teacher: itemEl.getAttribute('data-teacher'),
                    className: className,
                    locked: isLocked
                };
            }
        });
    }
    saveData();
    renderTimetableGrid();
}
function clearClassTimetable() {
    Swal.fire({
        title: t('confirm_clear_tt_title'),
        text: t('confirm_clear_tt_text'),
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        cancelButtonColor: '#3085d6',
        confirmButtonText: t('btn_yes_clear_all'),
        cancelButtonText: t('cancel')
    }).then((result) => {
        if (result.isConfirmed) {
            allSchedules[activeScheduleName].timetables = {};
            saveData();
            renderTimetableGrid();
            showToast(t('toast_tt_cleared'));
        }
    });
}

function buildSingleClassTimetableHTML(className, perPage = 1) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return '';
    const days = schedule.settings.workDays || ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
    const periodsCount = schedule.settings.periodsPerDay || 7;

    let periodHeaders = '';
    for (let p = 1; p <= periodsCount; p++) {
        periodHeaders += `<th style="width: ${86 / periodsCount}%; border: 1.5px solid #000 !important; background: #e2e8f0 !important; color: #000 !important; font-weight: 800; font-size: ${perPage === 1 ? '11pt' : (perPage === 2 ? '9.5pt' : '8pt')}; padding: 4px 1px; height: 26px;">${p}</th>`;
    }

    let cellHeight = Math.min(130, Math.max(90, Math.floor(620 / Math.max(1, days.length)))) + 'px';
    let subjFontSize = '15pt';
    let teachFontSize = '12pt';
    let titleFontSize = '16pt';
    let dayFontSize = '13pt';

    if (perPage === 4) {
        cellHeight = Math.min(68, Math.max(48, Math.floor(305 / Math.max(1, days.length)))) + 'px';
        subjFontSize = '8.5pt';
        teachFontSize = '7.5pt';
        titleFontSize = '11pt';
        dayFontSize = '8.5pt';
    } else if (perPage === 3) {
        cellHeight = Math.min(60, Math.max(45, Math.floor(275 / Math.max(1, days.length)))) + 'px';
        subjFontSize = '9.5pt';
        teachFontSize = '8pt';
        titleFontSize = '11.5pt';
        dayFontSize = '9pt';
    } else if (perPage === 2) {
        cellHeight = Math.min(95, Math.max(70, Math.floor(430 / Math.max(1, days.length)))) + 'px';
        subjFontSize = '12pt';
        teachFontSize = '10pt';
        titleFontSize = '13.5pt';
        dayFontSize = '11pt';
    }

    const schoolName = schedule.settings?.globalSchoolName || schedule.milak?.schoolName || '';
    let html = `<h3 class="text-center mb-1 pb-1" style="font-size: ${titleFontSize}; font-weight: 800; color: #000; border-bottom: 1.5px solid #000; margin: 0 0 4px 0;">${schoolName ? `${schoolName} - ` : ''}خشتێ حەفتیانە یێ پولا: ${className}</h3>`;
    html += `<table class="table table-bordered text-center align-middle preserve-table-styles" style="table-layout: fixed; width: 100%; border: 1.5px solid #000 !important; border-collapse: collapse !important; margin: 0;">
            <thead class="table-light"><tr><th style="width: 14%; border: 1.5px solid #000 !important; background: #e2e8f0 !important; color: #000 !important; font-weight: 800; font-size: ${perPage === 1 ? '11pt' : (perPage === 2 ? '9.5pt' : '8pt')}; padding: 4px 1px; height: 26px;">${t('day_period') || 'الروژ \\ حەسە'}</th>${periodHeaders}</tr></thead><tbody>`;
    for (let d = 0; d < days.length; d++) {
        html += `<tr><td style="width: 14%; border: 1.5px solid #000 !important; background: #f8fafc !important; color: #000 !important; font-weight: 800; font-size: ${dayFontSize}; padding: 2px 1px; vertical-align: middle; height: ${cellHeight};">${days[d]}</td>`;
        for (let p = 1; p <= periodsCount; p++) {
            const item = schedule.timetables?.[className]?.[d]?.[p];
            const teacherFirst = item ? getTeacherFirstNameOnly(item.teacher) : '';
            html += `<td style="border: 1px solid #000 !important; padding: 2px 1px; height: ${cellHeight}; min-height: ${cellHeight}; vertical-align: middle; text-align: center; overflow: hidden;">${item ? `<div style="font-weight: 800; color: #000 !important; font-size: ${subjFontSize}; line-height: 1.25; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${translateSubjectName(item.subject)}</div><div style="font-weight: 700; color: #1e293b !important; font-size: ${teachFontSize}; line-height: 1.15; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; margin-top: 4px;">${teacherFirst}</div>` : ''}</td>`;
        }
        html += `</tr>`;
    }
    html += `</tbody></table>`;
    return html;
}

function buildSingleTeacherTimetableHTML(teacher, perPage = 1) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !teacher) return '';
    const days = schedule.settings.workDays || ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
    const periodsCount = schedule.settings.periodsPerDay || 7;

    let periodHeaders = '';
    for (let p = 1; p <= periodsCount; p++) {
        periodHeaders += `<th style="width: ${86 / periodsCount}%; border: 1.5px solid #000 !important; background: #e2e8f0 !important; color: #000 !important; font-weight: 800; font-size: ${perPage === 1 ? '11pt' : (perPage === 2 ? '9.5pt' : '8pt')}; padding: 4px 1px; height: 26px;">${p}</th>`;
    }

    let cellHeight = Math.min(130, Math.max(90, Math.floor(620 / Math.max(1, days.length)))) + 'px';
    let classFontSize = '15pt';
    let subjFontSize = '12pt';
    let titleFontSize = '16pt';
    let dayFontSize = '13pt';

    if (perPage === 4) {
        cellHeight = Math.min(68, Math.max(48, Math.floor(305 / Math.max(1, days.length)))) + 'px';
        classFontSize = '8.5pt';
        subjFontSize = '7.5pt';
        titleFontSize = '11pt';
        dayFontSize = '8.5pt';
    } else if (perPage === 3) {
        cellHeight = Math.min(60, Math.max(45, Math.floor(275 / Math.max(1, days.length)))) + 'px';
        classFontSize = '9.5pt';
        subjFontSize = '8pt';
        titleFontSize = '11.5pt';
        dayFontSize = '9pt';
    } else if (perPage === 2) {
        cellHeight = Math.min(95, Math.max(70, Math.floor(430 / Math.max(1, days.length)))) + 'px';
        classFontSize = '12pt';
        subjFontSize = '10pt';
        titleFontSize = '13.5pt';
        dayFontSize = '11pt';
    }

    const teacherName = typeof teacher === 'string' ? teacher : teacher.name;
    const teacherObj = typeof teacher === 'object' ? teacher : (schedule.teachers.find(t => t.name === teacherName) || { name: teacherName });

    const schoolName = schedule.settings?.globalSchoolName || schedule.milak?.schoolName || '';
    let html = `<h3 class="text-center mb-1 pb-1" style="font-size: ${titleFontSize}; font-weight: 800; color: #000; border-bottom: 1.5px solid #000; margin: 0 0 4px 0;">${schoolName ? `${schoolName} - ` : ''}خشتێ حەفتیانە یێ ماموستا: ${teacherName}</h3>`;
    html += `<table class="table table-bordered text-center align-middle preserve-table-styles" style="table-layout: fixed; width: 100%; border: 1.5px solid #000 !important; border-collapse: collapse !important; margin: 0;">
            <thead class="table-light"><tr><th style="width: 14%; border: 1.5px solid #000 !important; background: #e2e8f0 !important; color: #000 !important; font-weight: 800; font-size: ${perPage === 1 ? '11pt' : (perPage === 2 ? '9.5pt' : '8pt')}; padding: 4px 1px; height: 26px;">${t('day_period') || 'الروژ \\ حەسە'}</th>${periodHeaders}</tr></thead><tbody>`;
    for (let d = 0; d < days.length; d++) {
        const isOffDay = teacherObj.offDays && teacherObj.offDays.includes(days[d]);
        html += `<tr><td style="width: 14%; border: 1.5px solid #000 !important; background: #f8fafc !important; color: #000 !important; font-weight: 800; font-size: ${dayFontSize}; padding: 2px 1px; vertical-align: middle; height: ${cellHeight};">${days[d]}</td>`;

        if (isOffDay) {
            html += `<td colspan="${periodsCount}" style="border: 1px solid #000 !important; background: #475569 !important; color: #fff !important; font-weight: 800; font-size: ${perPage >= 3 ? '8.5pt' : '10.5pt'}; vertical-align: middle; letter-spacing: 1px; height: ${cellHeight};">بهێنڤەدان (يوم إجازة للمعلم)</td></tr>`;
            continue;
        }

        for (let p = 1; p <= periodsCount; p++) {
            let foundClass = '', foundSubject = '';
            for (const cName of schedule.columns) {
                const item = schedule.timetables?.[cName]?.[d]?.[p];
                if (item && item.teacher === teacherName) {
                    foundClass = cName;
                    foundSubject = item.subject;
                    break;
                }
            }
            html += `<td style="border: 1px solid #000 !important; padding: 2px 1px; height: ${cellHeight}; min-height: ${cellHeight}; vertical-align: middle; text-align: center; overflow: hidden;">${foundClass ? `<div style="font-weight: 800; color: #dc2626 !important; font-size: ${classFontSize}; line-height: 1.25; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${t('class_label') || 'پولا'} ${foundClass}</div><div style="font-weight: 700; color: #000 !important; font-size: ${subjFontSize}; line-height: 1.15; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; margin-top: 4px;">${translateSubjectName(foundSubject)}</div>` : ''}</td>`;
        }
        html += `</tr>`;
    }
    html += `</tbody></table>`;
    return html;
}

function printCurrentTimetableView() {
    const mode = document.querySelector('input[name="ttViewMode"]:checked')?.value || 'class';
    if (mode === 'substitute') {
        printDailySubstitutionReport('current');
        return;
    }
    if (mode === 'master') {
        printMasterTimetable('landscape');
        return;
    }
    if (mode === 'master_teacher') {
        printMasterTeacherTimetable('landscape');
        return;
    }

    const schedule = allSchedules[activeScheduleName] || {};
    const principalName = schedule.settings?.principalName || '';
    let sigHtml = '';
    if (principalName) {
        sigHtml = `<div style="display: block; width: 100%; margin-top: 8px; clear: both; page-break-inside: avoid;"><div style="float: left; text-align: center; width: 220px; direction: rtl; margin-left: 15px;"><p class="mb-0" style="font-size: 8.5pt; font-weight: bold; margin-bottom: 2px;">${t('signature_approved_by') || 'المصادقة'}</p><p class="fw-bold mb-0" style="font-size: 8.5pt; margin-bottom: 2px;">${t('signature_principal') || 'مدير المدرسة'}</p><p class="fw-bold mb-0" style="font-size: 8.5pt; margin-top: 2px; margin-bottom: 0;">${principalName}</p></div><div style="clear: both;"></div></div>`;
    }

    if (mode === 'class') {
        const classSelect = document.getElementById('timetableClassSelect');
        const selectedClass = classSelect ? classSelect.value : '';
        if (selectedClass === 'all_classes' || !selectedClass) {
            printClassTimetables(1);
            return;
        }
        const singleHtml = `<div style="padding: 4px; width: 100%;">${buildSingleClassTimetableHTML(selectedClass, 1)}${sigHtml}</div>`;
        printWithContent(selectedClass, singleHtml, { orientation: 'landscape' });
        return;
    }

    if (mode === 'teacher') {
        const teacherSelect = document.getElementById('timetableTeacherSelect');
        const selectedTeacher = teacherSelect ? teacherSelect.value : '';
        if (selectedTeacher === 'all_teachers' || !selectedTeacher) {
            printTeacherTimetables(1);
            return;
        }
        const singleHtml = `<div style="padding: 4px; width: 100%;">${buildSingleTeacherTimetableHTML(selectedTeacher, 1)}${sigHtml}</div>`;
        printWithContent(selectedTeacher, singleHtml, { orientation: 'landscape' });
        return;
    }
}


// --- Advanced Timetable Features (Auto-Distribute & Master Prints) ---
function autoDistributeTimetableLegacy() {
    Swal.fire({
        title: 'دابەشکرنا ئۆتۆماتیکی',
        text: 'ئایا تە دڤێت سیستەم ب شێوەیەكێ ئۆتۆماتیکی هەمی وانەیێن بێ جهـ بۆ هەمی پولان دابەش بکەت؟ ڤێ چەندێ دبت دەمەکێ کێم پێدڤی بت.',
        icon: 'question',
        showCancelButton: true,
        confirmButtonText: 'بەڵی، دابەش بکە',
        cancelButtonText: 'هه‌لوه‌شاندن'
    }).then((result) => {
        if (result.isConfirmed) {
            const schedule = allSchedules[activeScheduleName];
            const days = schedule.settings.workDays || ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
            const periodsCount = schedule.settings.periodsPerDay || 7;

            if (!schedule.timetables) schedule.timetables = {};

            let unassigned = [];
            // 1. Gather all required items
            schedule.columns.forEach(className => {
                if (!schedule.timetables[className]) schedule.timetables[className] = {};
                schedule.teachers.forEach(teacher => {
                    if (teacher.classes?.[className]) {
                        Object.entries(teacher.classes[className]).forEach(([subject, periods]) => {
                            for (let i = 0; i < periods; i++) {
                                unassigned.push({ className, id: `t_${teacher.id}_${subject}_${i}`, subject, teacher: teacher.name });
                            }
                        });
                    }
                });
            });

            // 2. Filter out already assigned
            unassigned = unassigned.filter(req => {
                for (let d = 0; d < days.length; d++) {
                    for (let p = 1; p <= periodsCount; p++) {
                        const item = schedule.timetables[req.className]?.[d]?.[p];
                        if (item && item.teacher === req.teacher && item.subject === req.subject && !item._matched) {
                            item._matched = true;
                            return false;
                        }
                    }
                }
                return true;
            });

            // Cleanup temp flag
            schedule.columns.forEach(className => {
                for (let d = 0; d < days.length; d++) {
                    for (let p = 1; p <= periodsCount; p++) {
                        if (schedule.timetables[className]?.[d]?.[p]) delete schedule.timetables[className][d][p]._matched;
                    }
                }
            });

            // 3. Multi-Pass Greedy Placement
            const MAX_ITERATIONS = 500; // Boosted to 500 iter for maximum conflict resolution
            let bestDistribution = null;
            let bestUnassignedCount = Infinity;
            let bestPlacedCount = 0;

            for (let iter = 0; iter < MAX_ITERATIONS; iter++) {
                // Clone the clean unassigned state
                let tempUnassigned = JSON.parse(JSON.stringify(unassigned));

                // Shuffle the tie-breaking rules
                tempUnassigned.sort((a, b) => {
                    const weightA = parseInt(schedule.teachers.find(t => t.name === a.teacher)?.classes[a.className]?.[a.subject] || 0);
                    const weightB = parseInt(schedule.teachers.find(t => t.name === b.teacher)?.classes[b.className]?.[b.subject] || 0);
                    if (weightB === weightA) return Math.random() - 0.5; // Crucial: Randomness makes iterations useful
                    return weightB - weightA;
                });

                // Clone the current timetables struct
                let tempTimetables = JSON.parse(JSON.stringify(schedule.timetables || {}));

                let currentPlacedCount = 0;
                tempUnassigned.forEach(item => {
                    let placed = false;

                    let totalTeacherPeriodsInClass = 0;
                    let teacherObj = schedule.teachers.find(t => t.name === item.teacher);
                    if (teacherObj && teacherObj.classes?.[item.className]) {
                        Object.values(teacherObj.classes[item.className]).forEach(p => totalTeacherPeriodsInClass += parseInt(p, 10));
                    }

                    let availableDaysCount = days.length;
                    if (teacherObj && teacherObj.offDays) {
                        availableDaysCount -= teacherObj.offDays.filter(day => days.includes(day)).length;
                    }
                    if (availableDaysCount <= 0) availableDaysCount = 1;
                    const maxTeacherPerDay = Math.ceil(totalTeacherPeriodsInClass / availableDaysCount);

                    let currentMaxPerDay = maxTeacherPerDay;
                    while (!placed && currentMaxPerDay <= periodsCount) {
                        let teacherDailyLoad = Array(days.length).fill(0);
                        for (let day = 0; day < days.length; day++) {
                            for (const cName of schedule.columns) {
                                for (let period = 1; period <= periodsCount; period++) {
                                    if (tempTimetables[cName]?.[day]?.[period]?.teacher === item.teacher) teacherDailyLoad[day]++;
                                }
                            }
                        }

                        let preferredDays = [];
                        for (let d = 0; d < days.length; d++) preferredDays.push(d);
                        preferredDays.sort((a, b) => {
                            if (teacherDailyLoad[a] === teacherDailyLoad[b]) return Math.random() - 0.5;
                            return teacherDailyLoad[a] - teacherDailyLoad[b];
                        });

                        for (let dayOrder = 0; dayOrder < preferredDays.length && !placed; dayOrder++) {
                            let d = preferredDays[dayOrder];
                            let dayName = days[d];
                            if (teacherObj && teacherObj.offDays && teacherObj.offDays.includes(dayName)) continue;

                            let teacherSameDayCount = 0;
                            for (let checkP = 1; checkP <= periodsCount; checkP++) {
                                if (tempTimetables[item.className]?.[d]?.[checkP]?.teacher === item.teacher) teacherSameDayCount++;
                            }
                            if (teacherSameDayCount >= currentMaxPerDay) continue;

                            let periodUsageCount = Array(periodsCount + 1).fill(0);
                            for (let day = 0; day < days.length; day++) {
                                for (let period = 1; period <= periodsCount; period++) {
                                    if (tempTimetables[item.className]?.[day]?.[period]?.teacher === item.teacher) {
                                        periodUsageCount[period]++;
                                    }
                                }
                            }

                            let preferredPeriods = [];
                            for (let p = 1; p <= periodsCount; p++) preferredPeriods.push(p);

                            preferredPeriods.sort((a, b) => {
                                if (periodUsageCount[a] === periodUsageCount[b]) return Math.random() - 0.5;
                                return periodUsageCount[a] - periodUsageCount[b];
                            });

                            for (let i = 0; i < preferredPeriods.length && !placed; i++) {
                                let p = preferredPeriods[i];

                                if (teacherObj?.blockedPeriods?.[dayName] && teacherObj.blockedPeriods[dayName].includes(p)) continue;

                                if (!tempTimetables[item.className][d]) tempTimetables[item.className][d] = {};
                                if (!tempTimetables[item.className][d][p]) {
                                    let teacherFree = true;
                                    for (const cName of schedule.columns) {
                                        if (tempTimetables[cName]?.[d]?.[p]?.teacher === item.teacher) {
                                            teacherFree = false;
                                            break;
                                        }
                                    }
                                    if (teacherFree) {
                                        tempTimetables[item.className][d][p] = {
                                            id: item.id, subject: item.subject, teacher: item.teacher
                                        };
                                        placed = true;
                                        currentPlacedCount++;
                                    }
                                }
                            }
                        }
                        if (!placed) {
                            currentMaxPerDay++; // Relax constraint and try again!
                        }
                    }
                });

                let currentUnassignedCount = tempUnassigned.length - currentPlacedCount;
                if (currentUnassignedCount < bestUnassignedCount) {
                    bestUnassignedCount = currentUnassignedCount;
                    bestPlacedCount = currentPlacedCount;
                    bestDistribution = JSON.parse(JSON.stringify(tempTimetables));

                    if (bestUnassignedCount === 0) break; // Solved perfectly!
                }
            }

            if (bestDistribution) {
                schedule.timetables = bestDistribution;
            }

            saveData();
            renderTimetableGrid();
            const remaining = bestUnassignedCount;
            Swal.fire('تم التوزيع التلقائي', `هاتنە دابەشكرن ب سەركەفتیانە: ${bestPlacedCount} وانە.<br>${remaining > 0 ? `تێبینی: ${remaining} وانە نه‌هاتنە دابەشكرن ژبەر تێكچوونا دەمان (تعارض). پێدڤیە دەستكاریێ ب دەستی بكەی.` : 'هەمی وانە بێ كێشە جهـ گرتن!'}`, remaining > 0 ? 'warning' : 'success');
        }
    });
}

function ttBuildRequiredItems(schedule) {
    const items = [];
    schedule.columns.forEach(className => {
        schedule.teachers.forEach(teacher => {
            if (!teacher.classes?.[className]) return;
            Object.entries(teacher.classes[className]).forEach(([subject, rawPeriods]) => {
                const periods = parseInt(rawPeriods, 10) || 0;
                for (let i = 0; i < periods; i++) {
                    items.push({
                        className,
                        subject,
                        teacher: teacher.name,
                        id: `t_${teacher.id}_${className}_${subject}_${i}`
                    });
                }
            });
        });
    });
    return items;
}

function ttCreateEmpty(columns) {
    const timetables = {};
    columns.forEach(className => { timetables[className] = {}; });
    return timetables;
}

function ttReqKey(item) {
    return `${item.className}|||${item.teacher}|||${item.subject}`;
}

function ttClassDayLoad(timetables, className, dayIndex) {
    return Object.keys(timetables[className]?.[dayIndex] || {}).length;
}

function ttSubjectDayLoad(timetables, className, dayIndex, subject) {
    return Object.values(timetables[className]?.[dayIndex] || {}).filter(item => item.subject === subject).length;
}

function ttTeacherDayLoad(timetables, columns, teacherName, dayIndex, periodsCount) {
    let total = 0;
    columns.forEach(className => {
        for (let p = 1; p <= periodsCount; p++) {
            if (timetables[className]?.[dayIndex]?.[p]?.teacher === teacherName) total++;
        }
    });
    return total;
}

function ttTeacherPeriodUsage(timetables, columns, teacherName, period, daysCount) {
    let total = 0;
    columns.forEach(className => {
        for (let d = 0; d < daysCount; d++) {
            if (timetables[className]?.[d]?.[period]?.teacher === teacherName) total++;
        }
    });
    return total;
}

function ttTeacherBusy(timetables, columns, teacherName, dayIndex, period, excludeClassName = null) {
    return columns.some(className => {
        if (excludeClassName && className === excludeClassName) return false;
        return timetables[className]?.[dayIndex]?.[period]?.teacher === teacherName;
    });
}

function ttTeacherCanTake(teacherObj, dayName, period) {
    if (!teacherObj) return true;
    if (teacherObj.offDays?.includes(dayName)) return false;
    if (teacherObj.blockedPeriods?.[dayName]?.includes(period)) return false;
    return true;
}

function ttPlaceItem(timetables, item, dayIndex, period) {
    if (!timetables[item.className]) timetables[item.className] = {};
    if (!timetables[item.className][dayIndex]) timetables[item.className][dayIndex] = {};
    timetables[item.className][dayIndex][period] = {
        id: item.id,
        subject: item.subject,
        teacher: item.teacher,
        locked: !!item.locked
    };
}

function ttBuildMeta(schedule, days, periodsCount, requiredItems) {
    const classLoad = {};
    const teacherLoad = {};
    const teacherAvailability = {};
    const classDailyTarget = {};
    const teacherDailyTarget = {};
    const pairLoad = {};
    const classSubjectLoad = {};

    requiredItems.forEach(item => {
        classLoad[item.className] = (classLoad[item.className] || 0) + 1;
        teacherLoad[item.teacher] = (teacherLoad[item.teacher] || 0) + 1;
        pairLoad[ttReqKey(item)] = (pairLoad[ttReqKey(item)] || 0) + 1;
        const csKey = `${item.className}|||${item.subject}`;
        classSubjectLoad[csKey] = (classSubjectLoad[csKey] || 0) + 1;
    });

    schedule.columns.forEach(className => {
        classDailyTarget[className] = Math.ceil((classLoad[className] || 0) / Math.max(days.length, 1));
    });

    schedule.teachers.forEach(teacher => {
        let available = 0;
        days.forEach(dayName => {
            if (teacher.offDays?.includes(dayName)) return;
            for (let period = 1; period <= periodsCount; period++) {
                if (!teacher.blockedPeriods?.[dayName] || !teacher.blockedPeriods[dayName].includes(period)) {
                    available++;
                }
            }
        });
        teacherAvailability[teacher.name] = available;
        const workingDays = Math.max(days.filter(dayName => !teacher.offDays?.includes(dayName)).length, 1);
        teacherDailyTarget[teacher.name] = Math.ceil((teacherLoad[teacher.name] || 0) / workingDays);
    });

    return { classLoad, teacherLoad, teacherAvailability, classDailyTarget, teacherDailyTarget, pairLoad, classSubjectLoad };
}

function ttGetSubjectMaxDaily(weeklyLoad, daysCount = 5) {
    if (weeklyLoad >= 1 && weeklyLoad <= 5) return 1;
    if (weeklyLoad >= 6 && weeklyLoad <= 10) return 2;
    if (weeklyLoad > 10) return Math.max(2, Math.ceil(weeklyLoad / Math.max(daysCount, 1)));
    return 1;
}

function ttCanPlaceSubject(timetables, className, dayIndex, subject, meta, daysCount = 5) {
    const csKey = `${className}|||${subject}`;
    const weeklyLoad = meta?.classSubjectLoad?.[csKey] || 1;
    const maxDaily = ttGetSubjectMaxDaily(weeklyLoad, daysCount);
    const currentCount = ttSubjectDayLoad(timetables, className, dayIndex, subject);
    return currentCount < maxDaily;
}

function ttCandidateSlots(schedule, timetables, item, days, periodsCount, meta, blockedSlotKey = null) {
    const teacherObj = schedule.teachers.find(t => t.name === item.teacher);
    const slots = [];
    const csKey = `${item.className}|||${item.subject}`;
    const weeklyLoad = meta?.classSubjectLoad?.[csKey] || 1;
    const maxDaily = ttGetSubjectMaxDaily(weeklyLoad, days.length);

    for (let d = 0; d < days.length; d++) {
        const dayName = days[d];
        if (!ttSubjectCanTakeSlot(item.subject, dayName, null, schedule, item.className)) continue;

        // Hard rule: Do not exceed daily quota for this subject in this class
        const currentSubjectInDay = ttSubjectDayLoad(timetables, item.className, d, item.subject);
        if (currentSubjectInDay >= maxDaily) continue;

        for (let p = 1; p <= periodsCount; p++) {
            const slotKey = `${item.className}|${d}|${p}`;
            if (blockedSlotKey && slotKey === blockedSlotKey) continue;
            if (!ttSubjectCanTakeSlot(item.subject, dayName, p, schedule, item.className)) continue;
            if (!ttTeacherCanTake(teacherObj, dayName, p)) continue;
            if (timetables[item.className]?.[d]?.[p]) continue;
            if (ttTeacherBusy(timetables, schedule.columns, item.teacher, d, p)) continue;

            const classDayLoad = ttClassDayLoad(timetables, item.className, d);
            const teacherDayLoad = ttTeacherDayLoad(timetables, schedule.columns, item.teacher, d, periodsCount);
            const teacherPeriodUsage = ttTeacherPeriodUsage(timetables, schedule.columns, item.teacher, p, days.length);

            const classTargetPenalty = classDayLoad >= (meta.classDailyTarget[item.className] || periodsCount) ? 5 : 0;
            const teacherTargetPenalty = teacherDayLoad >= (meta.teacherDailyTarget[item.teacher] || periodsCount) ? 6 : 0;

            // Priority 4: For subjects with load 6-10, distribute across empty days first before taking a 2nd period in a day
            const spreadPenalty = currentSubjectInDay > 0 ? 400 : 0;

            // Priority 5: Avoid consecutive periods of the same subject unless necessary
            let consecutivePenalty = 0;
            if (p > 1 && timetables[item.className]?.[d]?.[p - 1]?.subject === item.subject) {
                consecutivePenalty += 30;
            }
            if (p < periodsCount && timetables[item.className]?.[d]?.[p + 1]?.subject === item.subject) {
                consecutivePenalty += 30;
            }

            const score =
                (classDayLoad * 6) +
                spreadPenalty +
                consecutivePenalty +
                (teacherDayLoad * 8) +
                (teacherPeriodUsage * 3) +
                (classTargetPenalty * 5) +
                (teacherTargetPenalty * 6) +
                Math.random();

            slots.push({ dayIndex: d, period: p, score });
        }
    }

    slots.sort((a, b) => a.score - b.score);
    return slots;
}

function openTeacherModalWithAvailability(teacherId) {
    if (!teacherId) return;
    try {
        Swal.close();
    } catch (e) { }
    openTeacherModal(teacherId);
    setTimeout(() => {
        const availTabBtn = document.getElementById('availability-tab');
        if (availTabBtn) {
            availTabBtn.click();
        }
    }, 300);
}

function getTeacherBlockedInfo(teacher, days, periodsCount) {
    if (!teacher) return { totalBlocked: 0, offDaysCount: 0, details: [], hasRestrictions: false };
    const offDays = teacher.offDays || [];
    const blockedPeriods = teacher.blockedPeriods || {};
    let totalBlocked = 0;
    const details = [];

    if (offDays.length > 0) {
        details.push(`روژێن بێهنڤەدانێ (عطلة): ${offDays.join(', ')}`);
    }

    Object.entries(blockedPeriods).forEach(([dayName, periods]) => {
        if (Array.isArray(periods) && periods.length > 0) {
            totalBlocked += periods.length;
            details.push(`${dayName}: وانەیێن (${periods.join(', ')})`);
        }
    });

    return {
        totalBlocked,
        offDaysCount: offDays.length,
        details,
        hasRestrictions: offDays.length > 0 || totalBlocked > 0
    };
}

function autoFixTimetableError(errorIndex) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;
    const initialValidation = validateTimetableSchedule(schedule);
    const err = initialValidation.errors[errorIndex];
    if (!err) return;

    const days = initialValidation.days;
    const periodsCount = initialValidation.periodsCount;
    const meta = initialValidation.meta;
    let fixed = false;

    if (err.type === 'DAILY_DUPLICATE' || err.type === 'DAILY_LIMIT') {
        const className = err.className;
        const subject = err.subject;
        const badDayIndex = err.dayIndex;
        const maxAllowed = err.maxAllowed;

        // Find periods for this subject on bad day
        const periodsWithSubject = [];
        for (let p = 1; p <= periodsCount; p++) {
            if (schedule.timetables[className]?.[badDayIndex]?.[p]?.subject === subject) {
                periodsWithSubject.push(p);
            }
        }

        const surplusPeriods = periodsWithSubject.slice(maxAllowed);
        for (const badPeriod of surplusPeriods) {
            if (ttTryDirectSwapForDuplicate(schedule, className, badDayIndex, badPeriod, meta, days, periodsCount)) {
                fixed = true;
            }
        }
    }

    // Verify whether errors genuinely decreased
    const updatedValidation = validateTimetableSchedule(schedule);
    const genuinelyFixed = updatedValidation.errors.length < initialValidation.errors.length || (fixed && updatedValidation.errors.every(e => !(e.className === err.className && e.subject === err.subject && e.dayIndex === err.dayIndex)));

    if (genuinelyFixed) {
        saveData();
        renderTimetableGrid();
        showScheduleValidationModal();
        showToast(t('val_fixed_success'), 'success');
    } else {
        saveData();
        renderTimetableGrid();

        // Check if teacher has blocked periods causing this restriction
        const offendingTeacherName = err.teacher || schedule.timetables[err.className]?.[err.dayIndex]?.[1]?.teacher;
        const teacherObj = schedule.teachers.find(t => t.name === offendingTeacherName) || schedule.teachers.find(t => t.classes?.[err.className]?.[err.subject]);
        const blockedInfo = getTeacherBlockedInfo(teacherObj, days, periodsCount);

        if (teacherObj && blockedInfo.hasRestrictions) {
            Swal.fire({
                title: `<span class="text-danger"><i class="fas fa-calendar-times me-2"></i>${t('val_blocked_warning_title')}</span>`,
                html: `
                    <div class="text-start p-3 bg-light rounded border border-danger shadow-sm" style="direction: rtl;">
                        <p class="mb-2 text-dark"><strong>${t('val_blocked_warning_desc')}</strong></p>
                        <div class="mb-2 p-2 bg-white rounded border">
                            <div><strong>${t('teacher_word')}:</strong> <span class="text-primary fw-bold">${teacherObj.name}</span></div>
                            <div><strong>${t('val_subject_lbl')}:</strong> <span class="text-dark fw-bold">${translateSubjectName(err.subject)}</span> | <strong>${t('val_class_lbl')}:</strong> <span class="text-dark fw-bold">${err.className}</span></div>
                            <div class="text-danger mt-1"><strong>${t('val_teacher_blocked_count')}:</strong> <span class="badge bg-danger fs-6">${blockedInfo.totalBlocked}</span> ${blockedInfo.offDaysCount > 0 ? `+ (${blockedInfo.offDaysCount} روژێن بێهنڤەدانێ)` : ''}</div>
                        </div>
                        <div class="small text-muted mb-3">
                            ${blockedInfo.details.map(d => `<div class="mb-1"><i class="fas fa-times-circle text-danger me-1"></i>${d}</div>`).join('')}
                        </div>
                        <button class="btn btn-primary w-100 fw-bold py-2 shadow-sm" onclick="openTeacherModalWithAvailability(${teacherObj.id})">
                            <i class="fas fa-unlock me-2"></i>${t('val_btn_open_teacher_blocked')}
                        </button>
                    </div>
                `,
                icon: 'warning',
                showConfirmButton: false,
                showCancelButton: true,
                cancelButtonText: t('btn_close'),
                width: '580px',
                customClass: { popup: 'swal2-modal-responsive' }
            });
        } else {
            showScheduleValidationModal();
            showToast(t('val_fix_failed'), 'warning');
        }
    }
}

function autoFixAllTimetableErrors() {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;

    const initialValidation = validateTimetableSchedule(schedule);
    if (initialValidation.errors.length === 0) {
        showToast(t('val_all_valid_title'), 'info');
        return;
    }

    const days = initialValidation.days;
    const periodsCount = initialValidation.periodsCount;
    const meta = initialValidation.meta;

    // Iteratively apply targeted direct and chain swaps for every duplicate error
    let maxPasses = 20;
    while (maxPasses > 0) {
        maxPasses--;
        const currentValidation = validateTimetableSchedule(schedule);
        if (currentValidation.errors.length === 0) break;

        let passChanged = false;
        for (const err of currentValidation.errors) {
            if (err.type === 'DAILY_DUPLICATE' || err.type === 'DAILY_LIMIT') {
                const periodsWithSubject = [];
                for (let p = 1; p <= periodsCount; p++) {
                    if (schedule.timetables[err.className]?.[err.dayIndex]?.[p]?.subject === err.subject) {
                        periodsWithSubject.push(p);
                    }
                }
                const surplus = periodsWithSubject.slice(err.maxAllowed);
                for (const p of surplus) {
                    if (ttTryDirectSwapForDuplicate(schedule, err.className, err.dayIndex, p, meta, days, periodsCount)) {
                        passChanged = true;
                        break;
                    }
                }
            }
            if (passChanged) break;
        }
        if (!passChanged) break;
    }

    const finalValidation = validateTimetableSchedule(schedule);

    saveData();
    renderTimetableGrid();
    showScheduleValidationModal();

    if (finalValidation.errors.length === 0) {
        showToast(t('val_all_fixed_success'), 'success');
    } else if (finalValidation.errors.length < initialValidation.errors.length) {
        showToast(`هاتنە چاککرن: ${initialValidation.errors.length - finalValidation.errors.length} کێشە. ماینە: ${finalValidation.errors.length}`, 'info');
    } else {
        showToast(t('val_fix_failed'), 'warning');
    }
}

function showScheduleValidationModal() {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;
    const validation = validateTimetableSchedule(schedule);
    const days = validation.days;
    const periodsCount = validation.periodsCount;

    // Find all teachers with blocked periods
    const restrictedTeachers = [];
    (schedule.teachers || []).forEach(teacher => {
        const info = getTeacherBlockedInfo(teacher, days, periodsCount);
        if (info.hasRestrictions) {
            restrictedTeachers.push({ teacher, info });
        }
    });

    let restrictionsHTML = '';
    if (restrictedTeachers.length > 0) {
        restrictionsHTML = `
            <div class="mt-2 p-2 bg-light rounded border shadow-sm text-start" style="direction: rtl; font-size: 0.75rem;">
                <h6 class="text-danger fw-bold mb-1" style="font-size: 0.78rem;"><i class="fas fa-calendar-times me-1"></i>${t('val_teacher_restrictions_title')} (${restrictedTeachers.length}):</h6>
                <div class="small text-muted mb-1" style="font-size: 0.7rem;">ئەڤ ماموستایێن ل خوارێ هندەک وانە یان روژ یێن قەدەغەکرین (حظر الحصص):</div>
                <div class="d-flex flex-column gap-1" style="max-height: 120px; overflow-y: auto;">
                    ${restrictedTeachers.map(item => `
                        <div class="d-flex justify-content-between align-items-center bg-white p-1.5 px-2 rounded border border-light-subtle">
                            <div>
                                <strong class="text-primary" style="font-size: 0.75rem;">${item.teacher.name}</strong>
                                <span class="badge bg-danger ms-1" style="font-size: 0.65rem;">${item.info.totalBlocked} ${t('val_teacher_blocked_count')}</span>
                                ${item.info.offDaysCount > 0 ? `<span class="badge bg-secondary ms-1" style="font-size: 0.65rem;">${item.info.offDaysCount} روژ</span>` : ''}
                            </div>
                            <button class="btn btn-sm btn-outline-danger py-0.5 px-2 fw-bold" style="font-size: 0.68rem;" onclick="openTeacherModalWithAvailability(${item.teacher.id})">
                                <i class="fas fa-unlock me-1"></i>${t('val_btn_open_teacher_blocked')}
                            </button>
                        </div>
                    `).join('')}
                </div>
            </div>
        `;
    }

    if (validation.isValid) {
        Swal.fire({
            title: `<span class="text-success"><i class="fas fa-check-circle me-1"></i>${t('val_all_valid_title')}</span>`,
            html: `
                <div class="validation-card-success text-start mb-2" style="direction: rtl;">
                    <div class="validation-item-row"><i class="fas fa-check-circle validation-item-icon"></i><span class="validation-item-text">${t('val_rule_all_subjects')}</span></div>
                    <div class="validation-item-row"><i class="fas fa-check-circle validation-item-icon"></i><span class="validation-item-text">${t('val_rule_no_dup')}</span></div>
                    <div class="validation-item-row"><i class="fas fa-check-circle validation-item-icon"></i><span class="validation-item-text">${t('val_rule_no_exceed')}</span></div>
                    <div class="validation-item-row"><i class="fas fa-check-circle validation-item-icon"></i><span class="validation-item-text">${t('val_rule_load_met')}</span></div>
                    <div class="validation-item-row"><i class="fas fa-check-circle validation-item-icon"></i><span class="validation-item-text">${t('val_rule_no_conflicts')}</span></div>
                    <div class="validation-item-row"><i class="fas fa-check-circle validation-item-icon"></i><span class="validation-item-text">${t('val_rule_no_missing')}</span></div>
                </div>
                ${restrictionsHTML}
            `,
            icon: 'success',
            confirmButtonText: t('btn_close'),
            width: '480px',
            customClass: { popup: 'swal-validation-compact swal2-modal-responsive' }
        });
    } else {
        let errorsHTML = `
            <div class="d-flex justify-content-between align-items-center mb-2 flex-wrap gap-2" style="direction: rtl;">
                <span class="badge bg-danger fs-6 py-1.5 px-2.5"><i class="fas fa-exclamation-triangle me-1"></i>${t('val_errors_found_title')}: ${validation.errors.length}</span>
                <div class="d-flex gap-1">
                    <button class="btn btn-outline-dark btn-sm fw-bold px-2 py-1 shadow-sm" style="font-size: 0.72rem;" onclick="Swal.close(); openSubjectRestrictionsModal();"><i class="fas fa-lock me-1 text-warning"></i>${t('btn_subject_restrictions')}</button>
                    ${validation.errors.length > 0 ? `<button class="btn btn-warning btn-sm fw-bold px-2 py-1 shadow-sm" style="font-size: 0.72rem;" onclick="autoFixAllTimetableErrors()"><i class="fas fa-magic me-1"></i>${t('val_fix_all_btn')}</button>` : ''}
                </div>
            </div>
            <div style="max-height: 320px; overflow-y: auto; direction: rtl;" class="text-start pe-1">
        `;

        validation.errors.forEach((err, idx) => {
            const isDuplicate = err.type === 'DAILY_DUPLICATE';
            const isLimit = err.type === 'DAILY_LIMIT';
            const isConflict = err.type === 'TEACHER_CONFLICT';

            errorsHTML += `
                <div class="card mb-2 border-danger shadow-sm" style="background: #fffafa; border-radius: 8px; overflow: hidden;">
                    <div class="card-header bg-danger bg-opacity-10 border-danger d-flex justify-content-between align-items-center py-1.5 px-2.5">
                        <div class="d-flex align-items-center gap-1.5">
                            <span class="badge bg-danger" style="font-size: 0.7rem;">${idx + 1}</span>
                            <strong class="text-danger" style="font-size: 0.8rem;"><i class="fas fa-exclamation-circle me-1"></i>${isConflict ? t('val_err_conflict') : translateSubjectName(err.subject)}</strong>
                        </div>
                        ${!isConflict ? `<button class="btn btn-xs btn-outline-primary bg-white fw-bold shadow-sm py-0.5 px-1.5" onclick="autoFixTimetableError(${idx})" style="border-radius: 4px; font-size: 0.68rem;"><i class="fas fa-wrench me-1"></i>${t('val_fix_single_btn')}</button>` : ''}
                    </div>
                    <div class="card-body p-2">
                        ${!isConflict ? `
                            <div class="row g-1 text-start" style="font-size: 0.72rem;">
                                <div class="col-6"><strong>${t('val_class_lbl')}:</strong> <span class="text-primary fw-bold">${err.className}</span></div>
                                <div class="col-6"><strong>${t('val_day_lbl')}:</strong> <span class="text-dark fw-bold">${err.dayName}</span></div>
                                <div class="col-6"><strong>${t('val_count_lbl')}:</strong> <span class="badge bg-danger">${err.count}</span></div>
                                <div class="col-6"><strong>${t('val_load_lbl')}:</strong> <span class="badge bg-success">${err.weeklyLoad}</span></div>
                                <div class="col-12 text-danger fw-bold mt-1 pt-1 border-top"><i class="fas fa-times-circle me-1"></i>${isDuplicate ? t('val_err_duplicate') : t('val_err_limit')}</div>
                            </div>
                        ` : `<div class="text-danger fw-bold" style="font-size: 0.72rem;">${err.message}</div>`}
                    </div>
                </div>
            `;
        });

        if (validation.missingCount > 0) {
            errorsHTML += `
                <div class="alert alert-warning p-1.5 mb-2 shadow-sm" style="border-radius: 8px; font-size: 0.75rem;">
                    <i class="fas fa-info-circle me-1"></i><strong>${t('val_err_missing')}:</strong> ${validation.missingCount} ${t('stat_total_periods')}
                </div>
            `;
        }

        errorsHTML += `</div>`;
        errorsHTML += restrictionsHTML;

        Swal.fire({
            title: `<span class="text-warning"><i class="fas fa-exclamation-circle me-1"></i>${t('val_title')}</span>`,
            html: errorsHTML,
            icon: 'warning',
            confirmButtonText: t('btn_close'),
            width: '520px',
            customClass: { popup: 'swal-validation-compact swal2-modal-responsive' }
        });
    }
}

function ttTryFastPlaceWithSwap(schedule, timetables, item, days, periodsCount, meta) {
    // 1. Direct empty slot
    const directSlots = ttCandidateSlots(schedule, timetables, item, days, periodsCount, meta);
    if (directSlots.length > 0) {
        ttPlaceItem(timetables, item, directSlots[0].dayIndex, directSlots[0].period);
        return true;
    }

    const teacherObj = schedule.teachers.find(t => t.name === item.teacher);
    const csKey = `${item.className}|||${item.subject}`;
    const weeklyLoad = meta.classSubjectLoad[csKey] || 1;
    const maxDaily = ttGetSubjectMaxDaily(weeklyLoad, days.length);

    // 2. High-speed 1-step swap: displace an item if it can find a free candidate slot
    for (let d = 0; d < days.length; d++) {
        const dayName = days[d];
        if (!ttSubjectCanTakeSlot(item.subject, dayName, null, schedule, item.className)) continue;
        if (ttSubjectDayLoad(timetables, item.className, d, item.subject) >= maxDaily) continue;

        for (let p = 1; p <= periodsCount; p++) {
            const occupied = timetables[item.className]?.[d]?.[p];
            // Never displace locked slots or same subject
            if (!occupied || occupied.subject === item.subject || occupied.locked) continue;
            if (!ttSubjectCanTakeSlot(item.subject, dayName, p, schedule, item.className)) continue;
            if (!ttTeacherCanTake(teacherObj, dayName, p)) continue;
            if (ttTeacherBusy(timetables, schedule.columns, item.teacher, d, p, item.className)) continue;

            const displacedItem = {
                className: item.className,
                subject: occupied.subject,
                teacher: occupied.teacher,
                id: occupied.id,
                locked: !!occupied.locked
            };

            delete timetables[item.className][d][p];

            // Candidate lookup for displaced item
            const relocationSlots = ttCandidateSlots(
                schedule,
                timetables,
                displacedItem,
                days,
                periodsCount,
                meta,
                `${item.className}|${d}|${p}`
            );

            if (relocationSlots.length > 0) {
                ttPlaceItem(timetables, displacedItem, relocationSlots[0].dayIndex, relocationSlots[0].period);
                ttPlaceItem(timetables, item, d, p);
                return true;
            }

            // Restore
            timetables[item.className][d][p] = occupied;
        }
    }

    // 3. 2-Step (2-hop) swap: displace occupied item 1, which in turn displaces occupied item 2 into an empty slot
    for (let d = 0; d < days.length; d++) {
        const dayName = days[d];
        if (!ttSubjectCanTakeSlot(item.subject, dayName, null, schedule, item.className)) continue;
        if (ttSubjectDayLoad(timetables, item.className, d, item.subject) >= maxDaily) continue;

        for (let p = 1; p <= periodsCount; p++) {
            const occupied1 = timetables[item.className]?.[d]?.[p];
            if (!occupied1 || occupied1.subject === item.subject || occupied1.locked) continue;
            if (!ttSubjectCanTakeSlot(item.subject, dayName, p, schedule, item.className)) continue;
            if (!ttTeacherCanTake(teacherObj, dayName, p)) continue;
            if (ttTeacherBusy(timetables, schedule.columns, item.teacher, d, p, item.className)) continue;

            const displaced1 = {
                className: item.className,
                subject: occupied1.subject,
                teacher: occupied1.teacher,
                id: occupied1.id,
                locked: !!occupied1.locked
            };

            delete timetables[item.className][d][p];

            const teacher1 = schedule.teachers.find(t => t.name === displaced1.teacher);
            const csKey1 = `${item.className}|||${displaced1.subject}`;
            const maxDaily1 = ttGetSubjectMaxDaily(meta.classSubjectLoad[csKey1] || 1, days.length);

            let twoHopSuccess = false;
            for (let d2 = 0; d2 < days.length && !twoHopSuccess; d2++) {
                if (ttSubjectDayLoad(timetables, item.className, d2, displaced1.subject) >= maxDaily1) continue;
                for (let p2 = 1; p2 <= periodsCount && !twoHopSuccess; p2++) {
                    if (d2 === d && p2 === p) continue;
                    const occupied2 = timetables[item.className]?.[d2]?.[p2];
                    if (!occupied2 || occupied2.locked || occupied2.subject === displaced1.subject) continue;
                    if (!ttSubjectCanTakeSlot(displaced1.subject, days[d2], p2, schedule, displaced1.className)) continue;
                    if (!ttTeacherCanTake(teacher1, days[d2], p2)) continue;
                    if (ttTeacherBusy(timetables, schedule.columns, displaced1.teacher, d2, p2, item.className)) continue;

                    const displaced2 = {
                        className: item.className,
                        subject: occupied2.subject,
                        teacher: occupied2.teacher,
                        id: occupied2.id,
                        locked: !!occupied2.locked
                    };

                    delete timetables[item.className][d2][p2];

                    const relocationSlots2 = ttCandidateSlots(
                        schedule,
                        timetables,
                        displaced2,
                        days,
                        periodsCount,
                        meta,
                        `${item.className}|${d2}|${p2}`
                    );

                    if (relocationSlots2.length > 0) {
                        ttPlaceItem(timetables, displaced2, relocationSlots2[0].dayIndex, relocationSlots2[0].period);
                        ttPlaceItem(timetables, displaced1, d2, p2);
                        ttPlaceItem(timetables, item, d, p);
                        twoHopSuccess = true;
                        return true;
                    }

                    // Restore occupied2
                    timetables[item.className][d2][p2] = occupied2;
                }
            }

            // Restore occupied1
            timetables[item.className][d][p] = occupied1;
        }
    }

    // 4. Cross-class teacher shift: When item.teacher is blocked in another class,
    // shift that teacher's lesson in the other class to an alternative slot in the other class
    for (let d = 0; d < days.length; d++) {
        const dayName = days[d];
        if (!ttSubjectCanTakeSlot(item.subject, dayName, null, schedule, item.className)) continue;
        if (ttSubjectDayLoad(timetables, item.className, d, item.subject) >= maxDaily) continue;

        for (let p = 1; p <= periodsCount; p++) {
            if (!ttSubjectCanTakeSlot(item.subject, dayName, p, schedule, item.className)) continue;
            if (!ttTeacherCanTake(teacherObj, dayName, p)) continue;

            const curInTargetClass = timetables[item.className]?.[d]?.[p];
            if (curInTargetClass && (curInTargetClass.locked || curInTargetClass.subject === item.subject)) continue;

            let blockingClass = null;
            for (const otherClass of schedule.columns) {
                if (otherClass !== item.className && timetables[otherClass]?.[d]?.[p]?.teacher === item.teacher) {
                    blockingClass = otherClass;
                    break;
                }
            }
            if (!blockingClass) continue;

            const otherLesson = timetables[blockingClass][d][p];
            if (otherLesson.locked) continue;

            const otherDisplaced = {
                className: blockingClass,
                subject: otherLesson.subject,
                teacher: otherLesson.teacher,
                id: otherLesson.id,
                locked: false
            };

            delete timetables[blockingClass][d][p];

            const otherSlots = ttCandidateSlots(
                schedule,
                timetables,
                otherDisplaced,
                days,
                periodsCount,
                meta,
                `${blockingClass}|${d}|${p}`
            );

            if (otherSlots.length > 0) {
                if (!curInTargetClass) {
                    ttPlaceItem(timetables, otherDisplaced, otherSlots[0].dayIndex, otherSlots[0].period);
                    ttPlaceItem(timetables, item, d, p);
                    return true;
                } else {
                    const localDisplaced = {
                        className: item.className,
                        subject: curInTargetClass.subject,
                        teacher: curInTargetClass.teacher,
                        id: curInTargetClass.id,
                        locked: false
                    };
                    delete timetables[item.className][d][p];
                    const localSlots = ttCandidateSlots(
                        schedule,
                        timetables,
                        localDisplaced,
                        days,
                        periodsCount,
                        meta,
                        `${item.className}|${d}|${p}`
                    );
                    if (localSlots.length > 0) {
                        ttPlaceItem(timetables, otherDisplaced, otherSlots[0].dayIndex, otherSlots[0].period);
                        ttPlaceItem(timetables, localDisplaced, localSlots[0].dayIndex, localSlots[0].period);
                        ttPlaceItem(timetables, item, d, p);
                        return true;
                    }
                    timetables[item.className][d][p] = curInTargetClass;
                }
            }

            timetables[blockingClass][d][p] = otherLesson;
        }
    }

    return false;
}

function ttTryPlaceWithSwap(schedule, timetables, item, days, periodsCount, meta) {
    return ttTryFastPlaceWithSwap(schedule, timetables, item, days, periodsCount, meta);
}

function ttSanitizeSeed(schedule, seedTimetables, requiredItems, days, periodsCount, meta) {
    const cleaned = ttCreateEmpty(schedule.columns);
    const requiredCounts = {};
    const usedCounts = {};

    requiredItems.forEach(item => {
        requiredCounts[ttReqKey(item)] = (requiredCounts[ttReqKey(item)] || 0) + 1;
    });

    schedule.columns.forEach(className => {
        for (let d = 0; d < days.length; d++) {
            for (let p = 1; p <= periodsCount; p++) {
                const currentItem = seedTimetables?.[className]?.[d]?.[p];
                if (!currentItem) continue;

                const candidate = {
                    className,
                    subject: currentItem.subject,
                    teacher: currentItem.teacher,
                    id: currentItem.id || `seed_${className}_${d}_${p}`,
                    locked: !!currentItem.locked
                };
                const key = ttReqKey(candidate);
                const teacherObj = schedule.teachers.find(t => t.name === candidate.teacher);

                if (!requiredCounts[key]) continue;
                if ((usedCounts[key] || 0) >= requiredCounts[key]) continue;

                // Locked items are always respected and preserved
                if (candidate.locked) {
                    ttPlaceItem(cleaned, candidate, d, p);
                    usedCounts[key] = (usedCounts[key] || 0) + 1;
                    continue;
                }

                if (!ttSubjectCanTakeSlot(candidate.subject, days[d], p, schedule, candidate.className)) continue;
                if (!ttCanPlaceSubject(cleaned, candidate.className, d, candidate.subject, meta, days.length)) continue;
                if (!ttTeacherCanTake(teacherObj, days[d], p)) continue;
                if (ttTeacherBusy(cleaned, schedule.columns, candidate.teacher, d, p)) continue;

                ttPlaceItem(cleaned, candidate, d, p);
                usedCounts[key] = (usedCounts[key] || 0) + 1;
            }
        }
    });

    const consumed = {};
    const remainingItems = requiredItems.filter(item => {
        const key = ttReqKey(item);
        const consumedCount = consumed[key] || 0;
        if (consumedCount < (usedCounts[key] || 0)) {
            consumed[key] = consumedCount + 1;
            return false;
        }
        return true;
    });

    return { timetables: cleaned, remainingItems };
}

function ttCountAssigned(timetables, columns, days, periodsCount) {
    let count = 0;
    if (!timetables) return 0;
    columns.forEach(c => {
        for (let d = 0; d < days.length; d++) {
            for (let p = 1; p <= periodsCount; p++) {
                if (timetables[c]?.[d]?.[p]) count++;
            }
        }
    });
    return count;
}

function ttDeepRepairUnassigned(schedule, timetables, requiredItems, days, periodsCount, meta) {
    let passes = 12;
    let changed = true;
    while (changed && passes > 0) {
        changed = false;
        passes--;

        const assignedList = [];
        schedule.columns.forEach(c => {
            if (timetables[c]) {
                for (let d = 0; d < days.length; d++) {
                    for (let p = 1; p <= periodsCount; p++) {
                        const cell = timetables[c][d]?.[p];
                        if (cell) assignedList.push({ className: c, teacher: cell.teacher, subject: cell.subject });
                    }
                }
            }
        });

        const unplaced = [];
        const copyAssigned = [...assignedList];
        requiredItems.forEach(req => {
            const idx = copyAssigned.findIndex(a => a.className === req.className && a.teacher === req.teacher && a.subject === req.subject);
            if (idx !== -1) {
                copyAssigned.splice(idx, 1);
            } else {
                unplaced.push(req);
            }
        });

        if (unplaced.length === 0) return true;

        for (const item of unplaced) {
            if (ttTryFastPlaceWithSwap(schedule, timetables, item, days, periodsCount, meta)) {
                changed = true;
                break;
            }
        }
    }
    return false;
}

async function ttRunAttemptAsync(schedule, baseTimetables, itemsToPlace, days, periodsCount, meta, iterations, onProgress = null) {
    let bestTimetables = JSON.parse(JSON.stringify(baseTimetables));
    const baseAssigned = ttCountAssigned(baseTimetables, schedule.columns, days, periodsCount);
    let bestRemainingCount = itemsToPlace.length;

    for (let iter = 0; iter < iterations; iter++) {
        // Yield to browser event loop every 8 iterations to keep UI completely responsive
        if (iter % 8 === 0) {
            if (onProgress) onProgress(iter, iterations);
            await new Promise(r => setTimeout(r, 0));
        }

        const tempTimetables = JSON.parse(JSON.stringify(baseTimetables));
        const strategy = iter % 4;
        const orderedItems = [...itemsToPlace].sort((a, b) => {
            if (strategy === 0) {
                const availA = meta.teacherAvailability[a.teacher] || 0;
                const availB = meta.teacherAvailability[b.teacher] || 0;
                if (availA !== availB) return availA - availB;
                const csKeyA = `${a.className}|||${a.subject}`;
                const csKeyB = `${b.className}|||${b.subject}`;
                return (meta.classSubjectLoad[csKeyB] || 0) - (meta.classSubjectLoad[csKeyA] || 0);
            } else if (strategy === 1) {
                const csKeyA = `${a.className}|||${a.subject}`;
                const csKeyB = `${b.className}|||${b.subject}`;
                const loadDiff = (meta.classSubjectLoad[csKeyB] || 0) - (meta.classSubjectLoad[csKeyA] || 0);
                if (loadDiff !== 0) return loadDiff;
                return (meta.teacherAvailability[a.teacher] || 0) - (meta.teacherAvailability[b.teacher] || 0);
            } else if (strategy === 2) {
                const cDiff = (meta.classLoad[b.className] || 0) - (meta.classLoad[a.className] || 0);
                if (cDiff !== 0) return cDiff;
                return (meta.teacherAvailability[a.teacher] || 0) - (meta.teacherAvailability[b.teacher] || 0);
            } else {
                return Math.random() - 0.5;
            }
        });

        orderedItems.forEach(item => {
            ttTryFastPlaceWithSwap(schedule, tempTimetables, item, days, periodsCount, meta);
        });

        let actualAssigned = ttCountAssigned(tempTimetables, schedule.columns, days, periodsCount);
        let newlyPlaced = actualAssigned - baseAssigned;
        let remainingCount = Math.max(0, itemsToPlace.length - newlyPlaced);

        if (remainingCount > 0 && remainingCount <= 8) {
            ttDeepRepairUnassigned(schedule, tempTimetables, itemsToPlace, days, periodsCount, meta);
            actualAssigned = ttCountAssigned(tempTimetables, schedule.columns, days, periodsCount);
            newlyPlaced = actualAssigned - baseAssigned;
            remainingCount = Math.max(0, itemsToPlace.length - newlyPlaced);
        }

        if (remainingCount < bestRemainingCount) {
            bestRemainingCount = remainingCount;
            bestTimetables = JSON.parse(JSON.stringify(tempTimetables));
            if (bestRemainingCount === 0) break;
        }
    }

    return {
        timetables: bestTimetables,
        remainingCount: bestRemainingCount
    };
}

function ttRunAttempt(schedule, baseTimetables, itemsToPlace, days, periodsCount, meta, iterations) {
    let bestTimetables = JSON.parse(JSON.stringify(baseTimetables));
    const baseAssigned = ttCountAssigned(baseTimetables, schedule.columns, days, periodsCount);
    let bestRemainingCount = itemsToPlace.length;

    for (let iter = 0; iter < iterations; iter++) {
        const tempTimetables = JSON.parse(JSON.stringify(baseTimetables));
        const strategy = iter % 4;
        const orderedItems = [...itemsToPlace].sort((a, b) => {
            if (strategy === 0) {
                const availA = meta.teacherAvailability[a.teacher] || 0;
                const availB = meta.teacherAvailability[b.teacher] || 0;
                if (availA !== availB) return availA - availB;
                const csKeyA = `${a.className}|||${a.subject}`;
                const csKeyB = `${b.className}|||${b.subject}`;
                return (meta.classSubjectLoad[csKeyB] || 0) - (meta.classSubjectLoad[csKeyA] || 0);
            } else if (strategy === 1) {
                const csKeyA = `${a.className}|||${a.subject}`;
                const csKeyB = `${b.className}|||${b.subject}`;
                const loadDiff = (meta.classSubjectLoad[csKeyB] || 0) - (meta.classSubjectLoad[csKeyA] || 0);
                if (loadDiff !== 0) return loadDiff;
                return (meta.teacherAvailability[a.teacher] || 0) - (meta.teacherAvailability[b.teacher] || 0);
            } else {
                return Math.random() - 0.5;
            }
        });

        orderedItems.forEach(item => {
            ttTryFastPlaceWithSwap(schedule, tempTimetables, item, days, periodsCount, meta);
        });

        let actualAssigned = ttCountAssigned(tempTimetables, schedule.columns, days, periodsCount);
        let newlyPlaced = actualAssigned - baseAssigned;
        let remainingCount = Math.max(0, itemsToPlace.length - newlyPlaced);

        if (remainingCount > 0 && remainingCount <= 8) {
            ttDeepRepairUnassigned(schedule, tempTimetables, itemsToPlace, days, periodsCount, meta);
            actualAssigned = ttCountAssigned(tempTimetables, schedule.columns, days, periodsCount);
            newlyPlaced = actualAssigned - baseAssigned;
            remainingCount = Math.max(0, itemsToPlace.length - newlyPlaced);
        }

        if (remainingCount < bestRemainingCount) {
            bestRemainingCount = remainingCount;
            bestTimetables = JSON.parse(JSON.stringify(tempTimetables));
            if (bestRemainingCount === 0) break;
        }
    }

    return {
        timetables: bestTimetables,
        remainingCount: bestRemainingCount
    };
}

function autoDistributeTimetable() {
    Swal.fire({
        title: t('auto_distribute_title'),
        text: t('auto_distribute_prompt'),
        icon: 'question',
        showCancelButton: true,
        confirmButtonText: t('confirm'),
        cancelButtonText: t('cancel')
    }).then(async (result) => {
        if (!result.isConfirmed) return;

        const schedule = allSchedules[activeScheduleName];
        const days = schedule.settings.workDays || ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
        const periodsCount = schedule.settings.periodsPerDay || 7;

        if (!schedule.timetables) schedule.timetables = {};

        let requiredItems = ttBuildRequiredItems(schedule);
        if (requiredItems.length === 0) {
            const isAr = (currentLang === 'ar');
            const { isConfirmed: runNisab } = await Swal.fire({
                title: t('result_title', 'ئەنجام'),
                text: isAr 
                    ? 'لا توجد حصص موزعة على الفصول والمعلمين حتى الآن. هل ترغب في إجراء التوزيع التلقائي للحصص وفق النصاب أولاً؟' 
                    : 'هیچ وانەیەک نەهاتیە دابەشکرن هەتا نوکە. ئایا دتەڤێت پێشتر دابەشکرنا ئۆتۆماتیکی یا نصابی بهێتە ئەنجامدان؟',
                icon: 'question',
                showCancelButton: true,
                confirmButtonText: isAr ? 'نعم، توزيع الحصص تلقائياً' : 'بەلێ، دابەش بکە',
                cancelButtonText: isAr ? 'إلغاء' : 'پاشگەزبوون'
            });
            if (runNisab) {
                await applyNisab();
            }
            return;
        }

        const meta = ttBuildMeta(schedule, days, periodsCount, requiredItems);
        const classCapacity = days.length * periodsCount;
        const warnings = [];

        schedule.columns.forEach(className => {
            const requiredCount = meta.classLoad[className] || 0;
            if (requiredCount > classCapacity) {
                warnings.push(`پولا ${className}: داواکاری ${requiredCount} حصەیە، بەڵام تەنها ${classCapacity} شوێن هەیە.`);
            }
        });

        schedule.teachers.forEach(teacher => {
            const requiredCount = meta.teacherLoad[teacher.name] || 0;
            const availableCount = meta.teacherAvailability[teacher.name] || 0;
            if (requiredCount > availableCount) {
                warnings.push(`ماموستا ${teacher.name}: ${requiredCount} حصەی هەیە، بەڵام تەنها ${availableCount} کاتە بەردەستە.`);
            }
        });

        // Show non-blocking loading spinner
        Swal.fire({
            title: `<span class="text-primary"><i class="fas fa-magic me-2"></i>${t('auto_distribute_title')}</span>`,
            html: `
                <div class="d-flex flex-column align-items-center my-3">
                    <div class="spinner-border text-primary mb-3" style="width: 3.5rem; height: 3.5rem;" role="status"></div>
                    <div class="fw-bold fs-6 text-dark" id="autoDistributeProgressText">سیستەم یێ ل باشترین دابەشکرنێ دگەڕیت...</div>
                </div>
            `,
            allowOutsideClick: false,
            allowEscapeKey: false,
            showConfirmButton: false,
            customClass: { popup: 'swal2-modal-responsive' }
        });

        await new Promise(r => setTimeout(r, 60)); // Yield to paint loading modal

        // Extract locked seeds from existing timetables so they are permanently preserved
        const lockedSeedTimetables = ttCreateEmpty(schedule.columns);
        let hasLockedSlots = false;
        schedule.columns.forEach(cName => {
            if (schedule.timetables?.[cName]) {
                for (let d in schedule.timetables[cName]) {
                    for (let p in schedule.timetables[cName][d]) {
                        const cell = schedule.timetables[cName][d][p];
                        if (cell && cell.locked) {
                            lockedSeedTimetables[cName][d][p] = { ...cell, locked: true };
                            hasLockedSlots = true;
                        }
                    }
                }
            }
        });

        let baseStartingTimetables = ttCreateEmpty(schedule.columns);
        let itemsToDistribute = requiredItems;

        if (hasLockedSlots) {
            const seed = ttSanitizeSeed(schedule, lockedSeedTimetables, requiredItems, days, periodsCount, meta);
            baseStartingTimetables = seed.timetables;
            itemsToDistribute = seed.remainingItems;
        }

        // 1. Run fast generation keeping locked seeds intact
        const fullCleanAttempt = await ttRunAttemptAsync(
            schedule,
            baseStartingTimetables,
            itemsToDistribute,
            days,
            periodsCount,
            meta,
            60
        );

        let chosenTimetables = fullCleanAttempt.timetables;
        let remaining = fullCleanAttempt.remainingCount;

        // 2. If any remaining, try fast sanitized seed wave
        if (remaining > 0) {
            const sanitizedSeed = ttSanitizeSeed(schedule, schedule.timetables || {}, requiredItems, days, periodsCount, meta);
            const seedAttempt = await ttRunAttemptAsync(
                schedule,
                sanitizedSeed.timetables,
                sanitizedSeed.remainingItems,
                days,
                periodsCount,
                meta,
                40
            );
            if (seedAttempt.remainingCount < remaining) {
                chosenTimetables = seedAttempt.timetables;
                remaining = seedAttempt.remainingCount;
            }
        }

        // 3. Post-repair wave for any difficult stubborn lessons
        if (remaining > 0) {
            ttDeepRepairUnassigned(schedule, chosenTimetables, requiredItems, days, periodsCount, meta);
        }

        const actualTotalAssigned = ttCountAssigned(chosenTimetables, schedule.columns, days, periodsCount);
        const actualRemaining = Math.max(0, requiredItems.length - actualTotalAssigned);

        schedule.timetables = chosenTimetables;
        saveData();
        renderTimetableGrid();

        let message = `هاتنە دابەشکرن ب سەرکەفتیانە: <strong>${actualTotalAssigned}</strong> وانە ژ کۆی <strong>${requiredItems.length}</strong>.<br>`;
        if (actualRemaining === 0) {
            message += `<span class="text-success fw-bold"><i class="fas fa-check-circle me-1"></i>هەمی وانە بێ کێشە و بێ چ دووبارەبوون هاتنە دابەشکرن!</span>`;
        } else {
            message += `<span class="text-warning fw-bold"><i class="fas fa-exclamation-triangle me-1"></i>ماوە: ${actualRemaining} وانە نەهاتنە جهـ گرتن ژبەر تێکچوونا دەمان یان وانەیێن قەدەغەکری.</span>`;
        }

        if (warnings.length > 0) {
            message += `<hr><div class="text-start small"><strong>هۆکارێن بەرتەنگکرنا خشتەی:</strong><ul>${warnings.slice(0, 6).map(item => `<li>${item}</li>`).join('')}</ul></div>`;
        }

        Swal.fire(t('result_title'), message, actualRemaining > 0 ? 'warning' : 'success');
    });
}

function validateTimetableSchedule(schedule = null) {
    if (!schedule) schedule = allSchedules[activeScheduleName];
    if (!schedule) return { isValid: false, errors: [], summary: {} };

    const days = schedule.settings?.workDays || ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
    const periodsCount = schedule.settings?.periodsPerDay || 7;
    const requiredItems = ttBuildRequiredItems(schedule);
    const meta = ttBuildMeta(schedule, days, periodsCount, requiredItems);
    const timetables = schedule.timetables || {};

    const errors = [];

    // 1. Check daily duplicates and limits for each class & subject
    schedule.columns.forEach(className => {
        const subjectsInClass = new Set();
        schedule.teachers.forEach(teacher => {
            if (teacher.classes?.[className]) {
                Object.keys(teacher.classes[className]).forEach(s => subjectsInClass.add(s));
            }
        });

        subjectsInClass.forEach(subject => {
            const csKey = `${className}|||${subject}`;
            const weeklyLoad = meta.classSubjectLoad[csKey] || 0;
            const maxDaily = ttGetSubjectMaxDaily(weeklyLoad, days.length);

            for (let d = 0; d < days.length; d++) {
                const count = ttSubjectDayLoad(timetables, className, d, subject);

                if (weeklyLoad >= 1 && weeklyLoad <= 5 && count > 1) {
                    errors.push({
                        type: 'DAILY_DUPLICATE',
                        className,
                        subject,
                        dayIndex: d,
                        dayName: days[d],
                        count,
                        maxAllowed: 1,
                        weeklyLoad,
                        message: `${t('val_class_lbl')} ${className} - ${t('val_subject_lbl')} ${translateSubjectName(subject)}: ${t('val_day_lbl')} ${days[d]} ${count} ${t('stat_total_periods')} (${t('val_load_lbl')}: ${weeklyLoad})`
                    });
                } else if (weeklyLoad >= 6 && weeklyLoad <= 10 && count > 2) {
                    errors.push({
                        type: 'DAILY_LIMIT',
                        className,
                        subject,
                        dayIndex: d,
                        dayName: days[d],
                        count,
                        maxAllowed: 2,
                        weeklyLoad,
                        message: `${t('val_class_lbl')} ${className} - ${t('val_subject_lbl')} ${translateSubjectName(subject)}: ${t('val_day_lbl')} ${days[d]} ${count} ${t('stat_total_periods')} (${t('val_load_lbl')}: ${weeklyLoad})`
                    });
                } else if (weeklyLoad > 10 && count > maxDaily) {
                    errors.push({
                        type: 'DAILY_LIMIT',
                        className,
                        subject,
                        dayIndex: d,
                        dayName: days[d],
                        count,
                        maxAllowed: maxDaily,
                        weeklyLoad,
                        message: `${t('val_class_lbl')} ${className} - ${t('val_subject_lbl')} ${translateSubjectName(subject)}: ${t('val_day_lbl')} ${days[d]} ${count} ${t('stat_total_periods')} (${t('val_load_lbl')}: ${weeklyLoad})`
                    });
                }
            }
        });
    });

    // 2. Check teacher conflicts
    schedule.teachers.forEach(teacher => {
        for (let d = 0; d < days.length; d++) {
            for (let p = 1; p <= periodsCount; p++) {
                const assignedClasses = [];
                schedule.columns.forEach(cName => {
                    if (timetables[cName]?.[d]?.[p]?.teacher === teacher.name) {
                        assignedClasses.push(cName);
                    }
                });
                if (assignedClasses.length > 1) {
                    errors.push({
                        type: 'TEACHER_CONFLICT',
                        teacherName: teacher.name,
                        dayIndex: d,
                        dayName: days[d],
                        period: p,
                        classes: assignedClasses,
                        message: `${t('col_teacher')} ${teacher.name}: ${days[d]} - ${t('day_period')} ${p} (${assignedClasses.join(', ')})`
                    });
                }
            }
        }
    });

    // 3. Check unassigned lessons
    let totalAssigned = 0;
    schedule.columns.forEach(cName => {
        if (timetables[cName]) {
            Object.values(timetables[cName]).forEach(dayObj => {
                totalAssigned += Object.keys(dayObj || {}).length;
            });
        }
    });
    const missingCount = Math.max(0, requiredItems.length - totalAssigned);

    return {
        isValid: errors.length === 0 && missingCount === 0,
        errors,
        missingCount,
        totalRequired: requiredItems.length,
        totalAssigned,
        days,
        periodsCount,
        meta
    };
}

function ttTryDirectSwapForDuplicate(schedule, className, badDayIndex, badPeriod, meta, days, periodsCount) {
    const timetables = schedule.timetables;
    const itemA = timetables[className]?.[badDayIndex]?.[badPeriod];
    if (!itemA) return false;

    const teacherA = schedule.teachers.find(t => t.name === itemA.teacher);
    const csKeyA = `${className}|||${itemA.subject}`;
    const maxDailyA = ttGetSubjectMaxDaily(meta.classSubjectLoad[csKeyA] || 1, days.length);

    // 1. First priority: Try empty slot on other days
    for (let d = 0; d < days.length; d++) {
        if (d === badDayIndex) continue;
        const currentCountAOnD = ttSubjectDayLoad(timetables, className, d, itemA.subject);
        if (currentCountAOnD >= maxDailyA) continue;

        for (let p = 1; p <= periodsCount; p++) {
            if (timetables[className]?.[d]?.[p]) continue; // Occupied
            if (!ttTeacherCanTake(teacherA, days[d], p)) continue;
            if (ttTeacherBusy(timetables, schedule.columns, itemA.teacher, d, p, className)) continue;

            delete timetables[className][badDayIndex][badPeriod];
            ttPlaceItem(timetables, itemA, d, p);
            return true;
        }
    }

    // 2. Second priority: Try direct mutual swap with occupied slot on other days
    for (let d = 0; d < days.length; d++) {
        if (d === badDayIndex) continue;
        const currentCountAOnD = ttSubjectDayLoad(timetables, className, d, itemA.subject);
        if (currentCountAOnD >= maxDailyA) continue;

        for (let p = 1; p <= periodsCount; p++) {
            const itemB = timetables[className]?.[d]?.[p];
            if (!itemB) continue;
            if (itemB.subject === itemA.subject) continue;

            const teacherB = schedule.teachers.find(t => t.name === itemB.teacher);

            if (!ttTeacherCanTake(teacherA, days[d], p)) continue;
            if (ttTeacherBusy(timetables, schedule.columns, itemA.teacher, d, p, className)) continue;

            if (!ttTeacherCanTake(teacherB, days[badDayIndex], badPeriod)) continue;
            if (ttTeacherBusy(timetables, schedule.columns, itemB.teacher, badDayIndex, badPeriod, className)) continue;

            // Check if itemB can be placed on badDayIndex
            const csKeyB = `${className}|||${itemB.subject}`;
            const maxDailyB = ttGetSubjectMaxDaily(meta.classSubjectLoad[csKeyB] || 1, days.length);
            const currentCountBOnBadDay = ttSubjectDayLoad(timetables, className, badDayIndex, itemB.subject);
            if (currentCountBOnBadDay >= maxDailyB) continue;

            // Perform direct swap!
            timetables[className][badDayIndex][badPeriod] = { ...itemB };
            timetables[className][d][p] = { ...itemA };
            return true;
        }
    }

    // 3. Third priority: Try 3-way chain swap (Item A -> Slot 2 -> Slot 3 -> Slot 1)
    for (let d2 = 0; d2 < days.length; d2++) {
        if (d2 === badDayIndex) continue;
        if (ttSubjectDayLoad(timetables, className, d2, itemA.subject) >= maxDailyA) continue;

        for (let p2 = 1; p2 <= periodsCount; p2++) {
            const itemB = timetables[className]?.[d2]?.[p2];
            if (!itemB || itemB.subject === itemA.subject) continue;
            if (!ttTeacherCanTake(teacherA, days[d2], p2)) continue;
            if (ttTeacherBusy(timetables, schedule.columns, itemA.teacher, d2, p2, className)) continue;

            const teacherB = schedule.teachers.find(t => t.name === itemB.teacher);

            for (let d3 = 0; d3 < days.length; d3++) {
                if (d3 === d2) continue;
                const csKeyB = `${className}|||${itemB.subject}`;
                const maxDailyB = ttGetSubjectMaxDaily(meta.classSubjectLoad[csKeyB] || 1, days.length);
                if (ttSubjectDayLoad(timetables, className, d3, itemB.subject) >= maxDailyB) continue;

                for (let p3 = 1; p3 <= periodsCount; p3++) {
                    const itemC = timetables[className]?.[d3]?.[p3];
                    if (!itemC) continue;
                    if (!ttTeacherCanTake(teacherB, days[d3], p3)) continue;
                    if (ttTeacherBusy(timetables, schedule.columns, itemB.teacher, d3, p3, className)) continue;

                    const teacherC = schedule.teachers.find(t => t.name === itemC.teacher);
                    if (!ttTeacherCanTake(teacherC, days[badDayIndex], badPeriod)) continue;
                    if (ttTeacherBusy(timetables, schedule.columns, itemC.teacher, badDayIndex, badPeriod, className)) continue;

                    const csKeyC = `${className}|||${itemC.subject}`;
                    const maxDailyC = ttGetSubjectMaxDaily(meta.classSubjectLoad[csKeyC] || 1, days.length);
                    if (ttSubjectDayLoad(timetables, className, badDayIndex, itemC.subject) >= maxDailyC) continue;

                    // Execute 3-way swap: A -> (d2, p2), B -> (d3, p3), C -> (badDayIndex, badPeriod)
                    timetables[className][badDayIndex][badPeriod] = { ...itemC };
                    timetables[className][d2][p2] = { ...itemA };
                    timetables[className][d3][p3] = { ...itemB };
                    return true;
                }
            }
        }
    }

    return false;
}



function promptPrintOptions(mode) {
    Swal.fire({
        title: t('lessons_per_page_title'),
        input: 'select',
        inputOptions: {
            '1': t('opt_1_per_page'),
            '2': t('opt_2_per_page'),
            '3': t('opt_3_per_page'),
            '4': t('opt_4_per_page')
        },
        inputValue: '1',
        showCancelButton: true,
        confirmButtonText: t('btn_print'),
        cancelButtonText: t('cancel')
    }).then((result) => {
        if (result.isConfirmed) {
            const perPage = parseInt(result.value);
            setTimeout(() => {
                if (mode === 'class') printClassTimetables(perPage);
                else if (mode === 'teacher') printTeacherTimetables(perPage);
            }, 300);
        }
    });
}

function promptMasterPrintOptions(mode) {
    Swal.fire({
        title: t('print_layout_style'),
        text: t('orientation_prompt_text'),
        input: 'select',
        inputOptions: {
            'landscape': t('opt_landscape'),
            'portrait': t('opt_portrait')
        },
        inputValue: 'landscape',
        showCancelButton: true,
        confirmButtonText: t('btn_print'),
        cancelButtonText: t('cancel')
    }).then((result) => {
        if (!result.isConfirmed) return;
        const orientation = result.value || 'landscape';
        setTimeout(() => {
            if (mode === 'class') printMasterTimetable(orientation);
            if (mode === 'teacher') printMasterTeacherTimetable(orientation);
        }, 300);
    });
}

function promptMasterHtmlDownload(mode) {
    Swal.fire({
        title: t('html_save_style'),
        text: t('orientation_prompt_text'),
        input: 'select',
        inputOptions: {
            'landscape': t('opt_landscape'),
            'portrait': t('opt_portrait')
        },
        inputValue: 'landscape',
        showCancelButton: true,
        confirmButtonText: t('download_html'),
        cancelButtonText: t('cancel')
    }).then((result) => {
        if (!result.isConfirmed) return;
        if (mode === 'class') downloadMasterTimetableHTML(result.value);
        if (mode === 'teacher') downloadMasterTeacherTimetableHTML(result.value);
    });
}

function downloadCurrentDistributionHTML() {
    const html = getCurrentDistributionHTML();
    if (!html) { showToast('هیچ خشتەیەك نیە بۆ هەڵگرتن.', 'error'); return; }
    downloadHTMLFile(`distribution_${activeScheduleName}`, html, { filename: `distribution_${sanitizeDownloadFileName(activeScheduleName)}.html` });
}

function downloadComprehensiveDistributionHTML() {
    const html = getComprehensiveDistributionHTML();
    if (!html) { showToast('هیچ ماموستایەك نیە بۆ هەڵگرتن.', 'error'); return; }
    downloadHTMLFile(`teachers_report_${activeScheduleName}`, html, { filename: `teachers_report_${sanitizeDownloadFileName(activeScheduleName)}.html` });
}

function downloadSimpleDistributionHTML() {
    const html = getSimpleDistributionHTML();
    if (!html) { showToast('هیچ ماموستایەك نیە بۆ هەڵگرتن.', 'error'); return; }
    downloadHTMLFile(`simple_distribution_${activeScheduleName}`, html, { filename: `simple_distribution_${sanitizeDownloadFileName(activeScheduleName)}.html` });
}

function downloadCurrentTimetableHTML() {
    const mode = document.querySelector('input[name="ttViewMode"]:checked')?.value || 'class';
    if (mode === 'substitute') {
        downloadSubstituteHTML('current');
        return;
    }
    if (mode === 'master') {
        downloadMasterTimetableHTML('landscape');
        return;
    }
    if (mode === 'master_teacher') {
        downloadMasterTeacherTimetableHTML('landscape');
        return;
    }
    if (mode === 'class') {
        const classSelect = document.getElementById('timetableClassSelect');
        const selectedClass = classSelect ? classSelect.value : '';
        if (selectedClass && selectedClass !== 'all_classes') {
            downloadHTMLFile(`timetable_${selectedClass}_${activeScheduleName}`, `<div class="table-responsive">${buildSingleClassTimetableHTML(selectedClass, 1)}</div>`, { filename: `timetable_${sanitizeDownloadFileName(selectedClass)}_${sanitizeDownloadFileName(activeScheduleName)}.html` });
            return;
        }
    }
    if (mode === 'teacher') {
        const teacherSelect = document.getElementById('timetableTeacherSelect');
        const selectedTeacher = teacherSelect ? teacherSelect.value : '';
        if (selectedTeacher && selectedTeacher !== 'all_teachers') {
            downloadHTMLFile(`timetable_${selectedTeacher}_${activeScheduleName}`, `<div class="table-responsive">${buildSingleTeacherTimetableHTML(selectedTeacher, 1)}</div>`, { filename: `timetable_${sanitizeDownloadFileName(selectedTeacher)}_${sanitizeDownloadFileName(activeScheduleName)}.html` });
            return;
        }
    }
    const container = document.getElementById("timetableGridContainer");
    if (!container || !container.innerHTML.trim()) { showToast('هیچ خشتەیەك نیە بۆ هەڵگرتن.', 'error'); return; }
    const clone = container.cloneNode(true);
    clone.querySelectorAll(".no-print").forEach(el => el.remove());
    clone.querySelectorAll("input, button, select").forEach(el => el.remove());
    downloadHTMLFile(`timetable_${activeScheduleName}`, `<div class="table-responsive">${clone.innerHTML}</div>`, { filename: `timetable_${sanitizeDownloadFileName(activeScheduleName)}.html` });
}

function printClassTimetables(perPage = 1) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !schedule.columns || schedule.columns.length === 0) return;

    let containerStyle = '';
    let itemStyle = 'margin-bottom: 0; page-break-inside: avoid; width: 100%;';

    if (perPage === 4) {
        containerStyle = 'display: flex; flex-wrap: wrap; justify-content: space-between; align-content: space-between; width: 100%; box-sizing: border-box;';
        itemStyle = 'width: 49%; margin-bottom: 8px; page-break-inside: avoid; overflow: hidden;';
    } else if (perPage === 3) {
        containerStyle = 'display: flex; flex-direction: column; justify-content: space-between; width: 100%;';
        itemStyle = 'width: 100%; margin-bottom: 10px; page-break-inside: avoid;';
    } else if (perPage === 2) {
        containerStyle = 'display: flex; flex-direction: column; justify-content: space-between; width: 100%;';
        itemStyle = 'width: 100%; margin-bottom: 16px; page-break-inside: avoid;';
    }

    const principalName = schedule.settings?.principalName || '';
    let sigHtml = '';
    if (principalName && perPage === 1) {
        sigHtml = `<div style="display: block; width: 100%; margin-top: 8px; clear: both; page-break-inside: avoid;"><div style="float: left; text-align: center; width: 220px; direction: rtl; margin-left: 15px;"><p class="mb-0" style="font-size: 8.5pt; font-weight: bold; margin-bottom: 2px;">${t('signature_approved_by') || 'المصادقة'}</p><p class="fw-bold mb-0" style="font-size: 8.5pt; margin-bottom: 2px;">${t('signature_principal') || 'مدير المدرسة'}</p><p class="fw-bold mb-0" style="font-size: 8.5pt; margin-top: 2px; margin-bottom: 0;">${principalName}</p></div><div style="clear: both;"></div></div>`;
    }

    const chunks = [];
    for (let i = 0; i < schedule.columns.length; i += perPage) {
        chunks.push(schedule.columns.slice(i, i + perPage));
    }

    let html = '';
    chunks.forEach((chunk, chunkIndex) => {
        const breakClass = chunkIndex > 0 ? 'page-break' : '';
        html += `<div class="${breakClass}" style="padding: 4px; ${containerStyle}">`;
        chunk.forEach(className => {
            html += `<div style="${itemStyle}">${buildSingleClassTimetableHTML(className, perPage)}${sigHtml}</div>`;
        });
        html += `</div>`;
    });
    printWithContent('خشتەیێن هەمی پولان', html, { orientation: (perPage === 4 || perPage === 1) ? 'landscape' : 'portrait' });
}

function printTeacherTimetables(perPage = 1) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;

    let containerStyle = '';
    let itemStyle = 'margin-bottom: 0; page-break-inside: avoid; width: 100%;';

    if (perPage === 4) {
        containerStyle = 'display: flex; flex-wrap: wrap; justify-content: space-between; align-content: space-between; width: 100%; box-sizing: border-box;';
        itemStyle = 'width: 49%; margin-bottom: 8px; page-break-inside: avoid; overflow: hidden;';
    } else if (perPage === 3) {
        containerStyle = 'display: flex; flex-direction: column; justify-content: space-between; width: 100%;';
        itemStyle = 'width: 100%; margin-bottom: 10px; page-break-inside: avoid;';
    } else if (perPage === 2) {
        containerStyle = 'display: flex; flex-direction: column; justify-content: space-between; width: 100%;';
        itemStyle = 'width: 100%; margin-bottom: 16px; page-break-inside: avoid;';
    }

    const validTeachers = schedule.teachers.filter(teacher => {
        const workload = schedule.columns.reduce((s, c) => s + (teacher.classes?.[c] ? Object.values(teacher.classes[c]).reduce((a, b) => a + parseInt(b, 10), 0) : 0), 0);
        return workload > 0;
    });

    if (validTeachers.length === 0) { showToast('هیچ ماموستایەك نینە خشتە هەبت', 'error'); return; }

    const principalName = schedule.settings?.principalName || '';
    let sigHtml = '';
    if (principalName && perPage === 1) {
        sigHtml = `<div style="display: block; width: 100%; margin-top: 8px; clear: both; page-break-inside: avoid;"><div style="float: left; text-align: center; width: 220px; direction: rtl; margin-left: 15px;"><p class="mb-0" style="font-size: 8.5pt; font-weight: bold; margin-bottom: 2px;">${t('signature_approved_by') || 'المصادقة'}</p><p class="fw-bold mb-0" style="font-size: 8.5pt; margin-bottom: 2px;">${t('signature_principal') || 'مدير المدرسة'}</p><p class="fw-bold mb-0" style="font-size: 8.5pt; margin-top: 2px; margin-bottom: 0;">${principalName}</p></div><div style="clear: both;"></div></div>`;
    }

    const chunks = [];
    for (let i = 0; i < validTeachers.length; i += perPage) {
        chunks.push(validTeachers.slice(i, i + perPage));
    }

    let html = '';
    chunks.forEach((chunk, chunkIndex) => {
        const breakClass = chunkIndex > 0 ? 'page-break' : '';
        html += `<div class="${breakClass}" style="padding: 4px; ${containerStyle}">`;
        chunk.forEach(teacher => {
            html += `<div style="${itemStyle}">${buildSingleTeacherTimetableHTML(teacher, perPage)}${sigHtml}</div>`;
        });
        html += `</div>`;
    });
    printWithContent('خشتەیێن ماموستایان', html, { orientation: (perPage === 4 || perPage === 1) ? 'landscape' : 'portrait' });
}

function downloadMasterTimetableHTML(pageOrientation = 'landscape') {
    const schedule = allSchedules[activeScheduleName];
    let html = '';
    const days = schedule.settings.workDays || ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
    const periodsCount = schedule.settings.periodsPerDay || 7;
    const totalClasses = schedule.columns.length;
    const rowHeight = pageOrientation === 'portrait'
        ? Math.min(55, Math.max(34, Math.floor(950 / Math.max(1, totalClasses))))
        : Math.min(42, Math.max(29, Math.floor(660 / Math.max(1, totalClasses))));

    html += `<h1 class="text-center mb-4">${t('master_class_title')}</h1>`;
    html += `<div class="table-responsive"><table class="table table-bordered text-center align-middle preserve-table-styles" style="font-size: 7pt; width: 100% !important; max-width: 100% !important; min-width: 0 !important; table-layout: fixed !important; border: 1.5px solid #000 !important; border-collapse: collapse !important; margin: 0 auto !important;">
                    <thead class="table-light">
                        <tr>
                            <th rowspan="2" class="align-middle" style="width: 38px !important; min-width: 38px !important; max-width: 38px !important; padding: 2px 1px !important; border: 1.5px solid #000 !important; background: #e2e8f0 !important; color: #000 !important; font-weight: 800; font-size: 7.5pt;">${t('col_class') || 'الصف'}</th>`;
    for (let d = 0; d < days.length; d++) html += `<th colspan="${periodsCount}" style="border: 1.5px solid #000 !important; background: #f1f5f9 !important; color: #000 !important; font-weight: 900; font-size: 8pt; padding: 3px 1px; height: 24px;">${days[d]}</th>`;
    html += `</tr><tr>`;
    for (let d = 0; d < days.length; d++) {
        for (let p = 1; p <= periodsCount; p++) html += `<th style="padding: 2px 1px; border: 1px solid #000 !important; background: #e2e8f0 !important; color: #000 !important; font-weight: 800; font-size: 7.5pt; height: 20px;">${p}</th>`;
    }
    html += `</tr></thead><tbody>`;

    schedule.columns.forEach(className => {
        html += `<tr style="height: ${rowHeight}px;"><td style="width: 38px !important; min-width: 38px !important; max-width: 38px !important; padding: 2px 1px; font-weight: 900; font-size: 9pt; text-align: center; border: 1px solid #000 !important; background: #f8fafc; height: ${rowHeight}px; vertical-align: middle;">${className}</td>`;
        for (let d = 0; d < days.length; d++) {
            for (let p = 1; p <= periodsCount; p++) {
                const item = schedule.timetables?.[className]?.[d]?.[p];
                html += `<td style="padding: 2px 0.5px; overflow: hidden; vertical-align: middle; text-align: center; border: 1px solid #000 !important; height: ${rowHeight}px; min-height: ${rowHeight}px;">${item ? formatMasterCellContent(item.subject, item.teacher) : ''}</td>`;
            }
        }
        html += `</tr>`;
    });
    html += `</tbody></table></div>`;
    downloadHTMLFile(`master_classes_${activeScheduleName}`, html, { orientation: pageOrientation, filename: `master_classes_${sanitizeDownloadFileName(activeScheduleName)}_${pageOrientation}.html` });
}

