// Period / Bell Supervision Operations & Auto-Distribution
// -----------------------------------------------------------------------------

// Add a supervisor to a specific period on a day
function addPeriodSupervisionSlot(dayIndex, period, teacherId) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;
    const supData = getSupervisionData();
    supData.periodAssignments = supData.periodAssignments || {};
    supData.periodAssignments[dayIndex] = supData.periodAssignments[dayIndex] || {};
    supData.periodAssignments[dayIndex][period] = supData.periodAssignments[dayIndex][period] || [];

    const teacher = schedule.teachers?.find(t => t.id === teacherId);
    if (!teacher) return;

    const locations = getSupervisionDefaultLocations();
    const slotIdx = supData.periodAssignments[dayIndex][period].length;

    supData.periodAssignments[dayIndex][period].push({
        teacherId: teacher.id,
        teacherName: teacher.name,
        location: locations[slotIdx % locations.length]
    });

    saveData();
    renderSupervisionTab();
}
window.addPeriodSupervisionSlot = addPeriodSupervisionSlot;

// Change teacher for a specific period slot
function changePeriodSupervisionSlot(dayIndex, period, slotIndex, newTeacherId) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;
    const supData = getSupervisionData();
    const list = supData.periodAssignments?.[dayIndex]?.[period];
    if (!list || !list[slotIndex]) return;

    const newTeacher = schedule.teachers?.find(t => t.id === newTeacherId);
    if (!newTeacher) return;

    list[slotIndex].teacherId = newTeacher.id;
    list[slotIndex].teacherName = newTeacher.name;

    saveData();
    renderSupervisionTab();
}
window.changePeriodSupervisionSlot = changePeriodSupervisionSlot;

// Remove supervisor from a period slot
function removePeriodSupervisionSlot(dayIndex, period, slotIndex) {
    const supData = getSupervisionData();
    const list = supData.periodAssignments?.[dayIndex]?.[period];
    if (list) {
        list.splice(slotIndex, 1);
        saveData();
        renderSupervisionTab();
    }
}
window.removePeriodSupervisionSlot = removePeriodSupervisionSlot;

